import type { BChap } from '../types';
const C: BChap[] = [{"v":["Блажен муж, що не йде на раду нечестивих, і на путь грішників не стає, і на зборищі губителів не сидить.","Але в Законі Господнім воля його, і Закону Його повчається день і ніч.","І буде він як дерево, посаджене при витоках вод, що плоди свої дає в час свій і лист його не опадає, а все, що він робитиме, буде успішним.","Не так нечестиві, [не так]: вони як порох, що вітер змітає [з лиця землі].","Тому не встоять* нечестиві на суді, і грішники на зібранні праведних.","Бо знає Господь путь праведних, а путь нечестивих загине."],"h":"Псалом Давида (який у євреїв не надписаний)","x":{"1":"25.25.4|32.15.17|26.10.30","2":"5.1.8","3":"25.91.13|32.17.8","4":"24.21.18|31.29.5","5":"50.25.32","6":"44.1.7|53.10.14|72.2.19"},"n":{"5":["У слов’янському перекладі: цього ради не воскреснуть…"]}},{"v":["Навіщо бунтуються народи і люди замишляють марне?","Повстають царі землі, і князі змовляються разом проти Господа і проти Христа Його.","«Розірвемо, кажуть, пута їхні й скинемо з себе ярмо їхнє».","Той, Хто живе на небесах, посміється з них, Господь осоромить їх.","Тоді Він заговорить до них у гніві Своїм і обуренням Своїм розжене їх.","Я ж поставлений від Нього Царем над Сионом — горою святою Його.","Сповіщаю волю Господню: Господь сказав до Мене: «Ти Син Мій, Я нині породив Тебе».","«Проси у Мене, і дам Тобі народи у спадщину Твою і краї землі у володіння Твоє.","Будеш пасти їх жезлом залізним і, як посуд глиняний, розіб’єш їх».","Отже, нині зрозумійте, царі, навчіться, всі судді землі.","Служіть Господу зі страхом і радійте [Йому] з трепетом.","Вшануйте Сина, щоб не прогнівався Господь і щоб не загинули ви, зійшовши з путі праведної, бо скоро запалає гнів Його. Блаженні всі, хто надіється на Нього."],"h":"Псалом Давида (Пророчий про Христа)","x":{"1":"54.4.25","4":"4.28.63|26.1.26","6":"25.92.1|53.18.37|75.12.22","7":"54.13.33|75.1.5|75.5.5","8":"25.21.28","9":"76.2.27|76.19.15","10":"29.6.2","12":"25.33.9|26.16.20|31.30.18|56.2.6"}},{"v":["Псалом Давида, коли він втікав від Авессалома, сина свого.","Господи, як намножилося напасників моїх, многі постають на мене,","многі кажуть душі моїй: «Нема спасіння йому в Бозі його».","Ти ж, Господи, заступник мій єси, слава моя, Ти возносиш голову мою.","Голосом моїм до Господа воззвав, і Він почув мене з гори святої Своєї.","Я лягаю, і сплю, і встаю, бо Господь заступить мене.","Не убоюся я тьми людей, що звідусіль нападають на мене.","Воскресни, Господи, спаси мене, Боже мій, бо Ти уразив усіх, що даремно ворогують зі мною, зуби грішників сокрушив єси.","Господнім є спасіння, і на людей Твоїх благословення Твоє."],"x":{"1":"9.15.14","4":"25.27.7","7":"52.12.4","9":"31.43.11|38.13.4"}},{"v":["Начальнику хору. На струнних інструментах. Псалом Давида.","Коли взиваю я, почуй мене, Боже правди моєї. В тісноті Ти давав мені простір. Помилуй мене і почуй молитву мою.","Сини людські! Доки будете ганьбити славу мою? Нащо любите марноту і шукаєте неправди?","Знайте, що Господь обрав для Себе преподобного Свого. Господь почує мене, коли я взиватиму до Нього.","Гніваючись, не зогрішайте, роздумуйте в серцях ваших, на постелях ваших заспокойтеся.","Приносьте жертву правди і уповайте на Господа.","Багато хто говорить: «хто покаже нам благо?» Ти явив нам світло лиця Твого, Господи.","Ти дав веселість в серці моїм; від плоду пшениці, вина [та єлею] вона примножилася.","В мирі я лягаю і сплю, бо Ти єдиний, Господи, Хто вселив у мене надію на життя."],"x":{"2":"25.3.2","3":"24.27.12","5":"66.4.26","6":"25.50.19|25.61.9","7":"25.30.17|50.6.10","9":"24.11.19"}},{"v":["Начальнику хору. На духових інструментах. Псалом Давида.","Господи, почуй слова мої, зглянься на благання мої.","Вислухай голос моління мого, Царю мій і Боже мій, бо до Тебе молюся я,","Господи! Зранку почуй голос мій, зранку стану я перед Тобою і буду чекати.","Бо Ти Бог, що не хочеш беззаконня, і не оселиться з Тобою лукавий.","Не залишаться нечестиві перед очима Твоїми, Ти зненавидів усіх, що чинять беззаконня.","Ти погубиш усіх, хто говорить неправду. Кровожерним і підступним гидує Господь.","Я ж з великої милости Твоєї увійду в дім Твій, поклонюся до храму святого Твого зі страхом перед Тобою.","Господи, настав мене правдою Твоєю, ворогів моїх заради виправ дорогу мою перед Тобою.","Бо нема істини в устах їхніх, серце їхнє лукаве, гріб відкритий — гортань їх; язиком своїм облещують.","Осуди їх, Боже, нехай відпадуть від намірів своїх, за безліч нечестя їхнього відкинь їх, бо вони повстали проти Тебе, Господи.","І нехай звеселяться всі, що уповають на Тебе, і повіки радіють. Ти оселишся між ними, і будуть хвалитися Тобою ті, що люблять ім’я Твоє.","Бо Ти благословляєш праведника, Господи, і благоволінням, наче щитом, покриваєш його."],"x":{"2":"25.4.2|25.16.1","3":"25.83.4","5":"4.32.4|26.3.32|53.9.31","6":"65.5.21","7":"25.54.24|31.1.15","10":"62.3.13"}},{"v":["Начальнику хору. На восьмиструнних інструментах. Псалом Давида.","Господи, не суди мене в ярості Твоїй і не карай мене в гніві Твоїм.","Помилуй мене, Господи, бо я немічний, і зціли мене, Господи, бо стривожилися кості мої.","І душа моя дуже стривожена. А Ти ж, Господи, доки?","Зглянься, Господи, і визволи душу мою, спаси мене ради милости Твоєї.","Бо хто ж після смерти буде згадувати Тебе? І у гробі хто ж буде славити Тебе?","Я втомився від зітхання мого; кожної ночі обмиваю ложе моє сльозами моїми, зрошую ними постіль мою.","Висохло від печалі око моє. Змарніло від усіх ворогів лице моє.","Відступіть від мене всі, хто чинить беззаконня, бо почув Господь голос плачу мого!","Почув Господь благання моє, Господь молитву мою прийняв.","Нехай осоромляться і устрашаться всі вороги мої і нехай з соромом побіжать і зникнуть дуже скоро."],"x":{"2":"25.37.2|32.10.24","6":"25.29.10","8":"24.17.7","9":"25.118.115|50.7.23","11":"25.34.4"}},{"v":["Плачевна пісня Давида, яку він співав Господу з приводу Хуса, сина Веніамінового.","Господи, Боже мій! Я на Тебе надіюся, спаси мене і від усіх гонителів моїх визволи мене.","Щоб ворог не схопив, як лев, душу мою, коли нема визволителя [і спасителя].","Господи, Боже мій! Якщо я вчинив щось недобре, якщо є неправда в руках моїх,","якщо я відплатив злом приятелям моїм або чинив зло тому, хто без причини ворогував проти мене,","то нехай ворог переслідує душу мою, нехай настигне її, втопче в землю життя моє і славу мою кине в порох.","Встань, Господи, у гніві Твоїм, піднесися проти лютування ворогів моїх. Устань, Господи, Боже мій, на суд, що заповідав Ти.","І сонм народів оточить Тебе, над ним високо піднесись.","Господь судить народи. Суди мене, Господи, за правдою моєю і за невинністю моєю.","Нехай припиниться злоба грішних, а праведника підкріпи, бо Ти, Боже праведний, знаєш серця й думки.","Поміч моя від Бога, Який спасає праведних серцем.","Бог — Суддя праведний, [непохитний, довготерпеливий] і не посилає гніву щодня.","Коли ж хто не кається, Він гострить меч Свій, готує зброю Свою і направляє на нього.","Готує для нього лук; стріли Свої робить палючими.","Ось нечестивий захворів на неправду, зачав злобу і породив беззаконня.","Копав яму, і викопав її, і впав у ту яму, яку сам приготував.","І повернеться злоба його на голову його, і неправда його на тім’я його впаде.","Прославлятиму Господа за правду Його і величатиму ім’я Господа Всевишнього."],"x":{"4":"24.31.7","5":"8.24.7","9":"0.18.25|25.25.1","10":"8.16.7|12.28.9|32.11.20|32.17.10|32.20.12|76.2.23","13":"33.2.4|33.3.12","15":"24.15.35|31.59.4","16":"25.9.16|25.56.7|26.5.22","17":"17.4.5|25.139.10"}},{"v":["Начальнику хору. На гефському інструменті. Псалом Давида (пророчий).","Господи Боже наш, яке величне ім’я Твоє по всій землі! Слава Твоя піднеслася вище небес!","Із уст дітей і немовлят вчинив єси хвалу перед ворогами Твоїми, щоб знищити ворога і месника.","Коли погляну на небо — діло рук Твоїх, на місяць і зорі, які Ти поставив,","то що є людина, що Ти пам’ятаєш про неї, і син людський, що Ти опікуєшся ним?","Ти створив його мало чим меншим за ангелів, славою й честю увінчав його.","І поставив його над творінням рук Твоїх; все підкорив під ноги його:","овець і волів усіх, ще й звірів польових;","птахів небесних і риб морських, що ходять стежками морськими.","Господи, Боже наш, яке величне ім’я Твоє по всій землі!"],"x":{"2":"25.109.1","3":"50.21.16","5":"24.7.17|25.143.3|75.2.6","7":"0.1.28|0.9.2|63.15.27"}},{"v":["Начальнику хору. Після смерти Лабена. Псалом Давида.","Славитиму [Тебе], Господи, всім серцем моїм, розповідатиму про всі чудеса Твої.","Буду веселитися й хвалитися Тобою, буду співати імені Твоєму, Всевишній.","Ось повернули назад вороги мої, знесилилися й загинули перед лицем Твоїм.","Бо Ти вчинив суд мій і справу мою; Ти сів на Престолі, Суддя праведний.","Ти покарав народи, знищив нечестивого, стер ім’я їхнє на віки віків.","У ворога не вистачило зброї, міста зруйнував Ти, і згинула пам’ять про нього.","Господь же перебуває повік. Він приготував для суду Престіл Свій.","Він буде судити вселенну за правдою, розсудить народи за справедливістю.","І буде Господь пристановищем пригнобленому і захистом у скорботі.","І будуть надіятися на Тебе всі, хто знає ім’я Твоє, бо Ти не покинеш тих, хто шукає Тебе, Господи.","Співайте Господу, що живе на Сионі, сповіщайте між народами про діла Його.","Бо Він карає за пролиту кров, пам’ятає її і не забуде плачу пригноблених.","Помилуй мене, Господи, споглянь на приниження моє від ворогів моїх, Ти, що підняв мене від воріт смерти;","щоб я звіщав усі хвали Твої у воротах дочки Сионової. Буду радіти спасінню Твоєму.","Попадали народи в яму, яку викопали, в сітці, яку потай поставили, заплуталася нога їхня.","Пізнається Господь за судом Його, який Він звершує: нечестивець заплутався у ділах рук своїх.","Нехай зійдуть грішники в пекло — всі народи, що забувають Бога.","Бо не назавжди буде забутий убогий, надія покривджених не загине.","Встань, Господи, щоб не підносилася людина, нехай перед лицем Твоїм приймуть суд усі народи.","Постав, Господи, над ними страх Твій, щоб зрозуміли народи, що вони тільки люди.","Чому Ти, Господи, стоїш далеко і не являєш Себе в час скорботи?","В гордині своїй нечестивий пригноблює вбогого; нехай вони будуть уловлені хитрощами, які самі придумують.","Бо грішник хвалиться похотями душі своєї, і гнобитель ублажає себе.","В гордині своїй грішник не визнає Бога, каже він: «Не покарає», бо думає він, що Бога нема.","Повсякчасно шляхи його оскверняються. Суди Твої далекі для нього. На ворогів своїх дивиться зневажливо.","Каже він у серці своїм: «Не похитнуся, з роду в рід не зазнаю лиха».","Уста його повні прокльонів, підступів та лукавства; на язиці його мука та злоба.","Він сидить у засідці на краю осель, щоб таємно вбити неповинного, очі його підглядають за бідними.","Підстерігає по закутках, як лев у лігві своїм, щоб схопити бідного; хапає і тягне в сіті свої.","Припадає до землі, пригинається, і бідні потрапляють у міцні лапи його.","Каже він у серці своїм: «Забув Бог, відвернув лице Своє і не побачить ніколи».","Воскресни, Господи Боже [мій], нехай піднесеться рука Твоя, і не забудь убогих [Твоїх до кінця].","Чому нечестивий зневажає Бога і каже в серці своїм: «Бог не бачить»?","Ти ж бачиш, бо Ти споглядаєш на страждання та пригноблення, щоб відплатити рукою Твоєю. До Тебе вдається бідний, і сироті Ти будь захистом.","Зломи силу нечестивого й лукавого так, щоб шукати і не знайти злодіянь його.","Господь — Цар на віки віків, а язичники згинуть з землі Його.","Господи, Ти чуєш бажання вбогих, підкріпи серце їхнє, відкрий вухо Твоє,","щоб учинити праведний суд сироті й пригнобленому, щоб не лякала їх людина на землі."],"x":{"3":"25.30.8","6":"9.22.15|25.33.17|26.10.7","9":"25.95.13|54.17.31","10":"25.31.7","13":"0.4.9|4.32.43","16":"25.7.16","19":"25.33.7","21":"31.31.3","28":"62.3.14","29":"54.23.15","30":"25.16.12","31":"31.3.15","32":"24.22.13","33":"51.4.38","35":"25.67.6-7","36":"36.30.24","37":"32.10.10|37.6.26"}},{"v":["На Господа я надіюся, як же ви кажете душі моїй: «Відлітай на гору вашу, як птах»?","Бо ось грішники напружили лук, наготували стріли, щоб стріляти в темряві у непорочних серцем.","Бо те, що Ти довершив, вони зруйнували. Що зробить праведний?..","Господь у храмі святім Своїм. Господь — на небі Престіл Його. Очі Його [на вбогих] споглядають, зір Його випробовує синів людських.","Господь випробовує праведного і нечестивого, той же, хто любить неправду, ненавидить душу свою.","Дощем проллє Він на грішників палаюче вугілля, вогонь і сірку. Палючий вітер — частка чаші скорботи їхньої.","Бо праведний Господь і любить правду. На праведних дивиться лице Його."],"h":"Начальнику хору. Псалом Давида.","x":{"1":"25.54.23|8.24.2","4":"31.66.1|45.2.20|50.5.34","6":"0.19.24|32.23.19"}},{"v":["Начальнику хору. На восьмиструнному інструменті. Псалом Давида.","Спаси [мене], Господи, бо не стало праведного, бо нема вірних між синами людськими.","Неправду говорить кожен ближньому своєму; уста улесливі говорять від серця лукавого.","Погубить Господь уста облесливі та язик гордовитий,","тих, що говорять: «Язиком нашим переможемо, уста наші з нами, хто нам є Господь?»","«Ради страждання вбогих і зітхання бідних нині воскресну, — говорить Господь, — стану спасінням людей і відкриюся в ньому.»","Слова Господні — слова чисті, срібло, очищене від землі, сім разів переплавлене.","Ти, Господи, збережеш нас і захистиш нас від роду цього і повік.","Навкруги нечестиві ходять, коли підносяться нікчемні з синів людських."],"x":{"2":"31.57.1|43.7.2","3":"25.27.3","4":"65.5.12","5":"1.5.2|24.21.15|37.3.15","7":"9.22.31|26.30.5"}},{"v":["Начальнику хору. Псалом Давида.","Доки, Господи, забуватимеш мене до кінця? Доки відвертатимеш лице Твоє від мене?","Доки носитиму думи мої в душі моїй і скорботи в серці моїм день [і ніч]? Доки буде підноситися ворог мій наді мною?","Зглянься і почуй мене, Господи, Боже мій. Просвіти очі мої, щоб не заснув я сном смертним.","Щоб не сказав ворог мій: «Я переміг його» і щоб не зраділи вороги мої, коли б я похитнувся.","Я ж на милість Твою уповаю, серце моє возрадіє спасінням Твоїм. Славитиму Господа, що добро вчинив мені, [і співатиму імені Господа Всевишнього]."],"x":{"2":"25.76.8|45.1.2","4":"14.9.8|32.51.39","6":"31.66.14|25.102.2"}},{"v":["Сказав безумний у серці своїм: «Бога нема». Впали в розпусту, опоганилися в ділах своїх; не стало тих, хто чинив би добро.","Господь поглянув з неба на синів людських, щоб побачити: чи є розумний, що шукає Бога?","Всі заблудили, всі нікчемні стали: нема тих, хто чинив би добро, нема жодного.","Невже не прийдуть до розуму всі, що роблять беззаконня, заїдають людей моїх, мов їдять хліб, і Господа не призивають?","Вони убояться там, [де немає страху]. Бо Господь в роді праведних:","ви насміялися над убогим, а Господь — надія його.","«Хто дасть із Сиону спасіння Ізраїлеві?» Коли поверне Господь з неволі народ Свій, тоді зрадіє Яків і звеселиться Ізраїль."],"h":"Начальнику хору. Псалом Давида.","x":{"1":"25.9.27|25.52.2","2":"25.32.13|48.9.1","3":"62.3.10","6":"27.9.16","7":"25.52.7|31.59.20"}},{"v":["Господи, хто може жити в оселі Твоїй? Хто оселиться на святій горі Твоїй?","Той, хто ходить непорочно, і чинить правду, і говорить істину у серці своєму.","Той, хто не улещує язиком своїм, не чинить ближньому своєму зла і не слухає наклепів на ближніх своїх.","Той, в очах якого лукава людина є нікчемною, а в пошані ті, що бояться Господа, той, хто дає клятву ближньому і не відмовляється від неї.","Хто не дає срібла свого на нечесний прибуток і не приймає підкупу на невинного. Хто так чинить, той не захитається повіки."],"h":"Псалом Давида.","x":{"1":"25.23.3|25.83.5","2":"31.33.15","3":"24.27.4|66.4.25","4":"11.3.14","5":"1.22.25|4.23.19"}},{"v":["Охорони мене, Господи, бо я на Тебе надіюся.","Я сказав Господу: «Ти Господь мій! Блага мої Тобі не потрібні».","Святим, що на землі Його, сотворив Господь усі бажання Свої в них.","Нехай примножуються скорботи в тих, що біжать до ідолів, я ж не принесу їм жертви кривавої і не спом’яну імен їхніх устами моїми.","Господь — частина спадку мого і чаші моєї. В Тобі, Господи, вся спадщина моя.","Межі мої пролягли в кращих місцях, спадок мій приємний для мене.","Славитиму Господа, що просвітив мене, бо навіть і вночі повчає мене серце моє.","Повсякчас бачу я Господа перед собою, бо Він праворуч мене, і я не захитаюся.","Тому радіє серце моє і веселиться язик мій, навіть тіло моє спочиває в надії,","що Ти, Господи, не залишиш душі моєї в пеклі і не даси святому Твоєму побачити тління.","Ти покажеш мені дорогу життя; перед лицем Твоїм повнота радости і в правиці Твоїй блаженство вічне."],"h":"Пісня Давида.","x":{"3":"53.11.5","4":"31.1.11","5":"33.3.24","8":"54.2.25","10":"54.13.35","11":"54.2.28"}},{"v":["Почуй, Господи, правду [мою], зваж на благання моє, вислухай молитву мою з уст неулесливих.","Від Тебе Самого нехай вийде суд мій, очі Твої нехай побачать правоту.","Ти випробував серце моє, відвідав мене вночі. Ти випробував мене і не знайшов у мені неправди; думки мої не розходяться з устами моїми.","В ділах людських, за словами уст Твоїх, я охороняв себе від дороги гнобителя.","Утверди стопи мої на путях Твоїх, щоб не хиталися ноги мої.","Тебе благаю, бо Ти вислухаєш мене, Боже. Нахили вухо Твоє до мене і вислухай слова мої.","Покажи дивну милість Твою, бо Ти спасаєш тих, що уповають [на Тебе], від противників правиці Твоєї.","Охорони мене, Господи, як зіницю ока, під покровом крил Твоїх,","укрий мене від лиця нечестивих, що нападають на мене, від ворогів душі моєї, що оточили мене.","Ожиріло серце їхнє, устами їхніми промовляє гординя.","Ті, що переслідують мене, нині оточили мене; очі свої спрямували на мене, щоб розтоптати мене на землі.","Вони, як той лев, що здобичі шукає, як звір, що причаївся.","Воскресни, Господи, випереди їх, подолай їх; визволи душу мою від нечестивого мечем Твоїм;","від ворогів — рукою Твоєю, Господи, від людей світу цього, доля яких — у цьому житті; черево своє вони наповнюють від скарбів Твоїх; сини їхні ситі і залишають спадщину дітям своїм.","А я в правді дивитимусь на лице Твоє. Щоранку буду насичуватися славою Твоєю."],"h":"Молитва Давида.","x":{"1":"25.4.2","3":"25.7.10|25.65.10|32.11.20","5":"8.2.9","8":"4.32.10|48.2.8|7.2.12","10":"24.15.27","15":"50.5.8|58.3.20|63.13.10"}},{"v":["Начальнику хору. Раба Господнього Давида, який виголосив слова пісні цієї до Господа, коли Господь визволив його від рук усіх ворогів його і від руки Саула. І він сказав:","ВозлюблюТебе, Господи, кріпосте моя.","Господь — твердиня моя і пристановище моє, визволитель мій, Бог мій, поміч моя; на Нього моя надія, оборонець мій, ріг спасіння мого, заступник мій.","З хвалою прикличу Господа і від ворогів моїх спасуся.","Огорнули мене муки смертельні, і ріки беззаконня засмутили мене.","Кайдани пекельні скували мене, і сіті смертні обплутали мене.","У тісноті моїй я призивав Господа і до Бога мого взивав, і Він почув голос мій із храму [святого] Свого, і благання моє дійшло до слуху Його.","І затряслася, захиталася земля, тремтіли й тряслися підвалини гір, бо запалав гнівом [Господь].","Піднявся дим від гніву Його і з вуст Його — вогонь палючий, палаюче вугілля сипалося від Нього.","Він прихилив небеса й зійшов, і морок — під ногами Його.","І возсів на херувимів, і полетів, понісся на крилах вітру.","Хмарами, як покровом, Він покрив Себе, темними хмарами води Він огорнув Себе.","Від блиску Його перед Ним летіли хмари, град і вогненне вугілля.","І загримів у небесах Господь, і Всевишній подав голос Свій.","Пустив стріли Свої і розігнав їх. Метнув безліч блискавок і розсіяв їх.","І відкрилися джерела вод, відкрилися основи всесвіту від заборони Твоєї, Господи, від подиху гніву Твого.","Він простяг руку з висоти і взяв мене, і з глибокої води визволив мене.","Він визволив мене від ворогів моїх сильних і від ненависників моїх, що були сильнішими від мене.","Вони повстали на мене в час біди моєї, та Господь укріпив мене.","Він вивів мене на простір і визволив мене, бо Він возлюбив мене.","Господь воздав мені за правдою моєю і за чистотою рук моїх відплатив мені.","Бо я зберіг путі Господні і не був нечестивим перед Богом моїм.","Бо всі заповіді Його були переді мною, і від повелінь Його я не відхилявся.","Я був непорочний перед Ним і берігся, щоб не згрішити мені.","І воздав мені Господь за правдою моєю і за чистотою рук моїх перед очима Його.","Господи, Ти чиниш з милостивим милостиво, і з справедливим за справедливістю його,","з чистим — за чистотою його, а з лукавим — за лукавством його.","Бо Ти народ поневолений спасаєш і пиху гордих приборкуєш.","Ти засвічуєш світильник мій. Господь Бог мій просвічує темряву мою.","З Тобою я перемагаю військо, з Богом моїм я через мур перейду.","Бог мій! Непорочні путі Його, чисте слово Його, Він оборонець усіх, що надіються на Нього.","Бо хто Бог, крім Господа? Хто захисник, крім Бога нашого?","Бог підперізує мене силою, рівняє переді мною дорогу мою.","Робить ноги мої швидкими, як у оленя, і на висотах моїх ставить мене.","Привчає руки мої до боротьби і м’язи мої робить, як лук мідний.","Ти, Господи, даєш мені щит спасіння Твого, правиця Твоя підтримує мене і ласка Твоя звеличує мене.","Ти розширюєш кроки мої піді мною, і не хитаються ноги мої.","Я жену ворогів моїх і настигаю їх, і не повертаюся, аж доки не знищу їх.","Уражаю їх, і вони не можуть встати, падають під ногами моїми.","Бо Ти підперезав мене силою на битву, кинув під ноги мої тих, що повстали на мене.","Ти повернув до мене спиною ворогів моїх, і я нищив тих, що ненавиділи мене.","Вони кричали, та нікому було рятувати; до Господа — але Він не послухав їх.","Я розсіваю їх, як порох перед вітром, як багно на вулиці, топчу їх.","Ти врятував мене від людського заколоту, поставив мене на чолі народів. Народ, якого не знав я, служить мені.","Лише почувши про мене, народи підкоряються мені, чужинці запобігають переді мною,","навіть в укріпленнях своїх іноплемінники бліднуть і тремтять.","Живий Господь і благословенний Бог. І нехай прославлений буде Бог спасіння мого!","Бог, що відплачує за мене і підкорює мені народи,","Він визволив мене від ворогів моїх, підніс мене над тими, що воювали проти мене, і від чоловіка неправедного визволив мене.","За те буду славити Тебе, Господи, між народами й співатиму імені Твоєму.","Ти велично спасаєш царя і виявляєш милість до помазаника Свого Давида і роду його навіки."],"h":"(Пісня Давида.)","x":{"1":"9.22.1-2","3":"75.2.13","6":"24.22.10","7":"25.33.6|31.26.16|42.2.3:8","8":"9.22.8|32.10.10","9":"4.4.24|36.10.2|75.12.29","12":"31.50.3","14":"8.2.10|32.51.16","17":"25.65.12|25.68.2","20":"25.30.9","21":"24.22.30","28":"8.2.8|25.112.7","29":"31.42.16","30":"25.59.14","31":"25.11.7|25.18.8|26.30.5","32":"9.22.32|31.43.11|31.44.6","34":"45.3.19","35":"25.143.1","37":"25.30.9","41":"0.49.8","42":"24.27.9","43":"11.13.7|25.82.11|31.10.6","44":"62.15.9","47":"4.32.40","48":"12.17.10","50":"62.15.9"}},{"v":["Начальнику хору. Псалом Давида.","Небеса повідають славу Божу, творіння ж рук Його сповіщає твердь.","День дневі сповіщає про них, і одна ніч ночі дає звістку.","Нема ні мови, ні говору, де не чувся б голос їх.","По всій землі розійшлося віщування їх, і в кінці вселенної слова їх. Він поставив у них сонце,","і воно, мов жених, виходить із весільного чертога свого. Радіє, мов велетень, щоб обійти коло своє.","Від краю небес вихід його, і захід його на краю їх, і ніщо не сховається від тепла його.","Закон Господній непорочний, душу оживляє: свідчення Господні вірні, навчають простих.","Повеління Господні праведні — звеселяють серце. Заповідь Господня світла — просвітлює очі.","Страх Господній чистий і перебуває вічно. Суди Господні — істина, всі справедливі,","дорожчі за золото й дорогоцінне каміння; солодші за мед із сотів.","Бо раб Твій охороняється ними. І хто додержує їх, тому нагорода велика.","Хто зрозуміє гріхи свої? І від тайних моїх очисти мене.","І від навмисних утримай мене, раба Твого, щоб не оволоділи вони мною. Тоді я буду непорочним і очищеним від гріха великого.","Нехай же слова уст моїх і думки серця мого будуть приємні Тобі, Господи, Твердине моя і Спасителю мій."],"x":{"2":"25.96.6|54.14.17|62.1.20","5":"62.10.18","7":"27.1.5","8":"25.2.7","9":"57.1.19|66.1.18","11":"25.118.72","15":"25.39.14"}},{"v":["Начальнику хору. Псалом Давида.","Вислухає тебе Господь в день скорботи, захистить тебе ім’я Бога Якова.","Він пошле тобі поміч із святині і з Сиону підкріпить тебе.","Він пом’яне всі жертви твої, і всепалення твоє буде приємне.","[Господь] дасть тобі за серцем твоїм і наміри твої здійснить.","Звеселімося ж спасінням твоїм, і в ім’я Господа Бога нашого звеличмося; Господь виконає всі прохання твої.","Тепер я знаю, що Господь спасає Христа Свого; з святих небес Своїх відповідає Йому могутністю спасаючої правиці Своєї.","Одні хваляться колісницями, інші кіньми, а ми хвалимося іменем Господа Бога нашого.","Вони хитаються й падають, а ми стоїмо твердо.","Господи, спаси царя і вислухай нас, в який би день ми не звертались [до Тебе]."],"x":{"2":"25.17.7","5":"25.20.3|31.41.16","6":"9.8.6","8":"11.19.23"}},{"v":["Начальнику хору. Псалом Давида.","Господи, силою Твоєю звеселиться цар і спасінню Твоєму вельми возрадується.","Ти дав йому бажання серця його і прохання уст його Ти не відкинув.","Ти зустрів його благословенням благісним і поклав на голову його вінець із чистого золота.","Життя він просив у Тебе, і Ти дав йому довголіття на віки віків.","Велика слава його у спасінні Твоїм, славою й величчю Ти прикрасив його.","Ти дав йому благословення, навіки звеселив його радістю перед лицем Твоїм.","Бо цар уповає на Господа і милістю Всевишнього не захитається.","Рука Твоя, Господи, нехай знайде [всіх] ворогів Твоїх, правиця Твоя нехай досягне всіх, що ненавидять Тебе.","В час гніву Твого Ти розпалиш їх, як піч. У гніві Своїм Господь погубить їх, і поїсть їх вогонь.","Ти знищиш плід їх із землі і рід їх з-поміж синів людських.","Бо вони замислили ворожнечу проти Тебе — злий намір, якого не можуть [здійснити].","Ти поженеш їх перед Собою, з луків Твоїх пустиш стріли в лице їх.","Піднесися, Господи, силою Твоєю! Будемо співати й прославляти могутність Твою."],"x":{"3":"25.144.19","4":"75.2.9","5":"31.53.9-10","7":"31.19.24","9":"50.24.51","11":"25.33.17|31.14.22"}},{"v":["Начальнику хору. При сході зорі. Псалом Давида. (Пророцтво про страждання Ісуса Христа).","Боже, Боже мій! [Зглянься на мене!] Нащо Ти покинув мене? Далекі від спасіння мого слова плачу мого.","Боже мій, взиваю вдень — і Ти не чуєш; вночі — і нема мені спокою.","Ти ж у святині живеш, хвало Ізраїля.","На Тебе надіялися батьки наші, надіялись, і Ти визволив їх.","До Тебе звертались і були спасенні, на Тебе надію покладали і не осоромились.","А я черв, а не людина, приниження в людей і зневага в народів.","Всі, хто дивиться на мене, насміхаються з мене, зневажають устами, киваючи головою:","«Він надіявся на Бога, нехай же спасе його, нехай визволить його, коли він угодний Йому».","Але Ти ж вивів мене з утроби, дав мені надію на Тебе від грудей матері моєї.","На Тебе покинутий я від утроби. Від грудей матері моєї Ти — Бог мій.","Не віддаляйся ж від мене, бо скорбота близько, а заступника нема.","Бики роз’ярені обступили мене, страшні васанські — оточили мене.","Розкрили на мене пащі свої, як лев, що шукає поживи й рикає.","Я розлився, як вода, розслабли всі кості мої, і серце моє, як віск, розтопилося в грудях моїх.","Висохла, як черепок, сила моя, і язик мій прилип до піднебіння мого. В порох смерти Ти звів мене.","Бо пси оточили мене, зграя злих обступила мене. Пробили руки й ноги мої.","Можна перелічити всі кості мої, а вони дивляться та зневажають мене.","Розділили ризи мої собі і за одежу мою кидали жереб.","Ти ж, Господи, не віддаляйся від мене. Сило моя, на поміч мені прийди!","Визволи від смерти душу мою і від псів самотню мою.","Почуй і спаси мене від пащі лева і від рогів єдинорогів визволи мене.","Я ж сповіщатиму ім’я Твоє браттям моїм, посеред церкви вірних у піснях хвалитиму Тебе.","Всі, хто боїться Господа, прославляйте Його. Всі нащадки Якова, хваліть Його; нехай же бояться Його всі покоління Ізраїля!","Бо Він не зневажив і не покинув бідного в біді його і не сховав від мене лиця Свого, а почув мене, коли благав Його.","Буду хвалитися Тобою у зібранні великому, буду визнавати Тебе, обітниці мої сповню перед тими, що бояться Його.","Будуть їсти убогі й насичуватися, і хвалитимуть Господа ті, що шукають Його, щоб жили серця ваші повіки.","Згадають і повернуться до Господа всі краї землі і поклоняться перед Ним усі племена народів.","Бо Господнє є Царство, і Він царює над народами.","Будуть споживати й поклоняться Йому всі сильні землі; поклоняться Йому всі, що сходять у землю, і душа моя для Нього живе.","Нащадки [мої] будуть служити Йому і будуть зватися Господніми повіки.","Прийдуть вони і будуть сповіщати правду Його родові майбутньому, про все, що створив Господь."],"x":{"2":"50.27.46|51.15.34","5":"25.106.6","6":"25.24.2","8":"50.27.39","9":"50.27.43|29.2.18","10":"25.70.6","13":"40.4.1|50.27.20","16":"53.19.28","17":"50.27.27","18":"52.23.35","19":"50.27.35|51.15.24|52.23.34|53.19.24","23":"53.20.17|75.2.12","25":"75.5.7","26":"25.34.18","27":"28.5.1|31.65.13|52.1.53","28":"25.2.8|31.60.14","29":"37.7.27|50.6.10","30":"31.25.6|31.49.23","31":"31.53.10"}},{"v":["Господь пасе мене, і нічого мені не бракуватиме.","На місці плодючім, там Він оселив мене; біля води спокійної виховав мене.","Душу мою навернув; навів мене на стежки правди задля імені Свого.","Коли піду навіть у тіні смертній, не боятимуся зла, бо Ти зі мною; жезл Твій і палиця Твоя — вони потішили мене.","Ти наготував переді мною трапезу на очах гнобителів моїх; Ти намастив оливою голову мою, і чаша Твоя, що напоює, найкраща.","І милість [Твоя] буде йти слідом за мною по всі дні життя мого, й оселюся в домі Господнім на довгі дні."],"h":"Псалом Давида.","x":{"1":"31.40.11|32.23.4|36.34.23|53.10.11-12|56.2.25","4":"25.117.6|62.8.31","5":"26.9.2|25.111.10|31.25.6","6":"25.26.4"}},{"v":["Господня земля і все, що наповнює її, вселенна і всі, що живуть у ній.","Він на морях заснував її і на ріках утвердив її.","Хто зійде на гору Господню, і хто стане на місці святому Його?","Той, у кого невинні руки і чисте серце, хто не марнував на суєту душу свою і не присягався [ближньому своєму] зрадливо,","той матиме благословення від Господа і милість від Бога, Спаса свого.","Це рід тих, що шукають Господа, шукають лиця Твого, Боже Яковів.","Піднімайте, врата, верхи ваші, піднімайтеся, врата вічні, — і ввійде Цар слави!","Хто є цей Цар слави? Господь кріпкий і сильний, Господь могутній в бою.","Піднімайте, врата, верхи ваші, піднімайтеся, врата вічні, — і ввійде Цар слави!","Хто є цей Цар слави? Господь Сил, Він є Цар слави."],"h":"Псалом Давида. [У перший день тижня].","x":{"1":"1.19.5|25.49.12|63.10.26","2":"24.38.6","3":"25.14.1|31.33.15","4":"50.5.8","5":"31.48.18|38.10.12","6":"56.2.9|31.51.2"}},{"v":["До Тебе, Господи, підношу душу мою.","Боже мій, на Тебе я уповаю. Не дай мені осоромитися, не допусти, щоб вороги мої втішилися перемогою наді мною.","Нехай не осоромляться всі, що надіються на Тебе, а осоромляться ті, що беззаконствують даремно.","Господи, вкажи мені путі Твої і навчи мене стежок Твоїх.","Настав мене на істину Твою і навчи, бо Ти — Бог спасіння мого, на Тебе повсякчас я надію покладаю.","Згадай про милосердя Твоє, Господи, і про милість Твою, що подаєш від віку.","Гріхів юности моєї і несвідомости моєї не поминай, пом’яни мене в милості Твоїй, Господи, заради благости Твоєї.","Господь благий і праведний, тому наставляє грішника на путь спасіння.","Він веде покірливих до правди і навчає лагідних путей Своїх.","Всі путі Господні — милість і істина для тих, хто шанує завіти Його і свідчення Його.","Ради імені Твого, Господи, прости провину мою, бо вона велика.","Хто та людина, що боїться Господа? Він укаже їй дорогу, яку треба обирати.","Душа її буде у блаженстві, і рід її успадкує землю.","Сила Господня — тим, що бояться Його, і завіт Свій відкриває їм.","Очі мої завжди до Господа, бо Він визволить із сіті ноги мої.","Зглянься на мене, Господи, і помилуй мене, бо я самотній і знесилений.","Страждання серця мого примножилися, з біди моєї визволи мене.","Поглянь на скорботи мої і знесилення моє і прости всі гріхи мої.","Поглянь на ворогів моїх, як багато їх і якою лютою ненавистю ненавидять мене!","Охорони душу мою і спаси мене, щоб я не осоромився, уповаючи на Тебе.","Непорочність і правда нехай охороняють мене, бо я надіюся на Тебе.","Спаси, Боже, народ Твій від усіх страждань його."],"h":"Псалом Давида.","x":{"1":"25.85.4","3":"25.21.6","4":"25.26.11","6":"25.102.17|32.33.11","7":"24.13.26","8":"4.32.4","10":"38.14.10|37.4.34","11":"25.78.9","13":"31.60.21","14":"4.29.29|52.8.10","15":"24.16.20|25.120.1","17":"9.22.7|33.1.20","19":"53.15.25"}},{"v":["Розсуди мене, Господи, бо я ходив у невинності моїй; на Господа я надіявся і не похитнувся.","Випробуй мене, Господи, досліди мене, розпали серце моє і всю істоту мою.","Бо милість Твоя перед моїми очима, і я ходив у істині Твоїй.","Не сидів я з людьми нечестивими, і з підступними не піду.","Я зненавидів збори беззаконників і з нечестивцями не сяду.","Умию в невинності руки мої і обійду жертовник Твій, Господи,","щоб сповіщати голосом хвали про всі дивні діла Твої.","Господи, полюбив я красу дому Твого і місце оселі слави Твоєї.","Не погуби з нечестивими душі моєї і життя мого з людьми кровожерними,","що руки їхні готові на беззаконня, а правиця їхня повна підкупів.","Я ж у непорочності моїй ходжу. Спаси мене, [Господи], і помилуй мене.","Нога моя стоїть на дорозі правди. У церквах буду благословляти Тебе, Господи."],"h":"Псалом Давида.","x":{"2":"25.7.10","4":"24.31.5","5":"25.118.128","6":"4.21.6|25.22.6|25.41.3","8":"52.2.37|25.26.4","12":"25.21.23"}},{"v":["Господь — Просвічення моє і Спаситель мій, кого убоюся? Господь — Захисник життя мого, кого устрашуся?","Коли нападуть на мене противники й вороги мої, щоб пожерти тіло моє, то вони спотикаються і падають.","Коли й військо проти мене стане, не злякається серце моє; коли й ціла війна стане проти мене, і тоді я буду надіятися на Нього.","Одного прошу я у Господа, одного бажаю, щоб жити мені в домі Господньому усі дні життя мого, дивитися на красу Господню, щоранку молитися у храмі Його.","Бо Він сховає мене в домі Своїм у день біди, сховає в оселі Своїй, на скелю піднесе мене.","Я піднесу голову мою вище за ворогів моїх, що оточують мене. Принесу в домі Його жертву хвали. Буду співати й прославляти Господа.","Почуй, Господи, голос мій, яким я взиваю до Тебе; зглянься на мене і помилуй мене.","Від Тебе говорить серце моє: «Шукайте Господа!» Я шукаю лиця Твого, Господи.","Не відвертай же від мене лиця Твого і не відкидай у гніві раба Твого. Ти — Поміч моя, не відкинь мене і не покинь мене, Боже, Спасителю мій.","Бо коли батько й мати покинули мене, то Ти, Господи, прийняв мене.","Навчи ж мене, Господи, путей Твоїх і настанови на стежку правди, задля ворогів моїх.","Не віддавай мене в руки ворогам моїм, бо повстали проти мене лжесвідки і злобою палають на мене.","Але я вірю, що побачу милість Господню на землі живих.","Надійся ж на Господа і будь мужнім. Нехай кріпиться серце твоє. Чекай допомоги від Господа."],"h":"Псалом Давида. [До помазання].","x":{"1":"25.117.6|43.7.8","3":"25.3.7","4":"25.22.6","5":"25.30.21","7":"25.4.2","8":"25.49.15","9":"10.8.57","10":"31.63.16|31.64.8","11":"25.24.4|25.85.11","12":"25.30.9","13":"31.38.11","14":"31.25.9|45.2.3"}},{"v":["До Тебе, Господи, взиваю я. Боже мій! Не будь мовчазний до мене. Бо коли не будеш зважати на мене, то я стану як ті, що сходять у могилу.","Почуй, Господи, голос моління мого, коли я молюся до Тебе, коли підношу руки мої до храму святого Твого.","Не осуди мене з нечестивими і не погуби з тими, що чинять неправду, що говорять про мир до ближніх своїх, а на серці у них зло.","Воздай їм, Господи, за ділами їхніми, за лукавством вчинків їх: за ділами рук їхніх відплати їм заслужене ними.","За те, що вони не зважали на діла Господні, на діла рук Його, Він зруйнує їх і вже не відбудує.","Нехай буде благословенний Господь, бо Він почув голос моління мого.","Господь — помічник мій і захисник мій. На Нього уповало серце моє. Він допоміг мені і оновив тіло моє. Я віддам Йому хвалу піснею моєю.","Господь — кріпость людей Своїх, захист і Спаситель помазаника Свого.","Спаси, Господи, людей Твоїх і благослови насліддя Твоє: паси їх і піднось їх повіки."],"h":"Псалом Давида.","x":{"1":"25.142.7","2":"25.4.2","3":"25.11.3|32.9.8","4":"50.16.27","5":"24.34.27|31.5.12","7":"25.3.4","8":"25.26.1"}},{"v":["Принесіть Господу, сини Божі, принесіть Господу молодих ягнят, принесіть Господу славу і честь.","Віддавайте Господу славу імені Його. Поклоняйтеся Господу в дивній святині Його.","Голос Господній над водами, Бог слави загримів. Загримів Господь над водами великими.","Голос Господа могутній, голос Господа величний.","Голос Господа ламає кедри, Господь сокрушає кедри ливанські.","Від голосу Його гори скачуть, як телята, Ливан і Сиріон — як молоді єдинороги.","Голос Господа викрешує полум’я вогню,","від голосу Господа трясеться пустеля. Потрясає Господь пустелю Кадеську.","Голос Господа розроджує ланей і оголює ліси. В храмі Його все говорить про Його велич.","Господь возсів на Престолі над водами великими і як Цар буде над нами повіки.","Господь дасть силу народу Своєму, Господь миром благословить людей Своїх."],"h":"Псалом Давида. [Після закінчення свята кущів].","x":{"1":"25.95.7|76.21.24","3":"9.22.14|24.37.4","5":"31.30.31","6":"54.9.5","9":"24.39.4","10":"0.6.17|56.3.20-21"}},{"v":["Псалом Давида; пісня на оновлення дому.","Прославлю Тебе, Господи, бо Ти підняв мене і не допустив, щоб вороги мої тішилися наді мною.","Господи, Боже мій! Я взивав до Тебе, і Ти зцілив мене.","Господи, Ти вивів душу мою з пекла, Ти повернув мене до життя, визволив мене з-поміж тих, що сходять у могилу.","Співайте Господу, всі святі Його, прославляйте святу пам’ять Його,","бо на мить гнів Його і на все життя — милість Його; звечора плач, а на ранок — радість.","І я говорив у дні благоденства мого: «Не похитнуся я повіки».","Господи, Ти з милости Своєї укріпив гору мою, але відвернув Ти лице Твоє, і я захитався.","Тоді до Тебе, Господи, я взивав і до Бога [мого] молився, кажучи:","«Яка користь у крові моїй, коли я зотлію? Чи ж буде порох славити Тебе та сповіщати про істину Твою?","Господи, почуй мене і помилуй мене; Господи, прийди на поміч мені».","І Ти змінив плач мій на радість, зняв з мене одежу смутку і одягнув мене веселістю.","Нехай же славить Тебе душа моя і не вмовкає. Господи, Боже мій, буду славити Тебе повік."],"x":{"1":"9.5.11","2":"25.34.19","3":"4.32.39","4":"8.2.6|25.85.13","5":"25.96.12","6":"31.54.8","7":"24.29.18","10":"25.6.6|31.38.18","13":"25.15.9"}},{"v":["Начальнику хору. Псалом Давида. [Під час повстання].","На Тебе, Господи, уповаю. Не дай мені осоромитися повіки, правдою Твоєю спаси мене.","Прихили до мене вухо Твоє, поспіши визволити мене; будь мені Богом Заступником і Домом пристановища, щоб спасти мене.","Бо Ти сила моя і пристановище моє. Заради імені Твого наставляєш мене і насичуєш мене.","Виведи мене з сіті, яку таємно поставили на мене, бо Ти Заступник мій, Господи.","В руки Твої віддаю дух мій — Ти визволив мене, Господи, Боже істини.","Я ненавиджу тих, що надіються на ідолів, я ж на Господа уповаю.","Возрадуюсь і звеселюся милістю Твоєю, бо Ти зглянувся на смирення моє і визволив з недолі душу мою.","Не віддав мене в руки ворогів, а поставив на просторі ноги мої.","Помилуй мене, Господи, бо я у скорботі; висохло від горя око моє, і душа моя і все нутро моє.","Бо виснажилося у недузі життя моє, і роки мої в зітханнях. У стражданнях моїх знемогла сила моя, і кості мої висохли.","Від нападів ворогів моїх я став посміховиськом навіть у сусідів моїх і страхіттям для знайомих моїх; ті, що бачать мене, геть тікають від мене.","Я забутий у серцях, як мертвий; я став наче посуд розбитий.","Бо я чую, як мене ганьблять ті, що живуть навколо мене, коли вони збираються та радяться, щоб взяти душу мою.","Але я на Тебе, Господи, уповаю і кажу: «Ти — Бог мій».","У руці Твоїй доля моя. Визволи мене з рук ворогів моїх, від гонителів моїх.","Просвіти лице Твоє на раба Твого, спаси мене милістю Твоєю, Господи.","Нехай не осоромлюся тим, що призиваю Тебе, нехай осоромляться нечестиві і зійдуть у пекло.","Нехай замовкнуть уста улесливі, що говорять беззаконня проти праведного, гордовито і зневажливо.","Яке велике множество благости Твоєї, Господи, яку зберігаєш Ти для тих, що бояться Тебе, яку наготував Ти для тих, що уповають на Тебе перед синами людськими!","Ти сховаєш їх у сяйві лиця Твого від заколотів людських, укриєш їх під покровом Твоїм від ворожнечі народів.","Благословенний Господь, Який явив мені дивну милість Свою у місті захищеному.","Я ж сказав у відчаї моїм: «Відкинутий я від очей Твоїх». Але почув Ти голос молитви моєї, коли я взивав до Тебе.","Любіть Господа, всі преподобні Його, бо Господь охороняє вірних Своїх і з лишком відплачує гордовитим.","Будьте мужні, і нехай кріпиться серце ваше, всі, хто уповає на Господа."],"x":{"2":"31.49.23","4":"25.17.3","6":"52.23.46","7":"4.32.21|25.61.11","9":"25.17.20","10":"25.6.8","11":"25.108.24","12":"24.19.13","13":"27.9.5|32.48.38","14":"25.2.2","16":"25.38.5|25.138.16","17":"3.6.25|25.4.7|37.9.18","20":"31.64.4","21":"8.25.29|25.26.5","22":"25.4.4","23":"25.144.19","24":"24.22.29|26.29.23|56.5.5"}},{"v":["Блаженні, кому прощено беззаконня і чиї гріхи покрито.","Блажен муж, якому Господь не поставить у провину гріха і в устах якого нема лукавства.","Коли я замовк, постарілися кості мої від благання мого увесь день.","Бо день і ніч тяжіла наді мною рука Твоя, і свіжість лиця мого зникла, як у літню посуху.","Беззаконня мої я пізнав і гріха мого не утаїв. Я сказав: визнаю я перед Господом беззаконня мої, і Ти простив провини серця мого.","Тому помолиться Тобі кожен праведник у слушний час, навіть велика повінь не досягне його.","Ти Пристановище моє у скорботі, що огорнула мене; Радосте моя, визволи мене від тих, що оточили мене.","«Врозумлю тебе й наставлю тебе на путь, що нею ходитимеш; пильнуватиме тебе око Моє.","Не будьте як кінь і мул, що розуму не мають; віжками та вуздечкою стягни щелепи їх, якщо не наближаються до тебе».","Багато покарань грішникові, а того, хто уповає на Господа, оточить милість.","Веселіться в Господі і радуйтеся, праведні, і торжествуйте всі, праві серцем."],"h":"Псалом Давида. Повчання.","x":{"1":"62.4.7","2":"64.5.19","4":"25.37.5","5":"26.28.13|58.1.9","6":"31.55.6","7":"25.9.10","8":"25.24.12|26.4.11|4.11.12","9":"26.26.3","10":"31.57.20"}},{"v":["Радуйтеся, праведні, у Господі; праведним подобає похвала.","Прославляйте Господа на гуслях, співайте Йому на десятиструнній псалтирі.","Співайте Йому пісню нову, співайте радісно, з піднесенням.","Бо слово Господнє праве і всі діла Його праведні.","Господь любить правду і праведний суд, милости Його повна земля.","Словом Господнім сотворено небеса, і духом уст Його — вся сила їх.","Він зібрав, наче в міх, води морські, утворив у глибині їх безодні.","Нехай боїться Господа вся земля, нехай тремтять перед Ним усі, що живуть на світі.","Бо Він сказав — і сталося, Він повелів — і створилося.","Господь нищить змови народів, відкидає злі задуми людей, [розбиває змови князів].","Рада ж Господня стоїть вічно, і думки серця Його — з роду в рід.","Блаженний народ, у якого Бог є Господом, — люди, яких обрав Господь у насліддя Собі.","Господь з неба дивиться і бачить усіх синів людських.","Дивиться з Престолу, на якому сидить, і бачить усіх, що живуть на землі.","Він створив серця всіх їх і знає всі діла їхні.","Не захистить царя велике військо його, і велетня не спасе велика сила його.","Ненадійний кінь для спасіння, не спасе він великою силою своєю.","Бо ось очі Господні на тих, що бояться Його, і на тих, що надіються на милість Його.","Він спасе душі їхні від смерти, і в часи голоду наситить їх.","Душа ж наша нехай уповає на Господа, бо Він поміч і захист наш.","Ним звеселиться серце наше, бо ми надіємося на святе ім’я Його.","Милість Твоя, Господи, нехай буде над нами, бо ми уповаємо на Тебе."],"h":"[Псалом Давида.]","x":{"1":"25.31.11|25.146.1","2":"25.91.4","3":"25.39.4|31.42.10|76.5.9","6":"0.1.6-8|53.1.3","7":"24.38.8|32.5.22","9":"0.1.3|19.16.14","10":"24.5.12","11":"26.19.21|31.46.4","12":"25.64.5|25.143.15","13":"13.16.9|24.28.24","17":"26.21.31","18":"24.36.7|25.33.16|56.3.12","21":"31.66.14"}},{"v":["Псалом Давида, коли він прикинувся безумним перед Авимелехом, який через це відпустив його.","Благословлю Господа на всякий час, завжди хвала Йому в устах моїх.","Господом буде хвалитися душа моя; нехай почують вірні і звеселяться.","Величайте Господа зі мною, і прославмо ім’я Його всі вкупі.","Я шукав Господа, і Він почув мене і від усіх скорбот визволив мене.","Приступіть до Нього й просвітіться, і лиця ваші не осоромляться.","Ось убогий благав, і Господь почув його і від усіх скорбот спас його.","Ангел Господній охороняє тих, що бояться Його, і визволяє їх.","Споживіть і побачите, що благий Господь. Блажен муж, що уповає на Нього.","Бійтеся Господа, [всі] святі Його, бо не знають нестатку ті, що бояться Його.","Багаті зубожіли і зголодніли, а ті, що шукають Господа, не будуть позбавлені всякого блага.","Прийдіть, діти, послухайте мене, я страху Господнього навчу вас.","Хто з людей бажає жити і бачити дні благі —","стримуй язик свій від зла, і уста твої нехай не будуть облесливі.","Ухиляйся від всього злого і роби добро, будь мирний і пильнуй того.","Очі Господні звернені до праведних, і вуха Його до молитви їх.","Лице ж Господнє проти тих, що чинять зло, щоб знищити з землі й пам’ять про них.","Взивали [праведні], і Господь почув їх і від усіх скорбот визволив їх.","Близько Господь до скорботних серцем, і смиренних духом Він спасає.","Багато скорбот у праведника, та від усіх них визволить його Господь.","Господь охороняє всі кості їх, і ні одна з них не зламається.","Смерть же грішників люта, і ті, що ненавидять праведного, загинуть.","Господь визволить душі рабів Своїх, і не загине ніхто з тих, що уповають на Нього."],"x":{"1":"8.21.13","3":"52.1.47","5":"31.65.24","6":"43.7.7","7":"25.17.7|25.68.34","8":"0.32.1","9":"25.2.12|26.16.20","10":"5.4.24","11":"52.1.53","13":"56.3.10","15":"24.28.28|25.36.37","16":"25.32.18|30.15.19","19":"25.144.18","20":"54.7.10|62.8.17","21":"31.66.14","22":"26.22.8","23":"62.8.1"}},{"v":["Господи! Будь Суддею тих, що змагаються зі мною, і побори тих, що бажають побороти мене.","Візьми зброю Твою і щит і стань на поміч мені.","Вийми меч і загороди дорогу тим, що переслідують мене. Скажи душі моїй: «Я твоє спасіння».","Нехай осоромляться ті, що шукають душу мою. Нехай повернуть назад і покриються безчестям ті, що задумали зло проти мене.","Нехай стануть вони як той порох перед вітром, і ангел Господній нехай прожене їх.","Нехай дорога їхня буде темна і слизька, і ангел Господній нехай переслідує їх.","Бо вони без вини таємно поставили сітки свої на мене, викопали яму для душі моєї.","Нехай же несподівано прийде загибель на нього. І сітка, що він таємно на мене поставив, нехай уловить його, і в ту яму нехай сам упаде, на свою погибель.","А душа моя буде радіти у Господі, буде втішатися спасінням від Нього.","Всі кості мої скажуть: «Господи, хто подібний до Тебе? Ти возволяєш слабкого від сильного, бідного і вбогого — від гнобителів його».","Стали проти мене свідки неправедні; про те, чого не знаю я, вони допитують мене.","Віддають мені злом за добро, осиротили душу мою.","Я ж, коли хворіли вони, одягався в одежу скорботи, смиряв постом душу мою, і молитва моя від серця мого не спинялася.","Наче за приятелем або за братом своїм я побивався, ходив, сумуючи та плачучи, наче за матір’ю.","А вони з нещастя мого радіють, збираються та радяться, як збільшити рани мої, ганьблять мене, не знаю, за що;","спокушаючи, насміхаються, скрегочуть на мене зубами.","Господи, чи довго будеш дивитися на це? Одведи душу мою від злочинства їхнього, від левів — самотню мою.","Я буду прославляти Тебе на великих зібраннях, серед численних народів буду хвалити Тебе,","щоб не торжествували наді мною ті, що ворогують проти мене даремно, не переморгувалися очима своїми ті, що ненавидять мене без вини.","Бо не про мир говорять вони, а проти мирних землі складають свої замисли.","Розширюють на мене уста свої і кажуть: «Добре, добре, бачили очі наші».","Ти бачив це, Господи, не мовчи. Господи, не віддаляйся від мене.","Встань, Господи і заступись за правоту мою. Розбери тяжбу мою, Господи мій і Боже мій!","Розсуди мене, Господи, за правдою Твоєю, щоб не величалися вони наді мною.","Щоб не говорили в серці своїм: «Добре, [добре!] цього ми бажали». Щоб не сказали: «Ми поглинули його».","Нехай постидяться й осоромляться ті, що радіють з мого нещастя. Нехай покриються соромом і ганьбою ті, що вихваляються проти мене.","І нехай радуються і веселяться ті, що співчувають правді моїй. І нехай завжди кажуть: «Який величний Господь, що бажає миру рабові Своєму!»","А язик мій буде звіщати правду Твою та прославляти Тебе по всі дні."],"h":"Псалом Давида. (Пророчий).","x":{"1":"31.49.25","4":"25.69.3","5":"24.21.18|25.1.4|31.29.5|38.13.3","7":"52.23.4","8":"25.7.16|37.6.24","10":"24.36.13","11":"50.26.60|54.6.13|54.24.26","15":"24.30.9|52.23.35","18":"25.21.26","19":"53.15.25","21":"24.16.9|25.39.16|33.2.16","23":"25.43.24","26":"24.8.22|25.6.11","27":"25.39.17"}},{"v":["Начальнику хору. Раба Господнього Давида.","Навчився беззаконник грішити в серці своїм; нема страху Божого перед очима його.","Сам себе він обманює в очах своїх, ніби шукає гріхів своїх, щоб зненавидіти їх.","Але слова уст його — неправда і лукавство, він не хоче навчитися чинити добро.","На ліжку своєму він замишляє беззаконня, стає на недобру дорогу, не соромиться зла.","Господи, милість Твоя до небес, істина Твоя понад хмарами.","Правда Твоя, — як гори Божі, а присуди Твої, — як безодня велика, про людей і про тварин піклуєшся Ти, Господи.","Яка велика милість Твоя, Боже! Сини людські під захистом крил Твоїх спокійні.","Вони живляться від достатків дому Твого, і з джерела солодощів Твоїх Ти напуваєш їх.","Бо в Тобі джерело життя: в сяйві Твоїм ми бачимо світло.","Нехай буде милість Твоя на тих, що визнають Тебе, і правда Твоя на добрих серцем.","Нехай не наступить на мене нога гордині, і рука грішника нехай не досягне мене.","Бо впали ті, що чинили беззаконня, впали і не можуть встати."],"x":{"2":"0.20.11","3":"11.17.9","5":"43.2.1|62.12.9","6":"25.56.11","7":"62.11.33|42.4.11|63.9.9","8":"24.36.11|25.16.8","9":"31.25.6|64.8.9|76.21.6"}},{"v":["Не ревнуй злочинцям, не май заздрощів до тих, що чинять беззаконня,","бо вони, як трава, скоро посохнуть і, як пожовкле листя, скоро опадуть.","Надійся на Бога, твори добро, живи за правдою на землі і будеш ситий з багатства її.","Утішайся Господом, і Він дасть тобі бажання серця твого.","Відкрий Господу путь твою і надійся на Нього, Він допоможе.","Він виявить правоту твою, як світло, і правду твою, як полудень.","Підкорись Господу і надійся на Нього. Не заздри чоловікові лукавому, хоч би й щастило йому в цьому житті.","Не гнівайся і не розпалюйся, не спокушайся чинити зло.","Бо всі, хто чинить зло, будуть знищені, а ті, що надіються на Господа, успадкують землю.","Ще трохи, і не стане грішника, поглянеш на місце його і не знайдеш його.","А люди лагідні успадкують землю і будуть втішатися великим спокоєм.","Нечестивий задумує зло проти праведного і скрегоче на нього зубами своїми.","Господь же сміється з нього, бо бачить, що приходить день його.","Нечестиві виймають меч свій, готують стріли свої, щоб повалити убогого і бідного, заколоти тих, що йдуть дорогою правди.","Меч їхній увійде в їхнє ж серце, і луки їхні поламаються.","Краще мале праведника, аніж багатство у багатьох беззаконних,","бо сила грішників буде знищена, а праведних підкріпить Господь.","Господь знає дні людей непорочних, і надбання їх перебуватиме повік.","Не будуть вони посоромлені в лиху годину, і в дні голоду будуть насичені. А грішники загинуть.","Вороги Господні в пишноті й гордині своїй, як дим, щезнуть.","Нечестивий позичає і не віддає, а праведник милостивий щедро дає.","Отже, ті, хто прославляє Господа, успадкують землю, а хто проклинає Його, буде знищений.","Господь стверджує кроки такого чоловіка і сприяє йому в дорозі його.","Коли буде падати, то не впаде, бо Господь підтримує за руку його.","Я був молодим і постарів уже, але не бачив праведника покинутим або щоб діти його просили хліба.","Він щодня дає милостиню, позичає, і рід його в благословенні перебуває.","Ухиляйся від зла і твори добро, і житимеш довіку.","Бо Господь любить правду і не покидає святих Своїх; Він береже їх, [а беззаконні будуть викинуті,] і нащадки нечестивців будуть знищені.","Праведні ж успадкують землю і будуть жити на ній повік.","Уста праведного промовляють премудрість, і язик його, сповіщає правду.","Закон Бога його в серці його, і не спіткнуться ноги його.","Беззаконник підглядає за праведним і шукає — як вбити його.","Та Господь не дасть праведника в руки його і не допустить звинуватити його на суді.","Надійся на Господа і тримайся шляхів Його, Він піднесе тебе, щоб ти успадкував землю, і коли буде нищити нечестивців, ти побачиш.","Я бачив беззаконника, як він пишався і підносився, наче кедри ливанські.","Але минув він, не стало його, шукаю його і не знаходжу.","Пильнуй непорочність, дивись на праведного, бо майбутнє таких людей — мир.","А беззаконники всі будуть знищені, і майбутнє нечестивців — загибель.","Спасіння ж праведним від Господа. Він захистить їх у час скорбот.","Господь допоможе їм і визволить їх. Він визволить їх від нечестивих і спасе їх, бо вони надіялися на Нього."],"h":"Псалом Давида.","x":{"1":"26.23.17|26.24.1","2":"25.128.6|31.37.27|30.14.19","5":"25.54.23","6":"31.58.8","8":"66.4.26","9":"31.34.17","11":"50.5.5","16":"51.8.8","17":"32.48.25","19":"24.5.20|25.32.19","20":"25.67.3","22":"25.24.13|26.2.21","24":"25.144.14|26.24.16","25":"30.2.10","26":"25.111.5","27":"25.33.15|31.1.16","28":"10.8.57","29":"50.5.5","30":"26.10.31|50.12.35","31":"31.51.7","32":"25.11.9|51.3.2","35":"25.72.6|36.31.3","36":"24.4.20|24.5.3|24.20.7","37":"0.39.8|52.16.25|62.2.10","39":"20.8.16|25.45.2","40":"29.3.9|37.6.23"}},{"v":["Псалом Давида. На спомин [про суботу].","Господи, не суди мене в ярості Твоїй і не карай мене у гніві Твоїм.","Бо стріли Твої пройняли мене, і утвердив єси на мені руку Твою.","Нема зцілення у плоті моїй від лиця гніву Твого, нема спокою в костях моїх від лиця гріхів моїх.","Бо беззаконня мої перевищили голову мою і, як тягар великий, пригнітили мене.","Засмерділись і загнилися рани мої від лиця безумства мого.","Пригноблений я і зовсім поник, весь день сумуючи ходжу.","Бо стегна мої сповнилися запаленням, і нема зцілення у плоті моїй.","Озлоблений був і смирився до кінця; ридаю від болю серця мого.","Господи, перед Тобою всі бажання мої, і зітхання моє від Тебе не втаїться.","Серце моє стривожене, покинула мене сила моя, і світло очей моїх — і того вже не стало в мене.","Друзі мої і приятелі мої відійшли від мене, і родина моя стала осторонь мене.","А ті, що шукають душу мою, поставили сіті, і ті, що бажають мені зла, говорять про погибель і весь день замишляють підступи.","Я ж, немов глухий, не чую і, як німий, не відкриваю вуст своїх.","І став я як людина, що не чує і не має в устах своїх виправдання.","Бо на Тебе, Господи, уповаю я: Ти почуй, Господи, Боже мій.","Тому я сказав: нехай ніколи не потішаються [вороги мої]; коли спіткнуться ноги мої, вони звеличуються наді мною.","Я готовий до ран, і недуги мої повсякчас переді мною.","Бо беззаконня мої я визнаю і печалюся через гріх мій.","Вороги ж мої живуть і зміцнюються більше за мене, і намножилося тих, що ненавидять мене не по правді.","Ті, що відплачують мені злом за добро, обмовляють мене, бо я про благодіяння дбаю.","Не покинь мене, Господи, Боже мій, не відступи від мене.","Поспіши на поміч мені, Господи спасіння мого."],"x":{"2":"25.6.2|32.10.24","3":"4.32.23|24.6.4","5":"25.31.4|36.33.10","7":"25.41.10","12":"24.19.13|24.30.10|25.30.12","14":"31.53.7|50.27.12|54.8.32","19":"25.31.5|64.7.10","21":"25.108.5"}},{"v":["Начальнику хору Ідифуму. Псалом Давида.","Я сказав: «Буду слідкувати за життям моїм, щоб не грішити язиком моїм. Буду стримувати уста мої, доки нечестивий переді мною».","Я став як німий, не давав голосу. Я мовчав навіть про добре, але скорбота моя поновилася.","Запалало серце моє в мені і в думках моїх розгорівся вогонь, тоді я сказав язиком моїм:","«Скажи мені, Господи, коли кончина моя, і число днів моїх — яке воно? Щоб зрозумів я, який вік мій».","Ти, мов п’ядями, виміряв дні мої, і вік мій — як ніщо перед Тобою.","Дійсно, всяка людина, що живе на землі, як тінь ходить; даремно метушиться, збирає і не знає, кому те дістанеться.","І нині чого чекати мені, Господи? Надія моя — на Тебе.","Від усіх гріхів моїх очисти мене; не віддавай мене на глум безумному.","Я став як німий і не відкриваю уст моїх, тому що Ти вчинив це.","Відверни від мене удари Твої, бо від сили руки Твоєї я щезну.","Якщо Ти за кожен гріх будеш карати людину, то розсиплеться, як від молі, вся краса її. Ось такою нетривкою є людина.","Почуй же, Господи, молитву мою і благання моє прийми; не будь мовчазним на сльози мої, бо я подорожній перед Тобою і захожий, як і всі батьки мої.","Дай мені полегшення, щоб я заспокоївся раніше, ніж відійду від світу цього і більше мене не буде."],"x":{"1":"12.16.42","2":"25.140.3","3":"25.107.14","4":"54.17.16","5":"62.13.11","6":"25.89.6|25.143.4","7":"24.8.9|32.17.11|52.12.20","10":"50.11.5","12":"31.51.8","13":"12.29.15|64.5.6-7|67.3.20|75.11.13"}},{"v":["Начальнику хору. Псалом Давида. (Пророчий).","Твердо я надіявся на Господа, і Він прихилився до мене і почув молитву мою.","Він вивів мене з ями пристрастей і в’язкого болота, поставив на камені ноги мої і зміцнив стопи мої.","Він вклав в уста мої пісню нову — хвалу Богу нашому. Многі побачать, і убояться, і будуть уповати на Господа.","Блаженна людина, яка покладає надію свою на Господа і не звертається до гордих і до тих, що схиляються до неправди.","Господи, Боже мій! Як багато створив Ти чудес Твоїх для нас! Хто уподібниться Тобі помислами Твоїми про нас! Хотів би я говорити і перелічити, але вони перевищують всяке число.","Жертви і принесення Ти не захотів, але Ти відкрив мені вуха*. Всепалення і жертви за гріх Ти не бажав.","Тоді я сказав: «Ось іду; у свитку книжному написано про мене.","Я бажаю виконати волю Твою, Боже мій, і закон Твій у серці моїм».","Я сповіщав про правду Твою в зібранні великому і не спиняв уст моїх. Ти знаєш, Господи.","Не втаїв я правди Твоєї в серці моїм; я всім сповіщав про істину й спасіння Твоє. Не затаїв милости й вірности Твоєї перед зібранням великим.","Ти ж, Господи, не віддаляй від мене милосердя Твого. Милість Твоя й істина Твоя нехай завжди охороняють мене.","Бо обступила мене біда велика: оточили мене беззаконня мої, і я не можу побачити їх, бо їх більше, ніж волосся на голові моїй, і серце моє стиснулося в мені.","Благозволь, Господи, визволити мене. Господи, поспіши на допомогу мені!","Нехай постидяться і осоромляться ті, що шукають душі моєї, щоб погубити її. Нехай повернуть назад ті, що бажають зла мені.","Нехай покриються соромом ті, що говорили мені: «Добре, добре!»","Але нехай зрадіють і звеселяться Тобою ті, що шукають Тебе, Боже, і ті, що люблять спасіння Твоє, нехай безперестанку виголошують: «Великий Господь!»","Я ж немічний і вбогий, Господи, допоможи мені! Ти поміч моя і моє спасіння, Боже мій, поспіши!"],"x":{"3":"24.30.19|52.6.48","4":"25.32.3|76.5.9","5":"25.2.12|26.16.20|32.17.7","7":"25.50.18","8":"53.5.46","9":"31.50.5","10":"25.34.18","11":"50.12.35","13":"25.30.11","14":"25.21.20","15":"25.34.4","16":"25.34.21","18":"25.69.6"},"n":{"7":["За перекладом 70-ти: приготував мені тіло."]}},{"v":["Начальнику хору. Псалом Давида. (Пророчий).","Блаженний, хто дбає про [вбогих і] бідних, в день скорботи спасає його Господь.","Господь збереже його й охоронить життя його. Блаженним він буде на землі, і Ти, Господи, не віддаси його в руки ворогів його.","Господь допоможе йому в час хвороби його, все ложе його Ти оздоровиш у болісті його.","Я сказав: «Господи, помилуй мене і зціли душу мою, бо згрішив я перед Тобою».","Вороги мої в злобі кажуть про мене: «Коли він помре та згине ім’я його?»","А коли приходять провідати мене, говорять облесливо, ховають злобу в серці, а вийшовши, змовляються.","Ненависники шепочуть між собою, замишляють зло проти мене.","Словом лихим ображають мене, говорячи: «Він ліг і вже не встане».","Навіть чоловік, що жив у згоді зі мною, що їв хліб мій і на якого я надіявся, — підняв проти мене п’яту свою.","Ти ж, Господи, помилуй мене, підійми мене, щоб я віддав їм.","З того дізнаюсь я, що Ти любиш мене, коли ворог мій не потішиться наді мною.","А мене Ти охорониш заради лагідности моєї, і поставиш перед лицем Твоїм навіки.","Благословенний Господь, Бог Ізраїля од віку й до віку! Амінь, амінь!"],"x":{"2":"26.14.21|37.4.24|52.14.13","4":"50.9.22|52.7.7","5":"25.6.3","8":"50.22.15","9":"51.12.13|50.27.66","10":"53.13.18|54.1.16","14":"25.39.17"}},{"v":["Начальнику хору. Повчання синам Кореєвим. (Псалом Давида).","Як прагне олень до потоку води, так прагне душа моя до Тебе, Боже.","Прагне душа моя до Бога сильного й живого. Коли ж прийду я і з’явлюся перед лицем Божим?","Сльози мої стали хлібом мені день і ніч, коли вороги говорили до мене щодня: «Де Бог твій?»","Згадуючи це, я виливаю душу мою, бо я ходив серед великої кількості людей, входив з ними в дім Божий з піснями радости й хвали, з голосами урочистого святкування.","Чому сумуєш, душе моя, чому хвилюєшся в мені? Уповай на Бога, бо я ще буду хвалити Його, Спасителя мого і Бога мого.","Душа моя хвилюється в мені, Боже мій, тому згадав я Тебе в землі Йорданській і Єрмонській, з гори Малої.","Безодня безодню викликає шумом водоспадів Твоїх. Усі води Твої і хвилі Твої пройшли наді мною.","Вдень покаже Господь милість Свою, а вночі пісня Йому від мене — молитва до Бога життя мого.","Кажу я до Бога: «Захиснику мій! Навіщо Ти забув мене? Чого я, сумуючи, ходжу, коли ворог ображає мене»?","Наче хто ламає кості мої, коли глумляться з мене вороги мої та говорять щодня: «Де Бог твій?»","Чому сумуєш, душе моя, чому хвилюєшся в мені? Уповай на Бога, бо я ще буду славити Його, Спасителя мого і Бога мого."],"x":{"1":"12.6.22","3":"25.83.3","5":"24.30.16","6":"25.42.5","8":"25.68.3","9":"25.118.62","10":"25.37.7","12":"25.42.5"}},{"v":["Суди мене, Боже, і розсуди тяжбу мою з народом недобрим. Від людини лукавої і злої визволи мене.","Бо Ти — Бог сили моєї. Навіщо Ти відкинув мене? Чому я, сумуючи, ходжу, коли ворог ображає мене?","Пошли світло Твоє й істину Твою, нехай вони ведуть мене і виведуть на святу гору Твою і в оселі Твої.","І ввійду я до жертовника Божого, що наповнює радістю серце моє, і буду славити Тебе піснями, як на гуслях, Боже, Боже мій.","Чому сумуєш, душе моя? Навіщо хвилюєшся в мені? Уповай на Бога, бо я ще буду славити Його, Спасителя мого і Бога мого."],"h":"(Псалом Давида).","x":{"2":"25.37.7","3":"9.15.25","5":"25.41.6"}},{"v":["Начальнику хору. Повчання синам Кореєвим.","Боже, вухами нашими почули ми, і отці наші сповістили нам про діла, які вчинив Ти в часи їхні, часи давні.","Рукою Твоєю Ти знищив народи, а їх оселив, знищив племена, а їх розмножив.","Не мечем вони придбали землю і не їхня сила спасла їх, а Твоя рука і Твоя сила й світло лиця Твого, бо Ти благоволив до них.","Боже, Ти — Цар мій! Ти Той, що даєш спасіння Якову.","З Тобою, як рогами, поб’ємо ми ворогів наших і в ім’я Твоє потопчемо тих, що повстали проти нас.","Бо не на лук мій я надіюся, і меч мій не спасе мене,","а Ти спасеш нас від ворогів наших і осоромиш тих, що повстали проти нас.","Тобою, Боже, будемо хвалитися кожен день, і ім’я Твоє будемо славити повіки.","Нині ж Ти відкинув і осоромив нас, і не виходиш, Боже, з військом нашим.","Ти попустив, щоб ми втікали від ворогів, і ненависники наші грабують нас.","Ти, як овець, віддав нас на заколення і розсіяв нас поміж народами.","Ти задарма віддав народ Свій і не підвищив ціни на нього.","Ти на глум віддав нас сусідам нашим, на посміх і зневагу всім, що навкруги нас.","Ти зробив нас притчею між народами, покиванням голови між людьми.","Щодня сором мій переді мною, і посоромлення вкриває лице моє","від голосу ганьбителя й наклепника, від погляду ворога й месника.","Все це прийшло на нас, але ми не забули Тебе і не порушили завіту Твого.","Не відхилилося від Тебе серце наше, і кроки наші не зійшли з дороги Твоєї,","коли Ти смирив нас у землі злостраждань і тінню смерти покрив нас.","Бо якби ми забули ім’я Бога нашого і простягнули руки свої до бога чужого,","то чи не покарав би нас Бог? Бо Він знає таємниці серця.","Але за Тебе, Господи, вбивають нас кожен день, ми стали як вівці, що призначені на заколення.","Встань, Господи, чого спиш Ти? Прокинься і не відкидай нас назавжди.","Навіщо ховаєш лице Твоє? Забуваєш скорботу та біду нашу?","Бо душа наша принижена до пороху, і серце наше в землю втоптане.","Воскресни, Господи, поможи нам і визволи нас імені Твого ради."],"x":{"1":"25.41.1","2":"4.6.21|25.77.3","3":"1.15.17","4":"4.33.29","6":"25.59.14|31.33.22","7":"25.19.8","10":"25.59.3","13":"8.12.9|31.52.3","14":"25.78.4|32.24.9","18":"31.26.8","22":"25.7.10","23":"62.8.36","24":"50.8.24-25","25":"25.12.2","26":"31.51.23"}},{"v":["Начальнику хору. На музичному інструменті шошан. Повчання синам Кореєвим. Пісня про Улюбленого.","Вилилось із серця мого слово благе, говорю я про діла мої Цареві. Язик мій — перо книжника-скорописця.","Ти прекрасніший за синів людських, виливається благодать із уст Твоїх. Тому благословив Тебе Бог навіки.","Прив’яжи меч Твій до бедра Твого, сильний, славою Твоєю і красою Твоєю.","І натягни лук, і встигай, і царюй істини ради, і лагідности, і справедливости, і дивно поведе Тебе правиця Твоя.","Гострі стріли Твої, [Сильний]! Вони в серце ворогам Царя. Впадуть народи перед Тобою.","Престіл Твій, Боже, повік віку, жезл правоти — жезл Царства Твого.","Ти полюбив правду і зненавидів беззаконня, тому помазав Тебе, Боже, Бог Твій єлеєм радости більше, ніж спільників Твоїх.","Вся одежа Твоя — як смирна, алое і касія; в палатах із слонової кості звеселять Тебе.","Дочки царів почесні гості Твої; стала цариця праворуч Тебе, в ризи позолочені одягнена, прикрашена.","Слухай, дочко, і споглянь, і прихили вухо твоє, і забудь народ твій і дім отця твого.","І забажає Цар доброти твоєї, бо Він — Бог твій, і поклонишся Йому.","І дочка Тира з дарами, і найбагатші з народів помоляться лицю Твоєму.","Вся слава дочки царя в ній самій, одежа її шита золотом.","В дорогих прикрашених ризах введуть її до Царя. Приведені будуть діви вслід за нею, подруги її.","Приведуть їх з піснями радости і введуть їх у палату Царя.","Замість батьків Твоїх будуть сини Твої. Ти поставиш їх князями по всій землі.","Пом’яну ім’я Твоє у всякому роді і роді. Заради того люди всі вихвалятимуть Тебе і прославлятимуть ім’я Твоє повік віку."],"x":{"1":"66.1.6","3":"52.4.22","4":"25.23.8|31.11.5|75.4.12|76.1.16|76.19.15","6":"24.6.4|25.37.3","7":"75.1.8|31.32.1","8":"25.14.2|31.61.1","9":"28.1.3|66.5.2","10":"31.61.10","11":"38.2.19","12":"31.62.4|76.19.7","13":"25.71.10","14":"36.16.10|50.22.11","15":"31.61.10|56.3.3","17":"62.9.5|76.1.6|76.5.10"}},{"v":["Начальнику хору. Синів Кореєвих. На музичному інструменті аламоф. Пісня.","Бог нам пристановище і сила, скора допомога в біді, що надходить на нас.","Тому не будемо боятися, хоч би захиталася земля, і гори зрушились у безодню моря.","Нехай шумлять і хвилями здіймаються води і трясуться гори від хвиль їхніх.","Потоки рік веселять місто Боже, святу оселю Всевишнього.","Бог посеред нього — воно не захитається; Бог допоможе йому зранку.","Стривожилися народи, захиталися царства: [Всевишній] подав голос Свій, і похитнулася земля.","Господь Сил з нами, Бог Якова — захисник наш.","Прийдіть і погляньте на діла Божі, які чуда вчинив Він на землі.","Він спинив війни до країв землі, поламав лук, знищив зброю і колісниці попалив вогнем.","«Заспокойтеся і пізнайте, що Я — Бог, піднесуся між народами і прославлюся на землі».","Господь Сил з нами, Захисник наш — Бог Якова."],"x":{"1":"25.41.1","2":"25.17.3|26.18.11|45.3.19","6":"31.33.20|36.48.35|48.2.5","8":"62.8.31","9":"25.65.5","10":"25.75.4|38.2.18","11":"31.64.2","12":"62.8.31"}},{"v":["Начальнику хору. Синів Кореєвих. Псалом.","Всі народи, заплещіть руками, вигукніть до Бога голосом радости.","Бо Господь Всевишній страшний, — великий Цар усієї землі.","Він підкорив людей нам, і народи — під ноги наші.","Обрав нам насліддя наше, красу Якова, якого полюбив.","Зійшов Бог при окликах радости, Господь — при звуках сурмних.","Співайте Богу нашому, співайте! Співайте Цареві нашому, співайте!","Бо Бог — Цар усієї землі, співайте розумно.","Бог став Царем над усіма народами. Бог возсів на святім Престолі Своїм.","Князі народів зібралися до народу Бога Авраамового, бо влада над землею — Божа. Він вищий за все."],"x":{"3":"48.14.9|49.1.14|76.19.15","6":"25.67.19|54.1.9|66.4.10","7":"31.12.5","9":"25.21.29|25.79.2|75.8.1"}},{"v":["Пісня синів Кореєвих.","Великий Господь і вельми хвальний у місті Бога нашого, на горі святій Його.","Велика радість всій землі — гора Сион; з північного боку її — місто Царя великого.","Бог у храмі Своєму знаний як захисник,","бо ось зібралися царі, зійшлися докупи,","побачили, здивувалися, злякалися і відступили.","Страх обійняв їх і муки, як у жінок під час родин.","Східним вітром Ти потопив кораблі фарсийські.","Як чули ми, так і побачили у місті Господа Сил, у місті Бога нашого: Бог утвердив його навіки.","Ми роздумували, Боже, про милість Твою посеред храму Твого.","Яке ім’я Твоє, Боже, така і хвала Твоя аж до країв землі. Повна правди правиця Твоя.","Нехай веселиться гора Сион, [і] нехай радіють дочки народу Божого заради судів Твоїх, [Господи].","Обійдіть навколо Сиона і розгляньте його, перелічіть вежі його,","зверніть серця ваші до могутності його, щоб переказати поколінням майбутнім.","Бо цей Бог є Бог наш повіки. Він буде провадити нас повік віку."],"x":{"2":"25.144.3|75.12.22|76.14.1","3":"36.40.2","4":"13.20.8|48.8.3|49.1.14","6":"11.19.35-36","7":"11.19.3|31.21.3","8":"31.27.8","11":"11.19.15|54.19.17","15":"31.25.9"}},{"v":["Начальнику хору. Синів Кореєвих. Псалом.","Слухайте це, всі народи. Почуйте всі, хто живе на світі, —","І прості, і знані, і багаті, й убогі.","Уста мої промовлятимуть премудрість, і помисли серця мого — розум.","Прихилю вухо моє до притчі і на гуслях пісні відкрию загадку мою.","Чого боятися мені в день біди, коли обступлять мене злочинства тих, що доганяють мене?","Ви, що надієтеся на силу свою та величаєтеся багатством своїм!","Людина ніколи не викупить брата свого, не дасть Богові викупу за нього.","Дорога ціна викупу душ їхніх, і не буде того повіки,","щоб залишився хтось жити вічно і не зазнав смерти.","Кожен бачить, що й розумні помирають так само, як і нерозумні та безумні гинуть, і багатства свої залишають іншим.","Вони думають, що доми їхні вічні і оселі їхні з роду в рід, землі свої вони називають своїми іменами.","І людина, будучи в честі, не розуміє, що вона зрівнялася з тваринами і уподібнюється їм.","Цей шлях їхній — спокуса їм, хоч після цього устами своїми будуть хвалити його.","Як овець, поглине їх безодня; смерть буде пасти їх, і ранком праведні будуть володіти ними; сила покине їх, і могила буде житлом їхнім.","Але Господь спасе душу мою від пекла, коли прийме мене.","Не бійся, коли розбагатіє людина, коли примножиться слава дому її.","Бо коли помре, то не візьме з собою нічого, не піде за нею слава її.","Хоч за життя вона ублажає душу свою, і славлять її за те, що догоджає собі,","але піде до роду батьків своїх, які ніколи не побачать світла.","Так людина, будучи в честі, не розуміє, що вона зрівнялася з тваринами і уподібнюється їм."],"x":{"5":"25.77.2|50.13.35","7":"24.36.18|25.51.9|26.11.4","8":"58.3.16","9":"50.16.26|51.8.37|56.1.19","11":"26.11.4|27.2.16|27.6.2","13":"27.3.19","15":"31.14.11|76.2.27","16":"25.15.10","18":"24.27.18","19":"4.29.19","21":"27.3.19|52.12.20"}},{"v":["Бог богів, Господь промовив і закликає землю від сходу сонця і до заходу.","Від Сиону велич краси Його.","Гряде Бог наш — і не мовчить, перед ним вогонь, що все палить, навкруги Нього сильна буря.","Він закликає з висоти небо і землю — судити народ Свій:","«Зберіть до Мене святих Моїх, що вступили в завіт зі Мною при жертві!»","Небеса проголосять правду Його, бо Суддя цей є Бог.","«Слухай, народе Мій, Я буду говорити. Ізраїлю! Я буду свідчити проти тебе. Я — Бог, твій Бог.","Не за жертви твої буду докоряти тобі, бо всепалення твої завжди переді Мною.","Не прийму ні телят від дому твого, ні козлів із дворів твоїх,","бо Мої всі звірі лісові і тварини на всіх горах.","Я знаю всіх птахів небесних і вся краса поля переді Мною.","Коли б я зголоднів, то не сказав би тобі, бо світ увесь Мій і все, що є в ньому.","Хіба Я споживаю м’ясо телят чи п’ю кров козлів?","Принеси Богу жертву хвали і виконай перед Всевишнім обітниці твої.","І призови Мене в день скорботи твоєї, Я спасу тебе, і ти прославиш Мене».","А до грішника каже Бог: «Навіщо говориш ти про настанови Мої і завіт Мій береш у вуста свої?","Ти ж зненавидів настанови Мої і слова Мої відкидаєш від себе.","Коли бачиш злодія, то сходишся з ним, і з перелюбником спілкуєшся.","Уста твої невпинно злословлять, і язик твій сплітає підступи.","Сидиш і наговорюєш на брата твого і на сина матері твоєї зводиш наклеп.","Ти це робив, а Я мовчав; ти гадав, що й Я такий, як ти. Але Я викрию тебе і поставлю перед тобою [гріхи твої].","Зрозумійте ж це ви, що забуваєте Бога, щоб я не зловив вас, і тоді вже ніхто не врятує вас.","Хто приносить жертву хвали, той прославляє Мене, і це дорога, якою Я явлю йому спасіння Моє»."],"h":"Псалом Асафа.","x":{"1":"4.10.17","2":"25.47.3","3":"25.2.5","4":"4.31.28","5":"50.24.31","7":"25.80.9","9":"31.66.3|32.6.20|38.5.6","12":"1.19.5|25.23.1|24.41.3","14":"25.115.8|62.12.1","15":"25.26.8|48.13.9","16":"62.2.21|63.9.27","17":"50.7.3","18":"50.24.49|66.5.7","19":"43.6.12","21":"31.42.14|31.47.11|31.57.11","23":"52.8.39|53.7.17"}},{"v":["Начальнику хору. Псалом Давида,","коли приходив до нього пророк Нафан, після того, як Давид увійшов до Вирсавії. (Молитва покаяння).","Помилуй мене, Боже, з великої милости Твоєї, і з великого милосердя Твого прости провини мої.","Особливо омий мене від беззаконня мого і від гріха мого очисти мене.","Бо беззаконня моє я знаю, і гріх мій повсякчас переді мною.","Проти Тебе єдиного я згрішив і лукаве перед Тобою вчинив, отже, праведний Ти у слові Твоїм і справедливий у присуді Твоїм.","Ось бо в беззаконні зачатий я, і в гріхах породила мене мати моя.","Бо Ти істину полюбив єси, невідоме й таємне мудрости [Твоєї] явив Ти мені.","Окропи мене ісопом — і очищуся, омий мене — і стану біліший від снігу.","Дай мені почути радість і веселість — і зрадіють кості мої упокорені.","Відверни лице Твоє від гріхів моїх і прости всі беззаконня мої.","Серце чисте створи в мені, Боже, і духа праведного віднови в нутрі моєму.","Не відкинь мене від лиця Твого і Духа Твого Святого не відніми від мене.","Поверни мені радість спасіння Твого і духом могутнім укріпи мене.","Навчатиму беззаконників шляхів Твоїх, і нечестиві навернуться до Тебе.","Визволи мене від вини кривавої, Боже, Боже спасіння мого, і язик мій радісно славитиме правду Твою.","Господи, відкрий уста мої, і уста мої сповістять хвалу Твою.","Бо коли б Ти жертви забажав, приніс би я: всепалення Ти не бажаєш.","Жертва Богові — це дух упокорений, серцем скорботним і смиренним Ти не погордуєш.","Ублажи, [Господи], благоволінням Твоїм Сион, і нехай збудуються стіни єрусалимські.","Тоді буде угодна Тобі жертва правди, приношення і всепалення: тоді покладуть на Жертовник Твій тельців."],"x":{"2":"9.12.1","3":"25.56.2|31.33.2|75.9.14","5":"25.31.5","6":"62.3.4","7":"24.14.4","8":"63.2.7","9":"2.14.6","12":"64.5.17|65.6.15|66.2.10","13":"50.6.13|32.7.15","15":"50.7.5","16":"9.11.15-16","17":"25.70.8","18":"25.39.7","19":"25.4.6|31.66.2|52.18.13","20":"31.33.20|31.54.11","21":"4.33.19"}},{"v":["Начальнику хору. Повчання Давида,","після того, як приходив Доїк ідумеянин і доніс Саулу, сказавши йому, що Давид прийшов у дім Авимелеха.","Чого хвалишся злодійством, сильний? Зловживаєш милосердям Божим кожен день?","Неправду висловлює язик твій, як бритва вигострена — таке твоє лукавство.","Ти полюбив зло більше, ніж добро, більше неправду, ніж говорити правду.","Ти полюбив слова погибелі, розмову улесливу.","За те знищить тебе Бог до кінця. Викине тебе й виселить тебе з дому [твого], викоренить тебе із землі живих.","Побачать це праведні і убояться, посміються над тобою [і скажуть]:","«Ось чоловік, що не у Бога шукав собі сили, а сподівався на силу багатства свого та зміцнювався злочинством своїм».","А я, мов оливкове зелене дерево в домі Божім, я уповаю на милість Божу повік.","Буду вічно славити Тебе, Боже, за все, що Ти вчинив для мене. Буду надіятися на ім’я Твоє, бо Ти милостивий до праведних Твоїх."],"x":{"2":"8.22.9","3":"26.21.12","4":"25.56.5|26.25.18","7":"24.18.14|24.20.7|25.49.22","9":"25.48.7|26.11.28|51.10.24","10":"25.91.13|32.11.16|38.14.7","11":"25.36.5"}},{"v":["Начальнику хору. На духових інструментах. Повчання Давида.","Сказав безумний у серці своїм: «Немає Бога». Розпусні стали, огидне діють у беззаконнях. Нема тих, хто чинив би добро.","Бог з неба поглянув на синів людських, щоб побачити: чи є хто розумний, що шукає Бога?","Всі відвернулися, всі нікчемні стали; нема вже такого, хто чинить добро, немає жодного.","Невже не прийдуть до розуму ті, що чинять беззаконня, що з’їдають людей моїх, наче хліб, а Господа не призивають?","Вони будуть боятися страху там, де нема його, бо розсипле Бог кістки самовпевнених. Осоромлені будуть вони, бо Бог відкинув їх.","Хто дасть із Сиону спасіння Ізраїлеві? Коли поверне Бог із полону людей Своїх, зрадіє Яків і звеселиться Ізраїль."],"x":{"2":"25.9.25|25.13.1|62.3.11","6":"50.25.25","7":"25.13.7|76.22.20"}},{"v":["Начальнику хору. На струнних інструментах. Повчання Давида,","коли прийшли зифеї і сказали Саулу: «Чи не в нас ховається Давид?»","Боже, в ім’я Твоє спаси мене і силою Твоєю допоможи мені.","Боже, почуй молитву мою і вислухай слова уст моїх.","Бо чужі повстали на мене, і сильні шукають душі моєї, і не мають вони Бога перед собою.","Та ось Бог помагає мені, і Господь підкріпляє душу мою.","Він відплатить за зло ворогам моїм. Істиною Твоєю, Боже, Ти погубиш їх.","Від серця принесу жертву Тобі і прославлю ім’я Твоє, бо воно благе.","Бо Ти визволив мене від усякої скорботи, і на ворогів моїх сміливо дивиться око моє."],"x":{"2":"8.23.19","4":"25.4.2|25.5.2","5":"25.85.14|18.4.5","9":"25.58.10-11"}},{"v":["Начальнику хору. На струнних інструментах. Повчання Давида.","Вислухай, Боже, молитву мою і не зневаж благання мого.","Прихилися і вислухай мене, я плачу від туги моєї.","І тривожуся від голосу ворожого і від утисків нечестивців.","Бо вони чинять мені беззаконня й у гніві ворогують проти мене.","Серце моє стривожилося в мені, смертельні страхіття напали на мене.","Страх і трепет прийшли на мене, і жах огорнув мене.","І я сказав: хто дав би мені крила, як у голуба, я б полетів та відпочив би.","Полетів би якнайдалі, став би жити в пустелі, ждучи Бога, щоб спас мене від слабкодухости і від бурі.","Розбий, Господи, і роз’єднай змову їхню, бо беззаконня та ворожнечу бачу я в місті.","Вдень і вночі вони обходять його по мурах його, а усередині його — беззаконня та кривда.","І не зникають з вулиць його насильство і зрада.","Та якби це ворог ганьбив мене, я стерпів би, або якби це ненависник мій величався наді мною, я не зважав би на нього.","Але ти, чоловіче, — однодумцю мій, приятелю і друже мій,","з яким ми щиро сходилися і до дому Божого разом ходили!","Нехай загибель прийде на них, бо лукавство в оселях їхніх, посеред них.","Я ж до Бога взиваю, і Господь почує мене.","Увечері, і вранці, і опівдні буду благати й молити, і Він почує голос мій.","Він визволить миром душу мою від напасників моїх, бо їх багато в мене.","Почує мене Бог, і упокорить їх Той, Хто перебуває вічно, бо нема в них каяття, і не бояться вони Бога.","Підіймають руки свої на невинних і оскверняють завіт Його.","Уста їх масніші від масла, а в серці їх злоба. Масні, як олива, слова їх, але то гострі стріли.","Покладайся на Господа у скорботах твоїх, і Він підтримає тебе. Ніколи не дасть Він упасти праведникові.","Ти, Боже, кинеш їх у яму погибелі. Кровожерні й підступні не доживуть і до половини віку свого. Я ж, [Господи], уповаю на Тебе."],"x":{"2":"25.53.4","4":"9.17.1","11":"3.23.21","14":"50.26.23|53.13.18|54.1.16","18":"37.6.10","20":"25.9.8","22":"25.56.5","23":"50.6.25|52.12.22|56.5.7","24":"26.26.27|25.68.16|11.1.4"}},{"v":["Начальнику хору. Про голубку, що мовчить на самоті. Пісня Давида, коли филистимляни захопили його в Гефі.","Помилуй мене Боже, бо нападає на мене чоловік і день у день гнобить мене.","Щодня нападають на мене вороги мої, бо багато тих, що поборюють мене.","Вдень я не буду боятися, бо уповаю на Тебе.","Богом я хвалюсь у словах моїх, на Бога покладаю надію і не боюся; що зробить мені плоть?","Щодня зневажають слова мої, всі думки їхні про мене — на зло.","Збираються й ховаються, стежать за кожним кроком моїм, щоб уловити душу мою.","Вони гадають, що не покараєш Ти їх за неправду їхню.","Боже, Тобі відомі всі страждання мої; збери сльози мої та поклади їх перед Собою. Запиши їх у книгу Твою.","Вороги мої втікають від мене, коли я кличу Тебе. З того знаю, що Ти, Боже, зі мною.","Богом я хвалюся в словах, в Господі хвалю слово Його.","На Бога я уповаю і не боюся: що заподіє мені людина?","В мені, Боже, молитва до Тебе, щоб возносити Тобі хвалу,","бо Ти визволив душу мою від смерти, [очі мої від сліз], ноги мої від спотикання. Буду ходити перед лицем Господа у світлі живих."],"x":{"1":"8.21.10-11","5":"31.51.8|56.3.12|75.13.6","10":"32.29.12","12":"25.117.6"}},{"v":["Начальнику хору. Не погуби. Молитва Давида, коли він утік від Саула в печеру.","Помилуй мене, Боже, помилуй мене, бо на Тебе надіється душа моя, і в тіні крил Твоїх я сховаюсь, аж доки перейде беззаконня.","Буду взивати до Бога Всевишнього, Який допомагав мені.","Він пошле поміч з неба і спасе мене. Пошле Бог милість Свою й істину Свою і осоромить тих, що шукають погубити мене.","Душа моя серед звірів, я серед людей, що дишуть полум’ям, зуби їхні, як списи, і язик їхній — меч гострий.","Вознесися над небесами, Боже, і по всій землі слава Твоя.","Сітку поставили вони для ніг моїх і ловлять душу мою; викопали для мене яму і самі впали в неї.","Готове серце моє, Боже; готове серце моє: буду співати і славити Тебе.","Вставай, славо моя! Встаньте, псалтир і гуслі! Встану я рано.","Буду славити Тебе, Господи, між народами, буду оспівувати Тебе між людьми.","Бо до небес піднеслася милість Твоя і до хмар істина Твоя.","Вознесися над небесами, Боже, і по всій землі слава Твоя."],"x":{"1":"8.22.1","2":"25.50.3","4":"25.55.3","5":"25.54.22","6":"25.107.6","7":"25.7.16|26.26.27|27.10.8","8":"25.107.2","9":"25.107.3","10":"25.107.4","11":"25.35.6","12":"25.56.6"}},{"v":["Начальнику хору. Не погуби. Псалом Давида.","Чи правду говорите ви, сильні; чи за правдою судите ви, сини людські?","Ні, беззаконня складаєте ви в серці. Неправду сплітають руки ваші на землі.","Від правди відступили грішні, від народження свого, від утроби матері блудять, кажучи неправду.","Отрута в них, як у змії, як у глухого аспида, що затикає вуха свої,","щоб не чути того, хто проклинає, хоч би й як умів він заклинати.","Боже, сокруши зуби їхні у щелепах їхніх. Розірви, Господи, пащі звірів.","Нехай щезнуть вони, як вода розлита, а коли пустять вони стріли свої, нехай вони не матимуть сили.","Нехай упаде на них вогонь, щоб розтанули, як віск, і вже не побачили сонця.","Раніше, ніж закиплять котли злоби їхньої, нехай буря гніву Божого рознесе вогонь їхній.","А праведник звеселиться, коли побачить помсту Божу та пройде ногами по крові нечестивців.","І скажуть люди: «Справді добре бути праведним! Бо є Бог, є Суддя справедливий на землі!»"],"x":{"3":"26.21.29","4":"25.115.2","5":"25.139.4","6":"31.48.8","7":"25.3.8","8":"32.17.11","9":"24.3.16|27.6.10","10":"9.23.6|36.2.6","11":"76.14.20","12":"27.3.17|32.9.24"}},{"v":["Начальнику хору. Не погуби. Молитва Давида, коли Саул послав стерегти дім його, щоб умертвити його.","Визволи мене від ворогів моїх, Боже мій, від тих, що повстали на мене, захисти мене.","Спаси мене від тих, що чинять беззаконня, і від кровожерних врятуй мене.","Бо ось вони підстерігають душу мою, збираються на мене сильні, не за беззаконня мої і не за гріх мій.","Господи! Без провини моєї вони йдуть на мене. Встань же на допомогу мені і поглянь.","Господи, Боже Сил, Боже Ізраїлів, встань, відвідай усі народи, не помилуй нікого з тих, що чинять беззаконня.","Щовечора сходяться вони, жадібні до крови, як пес, і обходять місто.","Ось вони лихословлять язиками своїми, в устах їхніх не слова, а мечі, бо думають: хто їх чує?","Але Ти, Господи, посмієшся з них, осоромиш усі народи.","Сила моя в Тобі, Боже! Ти Заступник мій.","Ти — Бог мій, і милість Твоя попередить мене. Бог дасть мені перемогу над ворогами моїми.","Не убивай їх, щоб люди не забули Закону Твого. Розвій їх силою Твоєю, Захиснику мій, Господи.","Слова уст їхніх — то гріх душі їхньої; хай будуть спіймані у гордині їхній за прокльони їхні та за неправду, яку вони говорять.","Розвій їх гнівом Твоїм так, щоб не стало їх, та щоб пізнали люди, що Бог володіє народами в усіх кінцях землі.","Вони сходяться вечорами, спраглі крови, як пси, і обходять місто.","Вони шукають поживи, але неситі лягають спати.","А я буду оспівувати силу Твою, щоранку прославлятиму милість Твою, бо Ти був оборонцем моїм і захисником моїм у час біди моєї.","Сило моя! Тобі я буду співати, бо Ти Заступник мій і Бог мій, Який милує мене."],"x":{"1":"8.19.11","4":"25.55.7","5":"25.43.24","6":"31.26.21","8":"26.25.18","9":"25.2.4|25.36.13","10":"25.53.9","13":"25.35.4","14":"25.55.8","16":"40.8.11-12"}},{"v":["Начальнику хору. На музичному інструменті шушан-едуф. Псалом Давида,","коли він воював з Сирією Месопотамською і з Сирією Цованською, коли Іоав, повертаючись, знищив дванадцять тисяч ідумеїв у долині Соляній.","Боже! Ти розгнівався на нас, відвернувся від нас і покарав нас. Але змилуйся над нами!","Ти потряс землю, порушив її; зціли рани її, бо вона захиталася.","Ти дав людям Твоїм зазнати гіркоти, напоїв нас вином скорбот.","Дай же знамення тим, що бояться Тебе, щоб вони могли втекти від стріли ворожої.","Щоб спаслися улюблені Твої, спаси їх правицею Твоєю і вислухай мене.","Бог сказав у святині Своїй: «Возрадуюся, і розділю Сихем, і долину Сокхоф розміряю.","Мій Галаад, Мій Манассія, Єфрем — твердиня глави Моєї, Іуда — цар Мій.","Моав — чаша уповання Мого; на Едом покладу чобіт Мій. Чужинці скорилися Мені».","Хто введе мене в укріплене місто? Або доведе мене до Едому?","Чи не Ти, Боже, що відвернувся від нас і не виходиш, Боже, з військом нашим?","Пошли нам поміч у скорботах, бо марна допомога людська.","З Богом ми покажемо силу, і Він подолає гнобителів наших."],"x":{"2":"9.8.1|12.18.3:12","3":"25.43.10","4":"13.7.14","5":"25.74.9","8":"25.107.8","10":"9.8.2|31.21.11","12":"25.43.10","14":"25.17.30|25.107.14"}},{"v":["Начальнику хору. На струнному інструменті. Псалом Давида.","Почуй, Боже, молитву мою, вислухай благання моє.","Від краю землі взиваю до Тебе, бо ниє серце моє. Виведи мене на скелю, що для мене недосяжна.","Бо Ти — Надія моя, Ти — Скеля моя, Ти — Захист мій від ворога.","Дай мені, Боже, навіки оселитися в оселі Твоїй та знайти спокій під покровом крил Твоїх.","Бо Ти, Боже, почув молитви мої і дав мені насліддя з тими, що бояться імені Твого.","Дні до днів цареві приклади і роки його продовжи від роду до роду.","Хай буде він вічно перед Богом; милість і істина нехай охороняють його.","Я буду співати імені Твоєму повіки і сповнятиму обітниці мої кожного дня."],"x":{"2":"25.5.2|25.53.4","3":"25.17.7|31.33.16","4":"25.70.3","5":"25.35.8","7":"25.20.5","8":"9.7.12-13","9":"25.49.14"}},{"v":["Начальнику хору Ідифумового. Псалом Давида.","Тільки в Богові спокій душі моїй, тільки від Нього спасіння моє.","Тільки Він — Твердиня моя і Спаситель мій, Заступник мій, і не похитнуся повіки.","Доки будете нападати на людину? Ви всі налягаєте, мов стіна, що похилилася, або мур, що розвалюється.","Вони задумали скинути його з висоти, кривлять душею: устами благословляють, а в серці проклинають.","Тільки в Богові спокій, душе моя, тільки на Нього надія моя.","Він — Бог мій і Спаситель мій, Заступник мій, і не похитнуся повіки.","У Богові спасіння моє і слава моя. Бог — поміч моя і пристановище моє.","Уповайте на Нього, всі народи, виливайте перед Ним серця ваші, бо Він захист наш.","А сини людські — тільки суєта, сини сильних — тільки неправда. Якщо покласти їх на ваги, то всі вони легші за порожнечу.","Не надійтеся на грабіжництво, не вдавайтеся до насильства, а коли багатство примножується, не віддавайте йому серце.","Один раз сказав Бог, і двічі чув я, що вся сила в Богові.","і в Тебе, Господи, милість, бо Ти даєш кожному за ділами його."],"x":{"1":"25.38.1","2":"25.36.7","3":"25.17.3","4":"31.30.13","5":"25.27.3|32.9.8","7":"13.25.8","9":"25.4.6|8.1.15|24.30.16","10":"25.38.6|31.40.23|37.4.32","11":"50.19.24|52.12.19-20|71.6.9:17","13":"24.34.11|26.24.12|32.32.19|36.33.20|50.16.27|62.2.6"}},{"v":["Псалом Давида, коли він був у пустелі Юдейській.","Боже, Боже мій, до Тебе з ранку лину я, жадає Тебе душа моя, за Тобою знемагає плоть моя в землі пустельній, непрохідній і безводній.","Як у святиню явився я до Тебе, щоб бачити силу Твою і славу Твою.","Бо милість Твоя краща за життя, уста мої прославлятимуть Тебе.","Так благословлятиму Тебе в житті моїм, і в ім’я Твоє піднесу руки свої.","Як ситтю та єлеєм, наповнюється душа моя, і голосом радости вихваляють Тебе уста мої,","коли згадую Тебе на постелі моїй і в усі години ночі розмірковую про Тебе,","бо Ти єси Помічник мій, і під покровом крил Твоїх возрадуюся.","Припала душа моя до Тебе, і правиця Твоя підтримує мене.","Ті ж, що даремно шукають душу мою, впадуть у безодню підземну,","уразить їх сила меча, стануть здобиччю лисів.","Цар же звеселиться в Бозі: прославиться кожний, хто клянеться Ним, і замовкнуть уста тих, що говорять неправедно."],"x":{"1":"8.23.14","2":"31.26.9|25.41.3","3":"25.22.6|25.26.4","7":"25.34.28","8":"25.16.8","9":"31.41.10","10":"3.16.32|4.6.13|31.19.18|32.4.2"}},{"v":["Начальнику хору. Псалом Давида.","Почуй, Боже, голос мій у молитві моїй. Від лютого ворога охорони життя моє.","Укрий мене від намірів злодіїв і від зборища беззаконників.","Вони наче меч нагострили язик свій і, мов стріли, кидають слова образи,","щоб таємно стріляти в неповинного; стріляють в нього несподівано і не бояться.","Вони утвердились у злому намірі, змовляються поставити таємно сітку і кажуть: хто їх побачить?","Вони вигадують всіляку неправду, вишукують, розслідують, заглядають аж до глибини серця.","Але уразить їх Бог стрілою. Несподівано стріла Божа вдарить їх.","Вони покарають себе своїми ж словами. Всі, хто побачить їх, відійдуть від них.","І нападе страх на всіх людей, вони сповістять про діла Божі, бо зрозуміють, що то — Його діло.","Звеселиться праведник у Господі і уповає на Нього. І похваляться всі праведні серцем."],"x":{"4":"25.54.22|25.58.8|32.9.3","6":"24.22.13|24.24.15","7":"32.17.9","9":"25.7.16","10":"1.8.19|20.8.17","11":"25.31.11"}},{"v":["Начальнику хору. Псалом Давида для співу.","Тобі подобає пісня, Боже, в Сионі, і Тобі піднесеться молитва [в Єрусалимі].","Почуй молитву мою. До Тебе приходить всяка плоть.","Безліч гріхів перемагає нас, але Ти очистиш беззаконня наші.","Блаженні, кого Ти обрав і прийняв, щоб він оселився у дворах твоїх. Наситимось добром дому Твого, святого храму Твого.","Дивний у правосудді, вислухай нас, Боже Спасителю наш, надія всіх кінців землі і тих, що в морі далеко.","Ти Той, що поставив гори силою Твоєю і підперезаний могутністю.","Ти втихомирюєш бурхливість моря, шуми хвиль його і повстання народів.","Устрашаться від знамень Твоїх усі, що живуть на землі. Ранок і вечір красою прославлять Тебе.","Ти дбаєш про землю і напуваєш її, примножуєш багатства її. Ріка Божа повна води. Ти вирощуєш хліб від землі, бо так впорядкував її.","Ти напоюєш борозни її, рівняєш груди її, дощами пом’якшуєш її та прикрашаєш її рослинами.","Ти благословиш вінець року благости Твоєї, і поля Твої сповняться врожаєм.","Вкриється травою пустеля, і радістю узгір’я наповняться.","Долини наповнюються отарами, і лани покриваються пшеницею. Все радіє, все співає."],"x":{"2":"25.49.14","3":"25.144.21|32.32.27","7":"40.4.13","8":"25.106.29|50.8.26","10":"4.11.11|4.33.28|25.45.5","12":"4.11.11"}},{"v":["Викликніть Господу, вся земле!","Співайте ж імені Його, віддайте славу й хвалу Йому.","Промовляйте Богові: «Як величні діла Твої, перед множеством сили Твоєї скоряться Тобі вороги Твої».","Вся земля нехай поклониться Тобі й співає Тобі. Нехай співає імені Твоєму, Всевишній!»","Прийдіть, погляньте на діла Божі, Який страшний Він у Своїх ділах над синами людськими!","Він море обернув на сушу, ріку перейшли ногами. Там ми веселилися в Ньому.","Він могутністю Своєю світом володіє вічно. Очі Його дивляться на всі народи, щоб не підносились у собі гнобителі.","Благословляйте, народи, Бога нашого і проголошуйте хвалу Йому.","Він дав життя душі нашій і не попустив, щоб ноги наші захиталися.","Ти випробував нас, Боже, Ти переплавив нас, як переплавляється срібло.","Ти попустив нам потрапити в сітку, поклав тягарі на плечі наші.","Ти допустив, щоб чужі люди сіли на шию нам. Ми йшли через вогонь і воду, але Ти вивів нас на волю.","Увійду в дім Твій з жертвами всепалення, виконаю перед Тобою обітниці мої,","що їх проголосили уста мої і висловив язик мій у скорботі моїй.","Великі жертви принесу Тобі з пахощами, принесу Тобі овець, волів і козлів.","Прийдіть усі, хто боїться Бога, послухайте мене, і я скажу вам, що вчинив Він для душі моєї.","Я взивав до Нього устами моїми і величав Його язиком моїм.","І якби була неправда в серці моїм, то не почув би мене Господь.","А Господь почув мене і прихилився до голосу благання мого.","Благословенний Господь, що не відкинув моління мого і милости Своєї не відвернув від мене."],"h":"Начальнику хору. Пісня.","x":{"2":"25.99.1","3":"4.33.29","5":"25.45.9","6":"1.14.21-22|5.3.16-17","10":"56.1.7|36.22.21","12":"31.43.2|37.3.17","18":"26.15.29|26.28.9"}},{"v":["Начальнику хору. На струнних інструментах. Псалом. Пісня.","Боже, ущедри нас і благослови нас, просвіти лице Твоє на нас і помилуй нас.","Щоб пізнали ми на землі путь Твою, в усіх народах — спасіння Твоє.","Нехай сповідують Тебе люди, Боже, нехай сповідують Тебе люди всі.","Нехай веселяться і радіють племена, бо Ти судиш народи праведно і керуєш всіма племенами на землі.","Нехай славлять Тебе народи, Боже, нехай славлять Тебе народи всі.","Земля дає плід свій: благослови нас, Боже, Боже наш.","Нехай благословить нас Бог, і нехай бояться Його всі краї землі."],"x":{"2":"3.6.25|68.1.15","4":"62.15.11","5":"54.17.31","7":"2.26.4|25.84.13","8":"4.6.25"}},{"v":["Начальнику хору. Псалом Давида. Пісня. (Пророчий).","Нехай воскресне Бог і розвіються вороги Його; нехай побіжать від лиця Його всі ненависники Його.","Як щезає дим, нехай щезнуть, як тане віск від лиця вогню, так нехай згинуть грішники від лиця Божого.","А праведники нехай звеселяться, нехай радіють перед Богом, нехай святкують у радості.","Співайте Богові, співайте імені Його, рівняйте дорогу перед Тим, Хто йде, як Переможець. Господь — ім’я Йому, радійте перед лицем Його.","Отець сиріт і Суддя вдовиць — Бог, Він у святих оселях Своїх.","Бог одиноких вводить у дім; визволяє в’язнів із кайданів, а непокірні живуть у гробах.","Боже, коли йшов Ти поперед народу Твого, коли проходив Ти через пустелю,","земля тряслася, навіть небеса танули від лиця Божого, і Синай — від лиця Бога, Бога Ізраїлевого.","Рясний дощ проливав Ти, Боже, на насліддя Твоє, і коли знесилювалося воно, Ти підкріпляв його.","Народ Твій Ти оселив на землі Твоїй, і з благости Твоєї Ти все приготував для бідного.","Господь дасть слово тим, що благовістять з великою силою.","Царі з військом утікають, утікають, а ті, що сидять вдома, ділять здобич.","Коли ж ви оселялися на землях [своїх], то стали мов голубка, у якої крила — як срібло, а пір’я сяє золотом.","Коли ж Всевишній розсіяв царів на цій землі, вона забіліла, як сніг на горі Селмоні.","Гора Божа — гора велика, гора кріпка, гора висока.","Чого ви заздрите, гори високі, на гору, що на ній Бог благоволив жити і буде перебувати на ній вічно?","Колісниць Божих тьма і тисячі тисяч. Серед них Господь на Синаї, у святині.","Ти зійшов на висоту, полонив полон, прийняв дари для людей, щоб і непокірні могли жити у Господа.","Господь Бог благословенний; благословенний Господь допоможе нам кожного дня.","Бог — Спаситель наш, Бог наш, Бог, щоб спасати. У владі Господа ворота смерти.","Бог сокрушить голови ворогів Своїх, волохате тім’я того, хто закам’янів у беззаконні.","Сказав Господь: «Від Васана поверну тебе, виведу з глибини моря,","щоб обмочив ти ногу твою, як пси язик свій, у крові ворога».","Ми бачили, як ішов Ти, Боже, як ішов Ти — Цар мій і Бог мій — у святиню.","Попереду князі і ті, що співали, за ними — ті, що грали на струнах, а кругом — діви з тимпанами.","В церквах благословляйте Бога — Господа від джерел Ізраїлевих.","Там Веніамін молодший — князь їхній, князі Іуди — владики їхні, князі Завулонові, князі Неффалимові.","Бог твій дав тобі таку силу. Утверди, Боже, те, що Ти створив для нас.","Ради храму твого в Єрусалимі царі принесуть Тобі дари.","Утихомир звіра, що в очереті, зібрання биків серед тихих телят — гордих народів, що хваляться сріблом своїм; розвій тих, що готують війни.","Прийдуть з Єгипту вельможі молитися; Ефіопія простягне руку свою до Бога.","Царства землі! Хваліть Бога, оспівуйте Господа,","Який зійшов на небо небес превічно. Ось Він дає голосу Своєму голос сили.","Віддайте славу Богу; на Ізраїлі велич Його і могутність Його на хмарах.","Дивний Бог у святих Своїх, Бог Ізраїлів; Він дає силу й твердість народу [Своєму]. Благословенний Бог!"],"x":{"2":"3.10.35","3":"19.16.15","4":"25.63.11","5":"31.40.3|31.57.14","6":"25.145.9|53.14.18","7":"25.112.9","8":"1.13.20|3.14.14","9":"1.20.18","10":"31.32.15|31.44.3|39.2.28","12":"31.52.7","15":"6.9.48","17":"25.113.4","18":"4.33.2","19":"66.4.10","21":"4.32.39|8.2.6|29.16.13","23":"3.21.33","24":"25.57.11|76.14.20","26":"1.15.20|8.18.6","27":"25.21.23|53.20.17","30":"25.71.10|31.60.6","32":"31.18.7","34":"25.28.3|48.9.14|76.4.5"}},{"v":["Начальнику хору. На шошаннимі. Псалом Давида. (Пророчий).","Спаси мене, Боже, бо води дійшли до душі [моєї].","Я загруз у глибокім болоті, і нема на чому стати. Зійшов я у глибину моря, і хвилі його заливають мене.","Я знемігся від благань, і гортань моя зашерхла. Втомилися очі мої від очікування Бога [мого].","Бо тих, що ненавидять мене без вини, більше, ніж волосся на голові моїй. Вороги мої, що переслідують мене даремно, зміцніли, і чого я не відбирав, того вимагають від мене.","Боже, Ти знаєш, як тяжко мені, і гріхи мої не втаєні від Тебе.","Нехай не осоромляться через мене ті, що надіються на Тебе, Господи, Боже Сил. Нехай не осоромляться через мене ті, що шукають Тебе, Боже.","Бо ради Тебе терплю я зневагу, і сором покриває лице моє.","Я став чужим для братів моїх і стороннім для синів матері моєї.","Бо ревність до дому Твого з’їдає мене, і зневага тих, що Тебе зневажають, впала на мене.","Коли я плакав і постом смиряв душу мою, то й тим докоряють мене.","Замість одежі я обгортав себе веретищем — і тим став посміховиськом для них.","Про мене говорять ті, що сидять біля воріт, про мене співають ті, що п’ють вино.","А я з молитвою моєю до Тебе, Господи, в час, угодний Тобі, Боже. З великої милости Твоєї, почуй мене в істині спасіння Твого.","Виведи мене з болота, щоб не потонув я, спаси мене від ненависників моїх і від глибокої води.","Нехай не затопить мене буря повені, нехай не потону я в глибині.","Вислухай мене, Господи, бо велика милість Твоя, заради великих щедрот Твоїх зглянься на мене.","Не відверни лиця Твого, бо я сумую, скоро почуй мене.","Поглянь на душу мою і спаси її, від ворогів моїх спаси мене.","Ти знаєш приниження моє, ганьбу мою і сором мій. Вороги мої всі перед Тобою.","Наруга сокрушила душу мою, і страждання. Я знеміг. Я очікував, що хтось буде співчувати мені, і не було, очікував, хто б заспокоїв мене, і не знайшлося.","І дали в їжу мені жовч і у спрагу мою напоїли мене оцтом.","Нехай буде трапеза їхня тенетами їм, і мирна вечеря — пасткою.","Нехай потемніють очі їхні, щоб не бачили, і спини їхні назавжди зігни.","Вилий на них гнів Твій, і полум’я його нехай обійме їх.","Нехай житло їхнє стане пустим, і в наметах їхніх нехай не залишиться нікого живого.","Бо кого покарав Ти, над тим вони ще й знущаються. І тому, кого поранив Ти, вони ще збільшують страждання.","Збери докупи всі беззаконня їхні, і нехай не увійдуть вони в правду Твою.","Нехай буде викреслено їх із книг живих, і між праведними нехай не напишуться.","А я бідний і страждаю, поміч Твоя, Боже, нехай визволить мене.","Я буду славити в піснях ім’я Бога [мого], буду прославляти Його хвалою.","І це буде більш приємне Господу, ніж жертви волів і телят з рогами і копитами.","Побачать це принижені і звеселяться. І оживуть серця ваші, ви, що шукаєте Господа.","Бо почув Господь убогих Своїх і не забув в’язнів Своїх.","Нехай хвалять Його небо і земля, море і все, що живе в них.","Бо спасе Господь Сион, і збудує міста Іуди для людей Своїх, і поселяться там, і будуть нащадками Його.","І нащадки рабів Його утвердяться в ньому, і ті, що люблять ім’я Його, будуть жити в ньому."],"x":{"2":"31.43.2","3":"25.39.3|25.41.8","5":"25.34.19|31.53.4|36.33.15","10":"53.2.17|62.15.3","13":"24.30.9","14":"31.49.8","15":"25.39.3","18":"25.101.3","20":"25.43.16","21":"50.27.39|52.23.49","22":"50.27.34:48|53.19.29","23":"62.11.9","26":"54.1.20","27":"31.53.4","28":"62.1.28","29":"52.10.20|67.4.3|76.3.5","33":"25.21.27","34":"25.33.7","35":"25.147.1","36":"63.3.10"}},{"v":["Начальнику хору. Псалом Давида. На спомин.","Боже, на поміч мені прийди, Господи, поспіши допомогти мені.","Нехай постидяться й осоромляться ті, що шукають душі моєї.","Нехай відступлять осоромленими ті, що шукають загибелі моєї. Нехай біжать назад ті, що кажуть [мені]: «Добре, добре!»","Але нехай зрадуються і звеселяться ті, що шукають Тебе, Боже. І ті, що люблять спасіння Твоє, нехай завжди кажуть: «Великий Господь!»","А я немічний і убогий: Боже, допоможи мені. Ти — Поміч моя і Спаситель мій. Господи, не забарись."],"x":{"3":"25.34.4","4":"25.34.21"}},{"v":["На Тебе, Господи, я уповаю, не дай мені осоромитися повік.","Правдою Твоєю врятуй мене і визволи мене, прихили до мене вухо Твоє і спаси мене.","Будь мені Богом Захисником, твердинею пристановища, щоб спасти мене.","Боже мій, визволи мене з руки нечестивого, з руки беззаконника, що гнобить мене.","Бо Ти надія моя, Господи Боже мій, надія моя від юности моєї.","В Тобі утвердився я від утроби матері моєї, від народження мого Ти мій покровитель, і Тобі хвала моя завжди.","Для багатьох я був наче диво, але Ти тверда моя надія.","Нехай наповняться уста мої хвалою Тобі, [щоб я оспівував славу Твою і] кожен день — велич Твою.","Не покинь мене в час старості, коли буде покидати мене сила моя. Не залиш мене.","Бо вороги мої говорять проти мене, і ті, що підстерігають душу мою, радяться між собою,","кажучи: «Бог покинув його, переслідуйте і схопіть його, бо нема визволителя».","Боже, не віддаляйся від мене. Боже, на поміч мені прийди.","Нехай осоромляться, нехай щезнуть усі, що повстали на душу мою. Нехай покриють сором і безчестя тих, що шукають загибелі моєї.","А я завжди буду уповати [на Тебе] і примножувати всяку похвалу Тобі.","Уста мої будуть звіщати правду Твою, кожен день — благодіяння Твої, що їм я не знаю числа.","Завжди буду думати про силу Господа Бога, згадувати правду Твою. Тільки Твою, Боже.","Ти навчав мене від юности моєї, і донині я сповіщаю про чудеса Твої.","І до старості, і до сивини не покинь мене, Боже, доки не розкажу про силу Твою всьому народові і всьому грядущому про могутність Твою.","Правда Твоя, Боже, до небес. Великі діла вчинив Ти; Боже, хто подібний до Тебе?","Ти посилав на мене люту біду, але знову оживляв мене і з безодні землі виводив мене.","Ти показав на мені правосуддя Твоє, але, обернувшись, Ти втішав мене [і з безодні землі знову виводив мене],","тому буду прославляти Тебе знову між народами, на струнних органах славитиму істину Твою, Боже. Буду оспівувати Тебе на гуслях, святий Ізраїлів.","Радіють уста мої, коли співаю Тобі, і душа моя, яку Ти визволив;","і язик мій щодня буде прославляти правду Твою, бо осоромлені ті, що шукали загибелі мені."],"h":"(Псалом Давида.)","x":{"1":"25.30.2-3","3":"50.4.6|52.4.10","4":"25.90.14","5":"75.2.13","6":"4.10.21|25.21.10","7":"36.12.6|36.24.27","8":"25.50.17","9":"25.68.4|31.46.4","12":"25.69.2","13":"25.34.4","17":"25.76.12","18":"31.46.4","19":"1.15.11|76.17.14","20":"25.67.23","21":"4.32.39","22":"25.88.19|25.150.3"}},{"v":["Боже, Суд Твій цареві дай і синові царя — правду Твою.","Щоб судив справедливо народ Твій, і вбогих Твоїх — судом праведним.","Щоб гори принесли мир людям, і пагорби — правду.","Щоб судив убогих у народі, спасав синів бідних та смирив гнобителя.","Він раніше сонця, раніше місяця з роду в рід.","Він зійде, як дощ на траву, і як роса, що падає на землю.","В часи днів його засяє правда і буде великий мир, аж доки світить місяць.","І заволодіє від моря до моря, і від ріки* — до краю землі.","Скоряться перед ним жителі пустелі, і вороги його перед ним уклоняться до землі.","Царі фарсійські з островів дари піднесуть, царі Аравії і Сави дари принесуть.","І вклоняться Йому всі царі землі, і всі народи будуть служити йому.","Бо він визволить безсилого від сильного, і убогого, що не мав захисника.","Буде милостивий до вбогих і бідних, і душі їхні спасе.","Від кривди і від насильства спасе душі їхні, і кров їхня буде дорогоцінна перед очима його.","І буде він жити, і принесуть йому золото Аравії; будуть молитися за Нього, завжди і щодня будуть благословляти його.","Буде достаток хліба на землі і на верхах гір; плоди його піднесуться вище Ливану, і розмножаться люди, як трава на землі.","Нехай буде ім’я його [благословенне] навіки; раніше сонця перебуває ім’я його, і в ньому благословляться [всі покоління землі] і всі народи будуть прославляти його.","Благословен Господь, Бог Ізраїлів, що творить чудеса єдиний.","І благословенне ім’я слави Його повіки. Славою Його буде повна вся земля. Амінь. Так буде. Амінь.","Закінчилися молитви Давида, сина Ієссеєвого."],"h":"Про Соломона. [Псалом Давида.] (Про Христа).","x":{"1":"37.7.27|31.11.5","2":"31.32.1","3":"10.4.24|66.2.14","4":"25.44.5|31.11.4","5":"32.31.36","6":"6.6.36-37|9.23.4","7":"31.35.1|38.14.6","8":"10.4.21","10":"25.44.13","11":"25.21.30|76.21.24","13":"53.5.7","15":"31.53.10|75.7.16","16":"31.27.6|38.14.6|48.10.8","17":"0.12.3|65.3.8:16","18":"12.16.36|52.1.68","19":"31.6.3"},"n":{"8":["Євфрат."]}},{"v":["Який милостивий Бог Ізраїлів до народу Свого, до чистих серцем!","Мої ж мало не похитнулися ноги, мало не посковзнулися стопи мої.","Я позаздрив безумним, бачивши добробут беззаконних.","Бо нема їм страждання, й до смерти їхньої міцні сили їхні.","У трудах людських їх нема, і не знають вони людської біди.","Тому-то гордість підняла їхню пихатість, і, як в одежу, одягаються вони у неправду та нечестя свої.","Пливе, наче олива, неправда їхня, живуть за похотями свого серця.","З усього глузують, зневажливо говорять про Бога, звисока розмовляють.","До небес підносять уста свої, і язик їхній обходить землю.","Тому звертаються до них люди і п’ють їхню воду повною чашею,","і кажуть: «Як довідається Бог? І чи знає Всевишній?»","І ось ці нечестивці завжди живуть у достатку і примножують багатство.","[І я сказав: ] «Чи не даремно я дбаю про чистоту серця і в невинності умивав руки мої;","віддавав себе під удари щодня і щоранку себе осуджував?»","Але коли б я сказав: «Буду і я так жити», то я став би зрадником перед родом синів Твоїх.","І я став думати, як би мені все це зрозуміти, але тяжким було це в очах моїх.","Аж поки не ввійшов я у святиню Божу та не зрозумів кінця їхнього.","Дійсно, на слизькій дорозі поставив Ти їх, над прірвою стоять вони.","Як несподівано прийшли вони до занепаду! Щезли, погинули за беззаконня свої.","Як щезає сон того, хто прокинувся, так Ти, Господи, розбудивши їх, знищив помисли їхні у місті Твоїм.","Коли хвилювалося серце моє і боліла душа моя,","я був нерозумним, я як тварина був перед Тобою.","Але я завжди з Тобою, Ти тримаєш мене за праву руку мою.","Ти порадою Твоєю провадиш мене, і до слави Твоєї Ти приймеш мене.","Хто бо для мене є на небі? І чого без Тебе бажати мені на землі?","Знемагають серце моє і тіло моє за Тобою, Боже серця мого і доле моя, Боже, навіки.","Бо ось ті, що віддалили себе від Тебе, гинуть. Ти знищуєш кожного, хто відступає від Тебе.","А мені найкраще прихилятися до Бога, покладати на Господа надію мою, сповіщати про всі діла Твої в Церкві Твоїй [у вратах дочки Сионової]."],"h":"Псалом Асафа.","x":{"1":"25.63.9|50.5.8|53.1.47","3":"25.36.1|24.21.7|32.12.1","7":"24.15.27","9":"30.13.28","11":"25.9.32|25.93.7","13":"49.3.14|24.9.30","18":"24.21.16-17|26.14.32","19":"24.21.30|25.51.7","20":"24.21.17|31.29.7","22":"53.12.16","23":"53.6.68","25":"25.15.5|53.4.14","26":"33.3.24","27":"32.17.13|38.7.13","28":"55.4.8"}},{"v":["Навіщо, Боже, відкинув Ти нас назавжди? Навіщо розпалився гнів Твій на овець стада Твого?","Пом’яни людей Твоїх, яких спочатку зібрала рука Твоя. Ти обрав, як жезл насліддя Твого, гору Сион, на якій оселився Ти.","Піднеси руку Твою і поглянь на злочинство їх: що наробив ворог у святині Твоїй — у храмі Твоїм!","Як звірі, рикають вороги Твої у храмі зібрання Твого. Поставили знамена свої замість знамен наших.","Наче в гущавині лісовій, високо змахували сокирами.","Всі двері і всі оздоби ломами та молотами порозбивали.","Вогнем спалили святиню Твою на землі, осквернили оселю імені Твого.","Сказали вони в серці своїм: «Зруйнуємо їх зовсім». І спалили всі міста зібрань Божих на землі.","Знамен наших ми вже не бачимо, нема вже й пророка. І нема між нами такого, хто сказав би, доки це буде.","Доки, Боже, буде ворог мучити нас, доки противник буде ображати ім’я Твоє?","Навіщо відхиляєш руку Твою і силу Твою? Гнівом могутности Твоєї урази їх.","Бог же, Цар наш, раніше віків учинив спасіння посеред землі.","Ти розділив силою Твоєю море, Ти знищив голови зміїв у воді.","Ти розбив голову дракона, дав його на поживу людям [ефіопським].","Ти відкрив джерела й потоки, і Ти ж висушив великі ріки.","Твій день і Твоя ніч. Ти створив зорі і сонце.","Ти поставив межі землі, і Ти ж установив літо й зиму.","Згадай це: ворог зневажає Господа, і люди нечестиві ображають ім’я Твоє.","Не віддавай звірам душ тих, що прославляють Тебе. Душ убогих Твоїх не забудь до кінця.","Подивись на завіт Твій, бо всі темні місця землі наповнилися домами беззаконня.","Нехай не повернеться смиренний осоромленим, принижений і убогий нехай прославляють ім’я Твоє.","Встань, Боже, захисти діло Твоє, згадай зневажання Тебе від беззаконного кожен день.","Не забудь голосу тих, що благають Тебе, бо гординя тих, що ненавидять Тебе, підіймається проти Тебе завжди."],"h":"Псалом Асафа. (Повчання.)","x":{"1":"25.43.24","2":"25.67.17|39.3.16","4":"32.2.15","7":"11.25.9","9":"33.2.9","13":"1.14.21","15":"1.17.5-6|3.20.11|5.3.13","17":"0.8.22|33.3.61","21":"52.11.27","22":"31.49.4|36.39.25"}},{"v":["Начальнику хору. Не погуби. Псалом Асафа. Пісня.","Славимо Тебе, Боже, прославляємо Тебе, і призиваємо ім’я Твоє, про нього сповіщають чудеса Твої.","«Коли виберу час, каже Господь, Я буду судити за правдою.","Хоч захиталася земля і всі, що живуть на ній, Я утверджу стовпи її».","Я кажу нечестивцям: «Не беззаконствуйте!» І до злих: «Не надійтеся на силу свою!","Не підносьте високо ріг ваш і [не] говоріть [на Бога] неправду.»","Бо не від сходу й не від заходу, і не з гір пустелі піднесення.","А Бог є Суддя: одного принижує, а іншого підносить.","Бо чаша в руці Господній, в ній кипить вино, повне приправ, і Він наливає з неї; а гущу його вижмуть і вип’ють усі грішники землі.","Я ж буду радіти повік, буду співати Богу нашому.","Всі роги нечестивців зломлю, і піднесеться сила праведного."],"x":{"2":"25.9.2|25.43.2","4":"25.45.7","8":"37.5.21","9":"25.59.5","11":"52.1.69"}},{"v":["Начальнику хору. На струнних інструментах. Псалом Асафа. Пісня.","Знаний Бог в Юдеї, в Ізраїлі велике ім’я Його.","І була в Салимі оселя Його, і перебування Його на Сионі.","Там знищив Він стріли лука, щит і меч і війну.","Ти славний, і силою світиш з висот вічних.","Не встояли всі нерозумні серцем, заснули сном своїм і не знайшли сили в руках своїх.","Від гніву Твого, Боже Якова, заснули кінь і колісниця.","Страшний Ти, і хто встоїть перед лицем Твоїм у час гніву Твого?","З небес Ти сповістив суд; земля вжахнулась і замовкла,","коли встав Бог на суд, щоб спасти всіх пригноблених на землі.","І гнів людський обернеться на славу Твою; залишок гніву Ти приборкаєш.","Помоліться і віддайте хвалу Господу, Богу нашому; всі, хто навколо Нього, принесуть дари страшному.","Він смиряє дух князів, Він страшний для царів землі."],"x":{"3":"14.1.3","4":"25.45.10|31.9.4","7":"6.5.22","9":"76.6.17","11":"36.28.22","12":"25.60.9","13":"8.14.15|76.19.15"}},{"v":["Начальнику хору Ідифумового. Псалом Асафа.","Голосом моїм до Господа я буду взивати. Голос мій до Бога, і Він почує мене.","В день скорботи моєї шукав я Господа, вночі підносив руки мої і не опускав їх — душа моя не мала втіхи.","Згадував я Бога і тремтів, став роздумувати, і знемагав дух мій.","Не змикалися очі мої вночі, я сумував і не міг говорити.","Я роздумував про дні давні, пригадував роки віків минулих.","Вночі роздумувало серце моє і допитувався дух мій:","невже навіки відкинув мене Господь і не виявить більше до мене милости Своєї?","Невже назавжди спинилася милість Його і скінчилося слово Його з роду в рід?","Невже забув милувати Бог і в гніві Своїм зачинив щедроти Свої?","І я сказав: «Ось, горе мені — це зміна правиці Всевишнього».","Буду згадувати про діла Господні, згадувати від початку чудеса Твої.","Буду вдумуватися в усі діла Твої, роздумувати про всі діяння Твої.","Боже! Свята путь Твоя. Хто бог великий, як Бог [наш]?!","Ти єси Бог, що твориш чудеса. Ти показав між народами силу Твою.","Ти визволив силою Твоєю народ Твій — синів Якова та Йосифа.","Побачили Тебе води, Боже, побачили Тебе води й убоялися, затремтіли безодні.","З хмар лилися води, гриміли громи і стріли блискавиць летіли.","Голос грому Твого котився по небу, і блискавки Твої освітили всю піднебесну, земля захиталася й тряслася.","Шляхи Твої в морі, і стежки Твої — у водах великих, а сліди Твої недовідомі.","Як стадо, вів Ти народ Твій рукою Мойсея і Аарона."],"x":{"1":"25.38.1","3":"13.20.3|25.17.7|25.49.15","6":"25.142.5","7":"31.26.9","8":"25.12.2|25.84.6|33.3.31","10":"51.4.38","11":"31.41.10","12":"4.32.7|25.70.17|25.104.2","14":"25.88.9","15":"52.1.51","16":"1.14.19","17":"1.14.21","19":"24.37.5","20":"24.38.16|45.3.15","21":"1.14.15-16"}},{"v":["Слухайте, люди мої, закону мого, прихиліть вухо ваше до слів уст моїх.","Відкрию в притчах уста мої і розкажу загадки віків давніх.","Що ми чули і що взнали і що батьки наші розповідали нам,","не втаїмо перед дітьми їх, сповіщаючи роду майбутньому славу Господню, силу й чудеса Його, які Він створив.","Він дав свідчення в Якові, поставив закон у Ізраїлі і наказав батькам нашим переказати його дітям їхнім,","щоб знав рід майбутній — діти, що народяться, і щоб свого часу і вони сповістили дітям своїм.","Щоб надію свою покладали на Бога, і не забували діл Божих та додержували заповідей Його.","Щоб не були такі, як батьки їхні, рід непокірний і лукавий, рід непостійний у серці своїм та невірний Богові духом своїм.","Сини Єфремові озброєні, що стріляли з лука, повернули назад у день битви.","Вони не зберегли завіту Божого, в законі Його не захотіли ходити.","Забули діла Його і чудеса Його, що Він показав їм.","Він перед очима батьків їхніх сотворив чуда в землі Єгипетській на полі Цоан.","Він розділив море і перевів їх, поставивши воду стіною.","Вдень вів їх хмарою, а всю ніч — світлом вогню.","Розсік камінь у пустелі і напоїв їх, наче з великої безодні.","Із скелі вивів потоки, і води потекли, як ріки.","Вони ж не перестали грішити перед Ним та прогнівляти Всевишнього в пустелі.","Спокушали Бога в серці своїм, вимагаючи поживи душі своїй.","Говорили проти Бога й сказали: «Чи може нам Бог приготувати трапезу у пустелі?","Ось Він ударив по каменю, і потекли води, й полилися потоки, чи може Він дати й хліба? Чи може приготувати й м’яса народу Своєму?»","Почув це Господь, і запалав гнів Його, вогонь спалахнув на Якова. І гнів піднявся над Ізраїлем,","за те, що не вірили Богу і не уповали на спасіння Його.","Він наказав хмарам і відчинив двері неба.","Дощем послав їм манну на поживу, хліба небесного дав їм.","Хлібом ангельським живилися люди, поживи послав їм до ситости.","Він підняв у небі східний вітер і навів південний силою Своєю.","І, наче порох, сипав на них м’ясо — птахів крилатих, що сипалися на них, як пісок морський.","Накидав їх серед табору їхнього біля наметів їхніх,","і їли вони до переситу; те, чого бажали вони, дав їм.","Але, коли ще не вдовольнили бажання свого, коли ще їжа була на зубах їхніх,","гнів Божий прийшов на них і умертвив багатьох із них, і вибраних Ізраїля відкинув.","Але й тоді вони не переставали грішити і не вірили чудесам Його.","І минали дні їхні у марноті і роки їхні у тривозі.","Коли Він умертвляв їх, тоді вони шукали Його і навертались, і зранку благали Його.","І пригадували, що Бог — пристановище їхнє і Бог Всевишній — Спаситель їхній.","Вони ніби любили Його устами своїми і язиком своїм корилися Йому,","але серце їх не було праведне перед Ним, і завіту Його вони не виконували.","Він же, милосердний, прощав гріхи їхні і не знищував їх. Багато разів Він одвертав гнів Свій і зупиняв обурення Своє.","Він пам’ятав, що вони — тіло, вітер, що проходить і не повертається.","Скільки разів вони засмучували Його в пустелі і прогнівляли Його в краю безлюднім!","І знову спокушали Бога і ображали Святого Ізраїлевого,","не пам’ятали руки Його у день, коли Він визволив їх від гнобителя.","Коли явив їм знамення Свої в Єгипті і чуда Свої на полі Цоан.","Коли обернув ріки й потоки їх на кров, щоб не могли пити.","Наслав на них мух, щоб жалили їх, і жаб, щоб гноїли їх.","Віддав гусені врожаї їхні і ниви їхні сарані.","Побив градом виногради їхні і фигові дерева їхні ожеледдю.","Великий град побив тварин їхніх, а отари овець попалила блискавка.","Послав на них полум’я гніву Свого і кару люту через ангелів гніву.","Відкрив дорогу для гніву Свого і не охороняв від смерти душі їхні, а тварин їхніх віддав на загибель.","Уразив смертю кожного первістка в Єгипті, початки сили їхньої у наметах Хамових.","І підняв народ Свій, як овець, і повів його, як отару, по пустелі.","Провадив їх у надії і без страху, а ворогів їхніх покрило море.","І привів їх до країни святої Своєї, на гору, що її обрала правиця Його.","Прогнав народи від лиця їх, землю розділив у володіння їм і покоління Ізраїля оселив у наметах їхніх.","Але вони ще спокушали і засмучували Бога Всевишнього, і повелінь Його не виконували.","Відступали і зраджували, як і батьки їхні, ставали ненадійними, як лук зіпсований.","Прогнівляли Його висотами своїми й ідолами своїми накликали гнів Його.","Почув Бог, і запалав гнів Його на Ізраїля.","Він відринув скинію Силоамську, оселю Свою, в якій оселився між людьми.","І віддав у неволю силу їхню, і славу їхню — у руки ворогів.","Віддав під меч народ Свій і розгнівався на насліддя Своє.","Юнаків їхніх попалив вогонь, і дівам їхнім ніхто не співав шлюбних пісень.","Священики їхні загинули від меча, і вдовиці їх не оплаканими будуть.","Але встав, наче від сну, Господь, як силач, повалений вином.","І уразив у спину ворогів Своїх, на вічний сором віддав їх.","Він відкинув оселі Йосифа і коліна Єфремового не обрав.","А вибрав коліно Іуди — гору Сион, що її полюбив.","І збудував, наче небо, святиню Свою на землі, і утвердив її навіки.","І обрав Давида, раба Свого, від отар овечих покликав його.","Від доїння їх привів його пасти народ Свій — Якова, і насліддя Своє — Ізраїля.","І він пас їх у чистоті серця свого і руками мудрими водив їх."],"h":"Повчання Асафа.","x":{"2":"25.48.5|50.13.35","3":"25.43.2","5":"4.4.9","8":"4.32.5|36.2.3","9":"6.8.2|6.12.1|31.7.2|38.7.11","10":"11.17.15","13":"1.14.21","14":"1.13.21|25.104.39","15":"1.17.6|3.20.11|29.11.4|63.10.4","18":"3.11.4|25.105.14|63.10.9","21":"3.11.1","24":"1.16.14|3.11.7|29.16.2|53.6.31|63.10.3","30":"3.11.33","32":"4.1.32","39":"55.4.14","40":"3.14.22","44":"1.7.20|25.104.29","45":"1.8.24|25.104.31","46":"1.10.13","47":"1.9.23:25|25.104.33","50":"1.9.6","51":"1.12.29","52":"1.12.37","55":"5.12.7","58":"4.32.16","60":"8.4.11","64":"8.4.11","66":"8.5.6","70":"8.16.11|9.7.8","71":"9.5.2|12.11.2"}},{"v":["Боже, прийшли язичники в насліддя Твоє, осквернили святий храм Твій, Єрусалим обернули на руїну.","Кинули трупи рабів Твоїх на поживу птахам небесним, тіла святих Твоїх — звірам земним.","Розлили кров їх, як воду, навкруги Єрусалима, і не було кому поховати їх.","Ми стали посміховиськом для сусідів наших, наругою й соромом для тих, що оточують нас.","Доки, Господи, будеш безупинно гніватися на нас, доки буде палати, як вогонь, обурення Твоє?","Вилий гнів Твій на народи, які не знають Тебе, і на царства, які імені Твого не призивають.","Бо вони поглинули народ Твій і місце його спустошили.","Не згадуй давніх гріхів батьків наших, але скоро пошли нам милість Твою, бо дуже зубожіли ми.","Поможи нам, Боже, Спасителю наш, задля слави імені Твого. Визволи нас, Господи, і очисти гріхи наші ради імені Твого.","Щоб не сказали язичники: «Де Бог їх?» Нехай на очах наших пізнають вони помсту за пролиту кров рабів Твоїх.","Нехай прийде перед лице Твоє стогін ув’язнених; могутністю Твоєю збережи засуджених на смерть.","Семикратно поверни в серце ворогам нашим наругу їх, якою вони зневажили Тебе, Господи.","А ми, народ Твій і вівці стада Твого, будемо вічно прославляти Тебе і з роду в рід сповіщати хвалу Твою."],"h":"Псалом Асафа.","x":{"1":"32.12.8","2":"21.7.17","3":"36.24.7","4":"25.43.14","5":"25.88.47","6":"32.10.25","8":"31.64.9","10":"25.41.4|39.2.17","11":"10.8.49","12":"31.65.6","13":"25.99.3"}},{"v":["Начальнику хору. На музичному інструменті шошанним-едуф. Псалом Асафа.","Пастирю Ізраїля, поглянь! Ти, Який водив Йосифа, наче ягня, і сидиш на херувимах, явися.","Перед Єфремом, Веніаміном, Манассією, Господи, піднеси силу Твою і прийди, спаси нас.","Боже, наверни нас, осяй нас світлом лиця Твого, і ми спасемося.","Господи, Боже Сил! Доки будеш гніватися на молитву рабів Твоїх?","Ти наситив нас хлібом слізним і напоїв нас сльозами великою мірою.","Ти поклав нас на осудження сусідам нашим, і вороги наші знущаються з нас.","Господи Боже Сил! Наверни нас, осяй нас світлом лиця Твого, і ми спасемося.","З Єгипту приніс Ти, Господи, виноградну лозу, прогнав народи і насадив її.","Ти очистив місце для неї, зміцнив коріння її і вона заповнила землю.","Гори покрилися тінню її, і віття її стало як у кедрів Божих.","Вона простягла паростки свої аж до моря, і віття свої — до ріки (Євфрату).","Навіщо зруйнував Ти огорожу навкруги виноградника цього? Обриває його кожний, хто йде дорогою.","Підриває коріння його вепр лісовий, і дикий звір пожирає його.","Боже Сил, обернися! Споглянь з небес, Боже, і подивись! Завітай у виноградник цей.","І охорони його, бо його насадила правиця Твоя і сина людського, якого Ти виростив для Себе.","Спалено його вогнем і порубано його; від грізного погляду лиця Твого загинуть.","Але нехай буде рука Твоя над мужем правиці Твоєї, і над сином людським, якого Ти укріпив для Себе.","А ми не відступимо від Тебе. Оживи нас, і ми будемо призивати ім’я Твоє.","Господи Боже Сил! Наверни нас, осяй нас світлом лиця Твого, і ми спасемося."],"x":{"2":"25.76.21","3":"31.7.2","4":"25.30.17","6":"10.22.27|25.101.10","7":"25.43.14","9":"25.43.3","12":"1.23.31","13":"31.5.5","14":"11.17.6|25.67.31"}},{"v":["Начальнику хору. На гефському інструменті. Псалом Асафа.","Радісно співайте Богу — твердині нашій, викликуйте славу Богові Якова.","Візьміть псалом, дайте тимпан, псалтир милозвучний з гуслями.","Засурміть у новомісяччя сурмою у пресвітлий день свята вашого.","Бо це закон для Ізраїля, повеління Бога нашого.","Він установив це як свідчення для Йосифа, коли він вийшов із землі Єгипетської, де почув мову, якої не знав.","«Я зняв тягарі з плечей його і руки його звільнив від корзин.","В біді ти прикликав Мене, і Я визволив тебе; серед грому Я почув тебе, при водах Мериви випробував тебе.","Слухай, народе Мій, і Я дам свідчення тобі; о, коли б ти послухав Мене, Ізраїлю!","Нехай не буде в тебе іншого бога, і не вклоняйся перед богом чужим.","Я — Господь Бог твій, що вивів тебе із землі Єгипетської. Розкрий уста твої, і Я наповню їх.","Але не послухав народ Мій голосу Мого, Ізраїль не підкорився Мені.","Тому Я покинув їх на волю серця їх — ходити за похотями своїми.","О, коли б народ Мій послухав Мене, коли б Ізраїль ходив дорогами Моїми.","Я скоро смирив би ворогів їхніх і на гнобителів їхніх поклав би руку Мою.","Ненависники Господні підкорилися б їм, а добробут їх був би повіки.","Я хлібом пшеничним годував би їх, і медом із скелі насичував би їх»."],"x":{"1":"25.8.1|25.83.1","4":"3.10.10","5":"1.23.17","8":"1.17.6","9":"1.20.1-2|25.49.7","13":"54.14.16","14":"2.26.3","17":"4.32.13"}},{"v":["Бог став у сонмі богів, посеред них, щоб богів судити.","«Доки будете судити неправедно і догоджати грішникам?","Судіть сироту і вбогого по правді, смиренного і бідного виправдайте.","Визволіть бідного й убогого, від руки грішника звільніть його.","Не пізнали і не зрозуміли, бо в темряві ходять. Нехай захитаються всі основи землі.","Я сказав: ви — боги і сини Всевишнього всі,","але вмираєте, як люди, і, як кожен князь, падаєте».","Воскресни, Боже, суди землю, бо Ти успадкував усі народи."],"h":"Псалом Асафа.","x":{"2":"4.1.17|13.19.6","4":"26.24.11|31.1.17","5":"58.1.6","6":"53.10.34","7":"36.31.14","8":"25.2.8|75.1.2"}},{"v":["Пісня. Псалом Асафа.","Боже, хто подібний до Тебе? Не мовчи і не будь спокійним, Боже.","Бо ось вороги Твої зашуміли і ті, що ненавидять Тебе, підняли голови.","Вони підступно змовляються проти народу Твого і радяться проти святих Твоїх.","Сказали: «Підемо й винищимо їх з-поміж народів, щоб ніхто не згадував більше імені Ізраїля».","Змовилися і однодушно уклали союз проти Тебе.","Сини Едома, ізмаїліти, Моав і агаряни,","Гевал і Аммон, Амалик і филистимляни з людьми тирськими.","І Ассур пішов з ними; вони стали на поміч синам Лотовим.","Зроби з ними так, як з Мадіамом, Сисарою та Іавимом біля потоку Кисана,","які були знищені в Аендорі і стали гноєм для землі.","Зроби з ними та князями їхніми, як з Оривом, Зивом, Зевеєм і Салманом — вельможами їхніми,","які говорили: «Візьмемо собі у володіння святиню Божу».","Боже мій! Нехай стануть вони як порох у вихорі, як солома перед вітром,","як вогонь спалює ліси, як полум’я, що обпалює гори,","так пожени їх бурею Твоєю і гнівом Твоїм приведи їх у замішання.","Покрий їх безчестям, щоб вони шукали імені Твого, Господи.","Нехай будуть осоромлені й застрашені навіки, і з соромом своїм загинуть.","І нехай узнають, що ім’я Тобі — Господь і що Ти єдиний Всевишній на всій землі."],"x":{"2":"25.108.1","4":"50.26.4","5":"32.11.19|54.14.5","8":"31.27.9","9":"0.19.37","10":"6.4.15","12":"6.7.25|6.8.12:21","14":"31.17.13|25.1.4","17":"25.69.3","19":"1.14.4|1.15.3"}},{"v":["Начальнику хору. На гефському інструменті. Псалом синів Кореєвих.","Які любі оселі Твої, Господи Сил!","Жадає і лине душа моя до двору Господнього; серце моє й тіло моє возрадувалися Богу живому.","Бо й пташка знаходить собі домівку, і ластівка гніздо собі, щоб вивести пташенят своїх, біля вівтарів Твоїх, Господи Сил, Царю мій і Боже мій.","Блаженні ті, що живуть у домі Твоїм, повіки вони будуть хвалити Тебе.","Блаженний муж, який має заступництво своє у Тобі і в якого у серці дорога до Тебе.","Ідучи долиною плачу, вони знаходять джерела води, Законодавець покриває їх благословенням.","Вони перейдуть від сили в силу і являться перед Богом на Сионі.","Господи, Боже Сил, почуй молитву мою! Зглянься, Боже Яковів.","Захиснику наш, Боже! Прихилися і поглянь на лице Христа Твого.","Бо один день у дворах Твоїх краще за тисячі днів. Бажаю краще стояти біля порога в домі Бога мого, аніж перебувати мені в палацах грішників.","Бо Бог є сонце й захист. Милість і правду любить Господь Бог і подає славу й благодать. Господь не позбавить блага тих, що ходять у чистоті.","Господи, Боже Сил! Блаженна людина, яка уповає на Тебе."],"x":{"1":"25.80.1","3":"25.41.3","8":"31.40.29|62.1.17","11":"8.26.19|9.6.22","12":"52.22.35","13":"25.2.12|26.3.5"}},{"v":["Начальнику хору. Псалом синів Кореєвих.","Господи, Ти змилувався над землею Твоєю, повернув з неволі синів Якова.","Ти простив беззаконня народу Твого, покрив усі гріхи їх.","Ти спинив увесь гнів Твій і відвернувся від гніву ярости Твоєї.","Поверни нас, Боже, Спасителю наш, і спини гнів Твій проти нас.","Чи ж довіку будеш гніватися на нас? Невже ж продовжиш гнів Твій від роду до роду?","Боже, повернися і оживи нас, щоб зрадувався Тобою народ Твій.","Яви нам, Господи, милість Твою і Твоє спасіння дай нам!","Почую, що скаже про мене Господь Бог. Він скаже мир народові Своєму і преподобним Своїм, тим, що звертають серця свої до Нього.","Так близько спасіння Його до тих, що бояться Його, щоб слава Його перебувала на землі нашій.","Милість і істина зустрілися, правда і мир поцілувалися.","Істина від землі засяяла, а правда з неба прихилилася.","Бо Господь пошле нам добро, і земля наша дасть плід свій.","Правда піде перед Ним і направить на путь стопи наші."],"x":{"3":"25.31.1|62.4.7","6":"25.12.2|25.76.8|25.78.5","10":"25.96.6|25.144.18","13":"39.2.19:22"}},{"v":["Прихили, Господи, вухо Твоє і почуй мене, бо я немічний і вбогий.","Охорони душу мою, бо я відданий Тобі. Боже мій, спаси раба Твого, що уповає на Тебе.","Помилуй мене, Господи, бо я взиваю до Тебе кожного дня.","Звесели душу раба Твого, бо до Тебе я підношу душу мою.","Бо Ти, Господи, благий і лагідний і многомилостивий до тих, що призивають Тебе.","Почуй, Господи, молитву мою і вислухай голос благання мого.","В день скорботи моєї я взиваю до Тебе, бо Ти почуєш мене, Боже.","Немає між богами такого, як Ти, Господи, і ніщо не може зрівнятися з ділами Твоїми.","Всі народи, що їх створив Ти, прийдуть і поклоняться Тобі, Господи, і прославлять ім’я Твоє.","Бо Ти великий і твориш чудеса. Ти — Бог єдиний.","Настав мене, Господи, на путь Твою, і буду ходити в істині Твоїй. Утверди серце моє в страху перед іменем Твоїм.","Буду вихваляти Тебе, Господи, Боже мій, всім серцем моїм і прославлятиму ім’я Твоє повіки.","Бо велика милість Твоя наді мною: Ти визволив душу мою з пекла найглибшого.","Боже! Беззаконники повстали проти мене, і натовп сильних шукає душі моєї, і не мають Тебе перед собою.","Ти ж, Господи, щедрий і милостивий, довготерпеливий і многомилостивий і істинний.","Зглянься на мене і помилуй мене; дай силу рабу Твоєму, спаси сина раби Твоєї.","Покажи на мені ознаку милости Твоєї, щоб побачили ненависники мої і посоромилися, бо Ти, Господи, допоміг мені і втішив мене."],"h":"Молитва Давида.","x":{"1":"25.87.3","5":"1.34.6|39.2.13|42.4.2","7":"25.49.15","8":"4.3.24","9":"32.3.17|76.15.5","10":"9.7.22|31.45.5","11":"25.24.4|25.26.11","13":"25.29.4","14":"25.53.5","15":"25.85.5|31.54.8"}},{"v":["Псалом синів Кореєвих. Пісня (про Єрусалим, що є прообраз Єрусалима небесного).","Основи його на горах святих, любить Господь врата Сиону більше за поселення Якова.","Преславне говорять про тебе, місто Боже.","Згадаю Єгипет і Вавилон перед тими, що знають мене. Ось филистимляни і Тир з людьми ефіопськими скажуть: це все сталося там.","І про Сион скажуть: і цей, і той чоловік народився в ньому, і Сам Всевишній заснував його.","Господь напише в переписі народів: ось такий народився там.","Бо в Тобі оселя всіх, що співають і веселяться."],"x":{"3":"31.62.3","5":"65.4.26"}},{"v":["Начальнику хору на махалаф, для співу. Повчання Емана Езрахіта. Псалом синів Кореєвих. (Пісня-молитва.)","Господи, Боже спасіння мого, вдень я взиваю і вночі перед Тобою.","Нехай дійде до Тебе молитва моя, прихили вухо Твоє до моління мого.","Бо стражданнями сповнилася душа моя, і життя моє до пекла наблизилося.","Приєднався я до тих, що сходять у могилу: я став як людина без сили,","між мертвими кинутий я, — як убиті, що сплять у гробі, про яких Ти вже не згадуєш і які від руки Твоєї відринуті.","Ти поклав мене у рові преісподнім, у темряві і тіні смертній.","На мені утвердилася ярість Твоя, і всі хвилі Твої навів Ти [на мене].","Віддалив Ти знайомих моїх від мене, зробив мене огидним для них. Я в неволі й не можу вийти.","Очі мої знемоглися від горя. Взивав до Тебе, Господи, весь день, підносив до Тебе руки мої.","Хіба для мертвих Ти твориш чудеса? А чи мертві воскреснуть і прославлятимуть Тебе?","Хіба розповість хто у гробі про милість Твою і про істину Твою — в погибелі?","Чи пізнані будуть у темряві чудеса Твої і правда Твоя — в землі забуття?","Я ж до Тебе, Господи, взиваю, і вранці молитва моя упередить Тебе.","Чому, Господи, відкидаєш душу мою, відвертаєш лице Твоє від мене?","Убогий я, і страждаю від юности моєї, смирився і знеміг.","По мені пройшов гнів Твій, і страхання Твої сокрушили мене.","Оточили мене, як вода, весь день, облягли мене всі вкупі.","Віддалив Ти від мене друга й ближнього, знайомих моїх — від моїх пристрастей."],"x":{"1":"12.25.5","5":"25.27.1|33.3.6","6":"24.10.21","9":"24.30.10|25.30.12|25.37.12","11":"25.6.6","13":"24.10.21-22","16":"24.19.7","18":"25.21.13"}},{"v":["Повчання Ефама Езрахіта.","Милості [Твої], Господи, повіки співатиму, з роду в рід сповіщатиму істину Твою устами моїми.","Бо Ти сказав: навіки милість перебуватиме, на небесах приготується істина Твоя.","«Я заповів завіт обраним Моїм, клявся Давидові, рабу Моєму:","навіки утверджу нащадків твоїх і збудую з роду в рід престіл твій».","Прославлятимуть небеса дивні діла Твої, Господи, і правду Твою в Церкві святих.","Бо хто на небесах зрівняється з Господом? І хто подібний до Нього між синами Божими?","Бог, що Його прославляють собори святих, великий і страшний для всіх, хто навкруги Нього.","Господи, Боже Сил! Хто подібний до Тебе?! Всесильний Ти, Господи, і правда Твоя навкруги Тебе.","Ти володарюєш над силою моря і втихомирюєш розбурхані хвилі його.","Ти смирив гордого, немов пораненого, і кріпкістю сили Твоєї Ти розсипав ворогів Твоїх.","Твої небеса і Твоя земля. Ти створив всесвіт і все, що наповнює його.","Північ і південь Ти створив єси. Фавор і Єрмон іменем Твоїм радуються.","Сильні рамена Твої, міцна рука Твоя, високо піднесена правиця Твоя.","Правосуддя і справедливість — основа Престолу Твого. Милість і істина йдуть перед лицем Твоїм.","Блаженні люди, що знають глас святковий: Господи, у світлі лиця Твого вони ходять,","і іменем Твоїм вони радуються весь день, і правдою Твоєю підносяться.","Бо Ти похвала сили їхньої, і милістю Твоєю підноситься ріг наш.","Бо Господь — Захист наш і Святий Ізраїлів — Цар наш.","Колись говорив Ти у видінні святому Твоєму і сказав: «Я подав поміч мужньому, підніс обраного з людей Моїх.","Я знайшов Давида, слугу Мого, і миром святим Моїм помазав його.","Рука Моя захистить його і сила Моя підкріпить його.","Не подолає ворог його, і син беззаконня не візьме в неволю його.","Розіб’ю перед ним ворогів його, і знищу ненависників його.","Істина Моя і милість Моя з ним, і ім’ям Моїм піднесеться сила його.","І покладу на море руку його і на ріки — правицю його.","І буде він звати Мене: «Ти Отець мій і Бог мій, твердиня спасіння мого.»","І Я первенця піднесу Мого* високо, вище царів землі.","Навіки збережу йому милість Мою, і завіт Мій вірний йому.","І продовжу навіки рід його, і престіл його — як дні неба.","А якщо сини його покинуть закон Мій і не будуть ходити за заповідями Моїми,","якщо зневажать устави Мої і повелінь моїх не збережуть,","то Я з жезлом прийду на беззаконня їх і з тяжкою карою — на неправду їх.","Милості ж Моєї не відійму від нього й не переміню правди Моєї,","не зламаю завіту Мого і не зміню того, що вийшло з уст Моїх.","Один раз клявся Я святістю Моєю і не скажу неправду Давиду.","Насіння його перебуватиме повіки, і престіл його — як сонце переді Мною,","як місяць, так буде він стояти вічно. Свідок на небесах певний».","А ось тепер Ти відкинув, занедбав і прогнівався на помазаника Твого.","Зневажив завіт Твій з рабом Твоїм і скинув на землю вінець його.","Ти зруйнував навкруги мури його і твердині його обернув на руїну.","Грабують його всі, хто проходить шляхом, став він посміховиськом у сусідів своїх.","Ти підніс правицю супротивників його, порадував усіх ворогів його.","Ти обернув назад вістря меча його і не підкріпив його в бою.","Відібрав славу його і престіл його повалив на землю.","Ти вкоротив дні влади його і вкрив його соромом.","Доки ж, Господи, будеш відвертати від нас лице Твоє, доки буде палати над нами гнів Твій?","Спом’яни, який вік мій. Хіба не на марне Ти створив усіх синів людських?","Хто з людей пожив і не зазнав смерти? Хто визволив душу свою від руки пекла?","Де давні милості Твої, Господи, що ними клявся Ти Давидові в істині Твоїй?","Згадай, Господи, наругу над слугами Твоїми, яку я ношу в серці своїм від сильніших народів.","Від ворогів Твоїх, Господи, що знеславлюють ім’я помазаника Твого.","Благословен Господь навіки. Амінь, амінь."],"x":{"1":"12.15.17","2":"25.91.3","4":"9.7.12|25.131.11","7":"25.85.8","9":"25.76.14|76.19.15","10":"25.106.29|50.8.26","12":"0.1.1","15":"25.92.2","18":"52.1.69","19":"25.3.4|25.83.10","21":"8.16.13|54.13.22","22":"31.41.10","23":"9.7.10","26":"25.71.8|76.10.2","27":"9.7.14|75.1.5","28":"68.1.18|76.19.16","30":"25.71.5|9.7.13|37.2.44","33":"9.7.14","35":"9.7.16","37":"9.7.16|25.71.17|52.1.33|53.12.34","38":"76.1.5","40":"25.43.10","41":"33.2.6","42":"25.30.12|25.43.14","47":"25.12.2","49":"25.48.10|30.14.18","50":"9.7.15"}},{"v":["Молитва Мойсея, чоловіка Божого.","Господи! Пристановищем нашим був Ти з роду в рід.","Перше, ніж з’явилися гори і створилися Земля і Вселенна, — од віку й до віку Ти єси.","Ти повертаєш людину у тління і кажеш: «Верніться, сини людські!»","Бо тисяча літ перед очима Твоїми — як день учорашній, що пройшов, як сторожа нічна.","Ти, наче повінню, зносиш їх. Вони як сон, як трава, що зранку зеленіє й цвіте, а ввечері опадає, в’яне й сохне.","Бо ми в страху від гніву Твого, і від ярости Твоєї ми в тривозі.","Ти поклав перед Собою беззаконня наші і таємне наше перед світлом лиця Твого.","Всі дні наші минають у гніві Твоїм, і роки наші щезають, як мрії.","Дні віку нашого — сімдесят літ, а як при силі — вісімдесят літ, і найкраща пора їх — труд і хвороби: час швидко минає, і ми зникаємо.","Хто знає силу гніву Твого, щоб страхом перед Тобою виміряти ярість Твою?","Навчи нас так обчисляти дні наші, щоб ми придбали серце мудре.","Повернися, Господи, доки ж? Змилосердься над слугами Твоїми.","Наповни нас вранці милістю Твоєю, Господи, і зрадіємо та звеселимось.","Звесели нас у всі дні наші — за ті дні, коли Ти смиряв нас, за літа, коли ми бачили зло.","І подивись на рабів Твоїх і на діла Твої і навчи синів їх.","І нехай буде милість Господа Бога нашого на нас. Діла рук наших виправ і в ділах рук наших допомагай нам."],"x":{"3":"31.43.13","5":"57.3.8","6":"31.40.6|31.51.12|30.14.18","7":"31.40.7|25.75.8","10":"30.18.8","11":"30.16.19","12":"25.38.5","14":"31.33.2|25.137.8","17":"24.14.15"}},{"v":["Хто живе під охороною Всевишнього, той під покровом Бога Небесного оселиться.","Каже він до Господа: «Ти пристановище і захист мій, Бог мій, і я уповаю на Тебе».","Він спасе тебе від сіті ловця і від пошести згубної.","Плечима Своїми Він захистить тебе, і під тінню крил Його ти надійно спочиватимеш. Обороною тобі буде правда Його.","Не побоїшся страху вночі, ані стріли, що летить удень.","Ані пошести, що ходить у темряві, ані напасти духа зла опівдні.","Впаде біля тебе тисяча, і десять тисяч праворуч тебе, але до тебе не наблизиться.","Тільки очима твоїми будеш дивитися і помсту над беззаконними бачити.","Бо ти сказав: «Господь — надія моя», і Всевишнього ти обрав за оборонця собі.","Отже, не прийде до тебе лихо, і пошесть не наблизиться до оселі твоєї.","Бо Він ангелам Своїм звелить, щоб охороняли тебе на всіх путях твоїх.","На руках вони понесуть тебе, щоб нога твоя не спіткнулася об камінь.","На гаспида й василиска ти наступатимеш і потопчеш лева й змія.","Бо каже Господь: «За те, що він поклав надію на Мене, Я визволю його і захищу його, бо він знає ім’я Моє.","Буде кликати Мене, Я почую його; буду з ним у скорботі, визволю його і прославлю його.","Довгим життям обдарую його і дам йому спасіння Моє»."],"h":"[Хвалебна пісня Давида] (у євреїв не надписаний).","x":{"1":"25.16.8|25.35.8|38.14.8","2":"25.141.6","4":"50.23.37","5":"9.22.31|25.83.12","7":"24.11.19","8":"25.91.12|25.111.8","11":"50.4.6|52.4.10","12":"24.5.23","13":"52.10.19","14":"25.144.19|37.6.23","15":"24.22.27|24.33.24|48.13.9","16":"31.43.2"}},{"v":["Пісня в день суботній.","Благо є сповідуватися Господу і співати імені Твоєму, Вишній.","Сповіщати зранку милість Твою і істину Твою на всяку ніч,","на десятиструннім псалтирі, з піснею на гуслях.","Бо Ти звеселив мене, Господи, і я радію від діл рук Твоїх.","Які величні діла Твої, Господи, і які дивні помисли Твої.","Безумний не збагне їх і нерозумний не зрозуміє.","Ось грішники зійшли, як трава, і беззаконники цвітуть, щоб щезнути навіки, —","Ти ж Всевишній навіки, Господи!","Ось бо вороги Твої, Господи, ось вороги Твої загинуть, і розсіються всі ті, що чинять беззаконня;","і піднесеться, як у єдинорога ріг, сила моя; і старість моя — в чистому єлеї;","і погляне око моє на ворогів моїх, і про лукавих, що повстають проти мене, почує вухо моє.","Праведник, як фінік, розцвіте, і як кедр, що в Ливані, примножиться.","Насаджені в домі Господнім у дворах Бога нашого розцвітуть.","Вони і в старості будуть множитися, і в доброму здоров’ї перебуватимуть,","щоб сповіщати, що праведний Господь — Бог наш, і нема неправди в Ньому."],"x":{"2":"25.146.1","3":"25.88.2","6":"25.103.24|36.47.5|62.11.33","7":"31.26.10","8":"25.36.2|25.128.6","9":"24.36.26|25.101.28","11":"3.23.22","13":"25.51.10","15":"52.2.36"}},{"v":["Господь воцарився, у красу зодягнувся. Зодягнувся Господь у силу [і] опоясався. Бо Він утвердив вселенну, і не захитається вона.","Престіл Твій, Господи, од вічності, споконвіку Ти єси Бог.","Ріки підносять голос, Господи, ріки підносять голос свій, ріки піднесли хвилі свої.","Але Господь у вишніх могутніший від шуму великих вод, від сильних хвиль моря.","Одкровення Твої вельми правдиві. Дому Твоєму належить святість, Господи, на довгі дні."],"h":"[Хвалебна пісня Давида. В день передсуботній, коли була населена земля.]","x":{"1":"25.95.10","4":"25.2.4-5|25.109.5","5":"25.118.86"}},{"v":["Боже помсти, Господи Боже помсти, яви Себе!","Встань, Судде землі, дай відплату гордим.","Доки, Господи, доки нечестивці будуть вихвалятися?","Вони говорять неправдиві слова, величають себе всі, що чинять беззаконня.","Народ Твій, Господи, поневолили і гноблять насліддя Твоє.","Вдовиць і сиріт уморюють і пришельців убивають.","І кажуть: «Не побачить Господь, не дізнається Бог Якова».","Зрозумійте ж, нерозумні люди! Коли ви прийдете до розуму?","Той, Хто створив вухо, чи не почує? І той, Хто створив око, чи не побачить?","Той, що врозумляє народи і дає людям розуміння, невже не покарає вас?","Знає Господь замисли людські, що вони марні.","Блаженна та людина, яку врозумляєш Ти, Господи, і навчаєш закону Твого,","щоб у тяжкі дні вона мала спокій, доки нечестивому викопають яму.","Бо не відкине Господь народу Свого і не забуде насліддя Свого.","Бо в суд прийде правда, і за нею прийдуть усі праведні серцем.","Хто стане за мене проти злочинців? І хто стане за мене проти тих, що чинять беззаконня?","Якби б Господь не поміг мені, то скоро зійшла б до пекла душа моя.","Коли я сказав: «Похитнулися ноги мої», тоді милість Твоя, Господи, підтримувала мене.","Коли ж намножувалися скорботи в серці моїм, Твоя втіха насолодою наповнювала душу мою.","Чи допустиш Ти, щоб поблизу Тебе постала оселя розбійників, що чинять насильство наперекір закону?","Вони натовпом нападають на душу праведника і кров неповинну судять.","Але Господь — захист мій, і Бог мій — твердиня надії моєї.","Він поверне на них беззаконня їхні і злочинством їхнім погубить їх, знищить їх Господь Бог наш."],"h":"[Псалом Давида в четвертий день тижня.]","x":{"1":"4.32.35|62.12.19","4":"25.51.3","5":"25.15.5","6":"36.22.7","7":"24.22.13|24.24.15","9":"26.20.12|49.3.16","11":"63.3.20","12":"24.5.17|26.3.12","14":"10.8.57","21":"25.2.2|37.6.4"}},{"v":["Прийдіть, у радості заспіваємо Господу, виголосимо славу Спасителю нашому.","Станьмо перед лицем Його з хвалою, піснями прославимо Його.","Бо Господь — Бог великий і Цар великий над усіма сильними землі.","Бо в руці Його всі глибини землі, і висоти гір всі Його.","І море — Його, бо Він створив його, і сушу створили руки Його.","Прийдіть, поклонімось і припадімо до Нього, та, схиливши коліна, помолимось перед Господом, Який створив нас.","Бо Він — Бог наш, а ми, люди, — паства Його і вівці руки Його. О, коли б ви нині послухали голосу Його:","«Не робіть жорстокими сердець ваших, як у Мереві, як у день випробовування в пустелі,","де спокушали Мене батьки ваші, випробовували Мене, хоч бачили діла Мої.","Сорок років гнівив Мене рід цей, і Я сказав: народ цей заблукав серцем; вони не пізнали шляхів Моїх.","Тому Я поклявся в гніві Моїм, що вони не ввійдуть у спокій Мій»."],"h":"[Хвалебна пісня Давида.]","x":{"1":"4.32.3","3":"12.16.25","4":"25.49.10","6":"25.17.7|25.131.7","7":"75.3.7|75.4.7","9":"1.17.2:7","10":"3.14.34","11":"75.4.3"}},{"v":["Заспівайте Господу пісню нову. Заспівайте Господу, вся земле.","Співайте Господу і благословляйте ім’я Його. Благовістіть день у день про спасіння Його.","Сповіщайте в народах про славу Його, між усіма поколіннями про чудеса Його.","Бо великий Господь і вельми хвальний, страшний для всіх богів.","Бо ті боги народів ніщо — ідоли, а Господь небеса сотворив.","Слава і велич перед лицем Його, сила й краса у святині Його.","Воздайте, покоління народів, воздайте Господу славу і честь.","Воздайте Господу славу імені Його. Принесіть дари і ввійдіть у двори Його.","Поклоніться Господу у величній святині Його. Нехай тремтить перед лицем Його вся земля.","Сповіщайте народам, що Господь царює, що Він утвердив вселенну і не захитається вона. Він буде судити народи за правдою.","Нехай веселяться небеса і нехай радіє вся земля; хай шумить море і все, що наповнює його.","Нехай радіють поля і все, що на них, і нехай веселяться всі дерева в лісах перед лицем Господа.","Бо ось Він гряде, Він гряде судити землю. Він буде судити вселенну за правдою і всі народи за істиною Своєю."],"h":"[Хвалебна пісня Давида. На спорудження дому.]","x":{"1":"12.16.23","4":"30.43.31","5":"31.41.24","6":"12.16.27","7":"12.16.29|25.28.1","10":"48.9.10","11":"12.16.31|31.49.13|76.12.12","13":"25.9.9|54.17.31|31.3.14"}},{"v":["Господь царює — нехай радіє земля, нехай веселяться численні острови її.","Хмара і морок навкруги Нього, суд і правда — підвалини Престолу Його.","Вогонь іде перед Ним і навколо спалює ворогів Його.","Блискавки Його осявають всесвіт, земля бачить це і трясеться.","Гори, наче віск, тануть від лиця Господа, від лиця Господа всієї землі.","Небеса сповіщають правду Його, і всі народи бачать славу Його.","Нехай посоромляться всі, що вклоняються перед ідолами та ще й хваляться ними. Поклоніться Йому, всі ангели Його.","Чує Сион і радіє, і веселяться дочки юдейські через суди Твої, Господи.","Бо Ти, Господи, високий над усією землею, Ти високо піднісся над усіма богами.","Ви, що любите Господа, ненавидьте зло, Він охороняє душі святих Своїх, із рук баззаконників визволяє їх.","Світло сяє на праведника, і на правих серцем — радість.","Веселіться, праведні, у Господі, і прославляйте пам’ять святині Його."],"h":"[Псалом Давида, коли упорядковувалася земля його.]","x":{"1":"25.92.1|25.98.1|48.9.10","2":"76.10.1|25.88.15","4":"76.4.5|25.76.17","6":"25.18.2","7":"1.20.4|2.26.1|4.5.8","9":"25.134.5","10":"40.5.15|62.12.9","11":"9.22.29|24.18.5|25.111.4","12":"25.31.11"}},{"v":["Заспівайте Господу пісню нову, бо дивне сотворив Господь. Правиця Його і сила Його дали Йому перемогу.","Явив Господь спасіння Своє, перед народами відкрив правду Свою.","Згадав Він милість Свою [до Якова] і вірність Свою до дому Ізраїлевого. Побачили всі кінці землі спасіння Бога нашого.","Викликніть Господу, вся земля; радійте, веселіться й співайте!","Співайте Господу з гуслями, з гуслями і з голосом псалмоспівів.","Звуками труб і голосом рога радісно святкуйте перед Царем Господом.","Нехай співає море і все, що живе в ньому; вселенна і все, що наповнює її.","Нехай плещуть хвилями ріки і нехай радіють гори","перед лицем Господа, бо ось Він гряде судити землю; Він буде судити вселенну за справедливістю і народи — за правдою."],"h":"Псалом [Давида].","x":{"1":"31.63.5","2":"31.52.10","3":"52.2.30|52.3.6","4":"25.65.2","5":"25.149.3","8":"12.16.32","9":"25.95.13"}},{"v":["Господь воцарився — нехай бояться народи! Возсів на херувимах, — нехай захитається земля.","Господь в Сионі великий і високий над усіма людьми.","Нехай прославляють велике і страшне ім’я Твоє, бо воно святе.","І честь Царева любить правосуддя: Ти утвердив правду, суд і правоту встановив Ти у синів Якова.","Возносьте Господа Бога нашого і поклоняйтеся підніжжю ніг Його, бо воно святе.","Мойсей і Аарон між ієреями Його, і Самуїл між тими, що призивають ім’я Його. Взивали вони до Господа, і Він вислухав їх.","У стовпі хмарному Він говорив до них, і вони виконували, зберігали заповіді Його і повеління Його, що Він дав їм.","Господи, Боже наш! Ти вислухав благання їхні; Боже, Ти був милостивим до них, але й карав за провини їхні.","Возносьте Господа Бога нашого і поклоняйтеся на горі святій Його, бо Святий Господь, Бог наш."],"h":"[Псалом Давида.]","x":{"1":"25.92.1|8.4.4|9.6.2","3":"25.94.3|25.110.9","4":"25.102.6","5":"31.6.3|76.4.8","6":"1.32.11|3.14.13|8.12.19","7":"1.33.9","9":"56.1.16"}},{"v":["Викликніть Господу, вся земля!","Служіть Господу з радістю. Ідіть перед лице Його з піснями хвали.","Знайте, що Він — Господь Бог наш, Він створив нас. Ми — народ Його і вівці пастви Його.","Входьте у ворота Його з хвалою, у двори Його — з піснями хвальними. Хваліть Його і прославляйте ім’я Його.","Бо Господь милосердний, милість Його вічна й істина Його з роду в рід."],"h":"Псалом [Давида] хвалебний.","x":{"1":"25.97.4|54.10.46","3":"8.12.22|25.73.1|25.78.13","5":"25.72.1"}},{"v":["Про милість і правосуддя буду співати Тобі, Господи.","Буду розмірковувати про путі непорочні; коли Ти, Господи, прийдеш до мене? Буду ходити в домі моїм у чистоті серця мого.","Не покладу перед очима моїми діла протизаконного; тих, що чинять беззаконня, я ненавиджу.","Серце нечестивого не пристане до мене. Злого я не хочу знати.","Того, що потай очорнює ближнього свого, я прожену. З гордим оком і неситим серцем не сяду за стіл.","Очі мої на вірних землі, щоб перебували вони біля мене. І хто ходить шляхом непорочности, той буде служити мені.","Не буде жити в моїм домі той, хто діє підступно. Не залишиться перед очима моїми той, хто говорить неправду.","Щоранку буду нищити всіх грішників землі, щоб викоренити з міста Господнього всіх, що чинять беззаконня."],"h":"Псалом Давида.","x":{"1":"25.88.2","2":"8.18.14|12.18.14","3":"25.138.21","4":"25.6.9","6":"51.3.35"}},{"v":["Молитва скорботного, коли він у печалі виливає перед Богом благання своє.","Господи! Вислухай молитву мою, і плач мій до Тебе нехай дійде.","Не відвертай лиця Твого від мене в день, коли я в скорботі. Прихили до мене вухо Твоє в той день, [коли] призву [Тебе]; скоро вислухай мене.","Бо щезають, наче дим, дні мої, і кості мої висохли.","Я підкошений, наче трава, і висохло серце моє, бо я вже забув їсти хліб мій.","Від тяжкого зітхання мого присохли кості мої до плоті моєї.","Я став подібний до нічного птаха в пустелі, став як сова на руїнах.","Не сплю і став наче самотній птах на покрівлі.","Кожного дня зневажають мене вороги мої, і ті, що хвалили мене, проклинають мене.","Я вже попіл їм, наче хліб, і пиття моє змішую зі сльозами.","Від лиця гніву Твого і ярости Твоєї — Ти підніс і кинув мене.","Дні мої, наче тінь, зникають, і я висох, як та трава.","Ти ж, Господи, перебуваєш вічно, і пам’ять про Тебе з роду в рід.","Ти встанеш і змилосердишся над Сионом, бо вже час помилувати його, бо вже прийшов призначений час.","Бо раби Твої полюбили й каміння його, і жаль їм руїн його.","І будуть народи боятись імені Твого, і всі царі землі — слави Твоєї.","Бо відбудує Господь Сион і явиться у славі Своїй.","Він зглянеться на молитви смиренних і не відкине благання їх.","І буде написано про це для поколінь майбутніх, і люди, що народяться, будуть хвалити Господа.","Бо Він прихилився з висоти святої Своєї, поглянув Господь з небес на землю,","щоб почути стогін ув’язнених, звільнити синів, на смерть засуджених,","щоб прославляли ім’я Господнє в Сионі і хвалили Його в Єрусалимі,","коли разом зберуться народи й царства, щоб служити Господу.","Ти виснажив у дорозі сили мої, вкоротив дні віку мого.","І я сказав: «Боже мій! Не знищуй мене на половині життя мого, Твої літа в роді родів вічно.","На початку Ти, [Господи,] землю створив, і небеса — діло рук Твоїх.","Вони загинуть, Ти ж існуватимеш; вони, наче риза, постаріють; як одежу, переміниш їх, і вони зміняться.","Ти ж усе Той Самий, і літа Твої не скінчаться.","Сини рабів Твоїх будуть жити, і насліддя їх утвердиться перед лицем Твоїм повік»."],"x":{"2":"25.142.1","3":"25.12.2|25.43.25","4":"26.17.22","5":"25.108.22","7":"4.14.17","10":"24.3.24","12":"24.8.9|24.14.1-2","14":"25.50.20|32.29.10","17":"31.14.32","21":"25.78.11","22":"31.62.6","23":"48.8.21","24":"25.88.46","25":"24.21.21","26":"75.1.10","27":"31.51.6|50.24.35","28":"24.36.26|25.89.3|49.3.6"}},{"v":["Благослови, душе моя, Господа і, вся істото моя, ім’я святеє Його.","Благослови, душе моя, Господа і не забувай усіх добродійств Його.","Він очищає всі беззаконня твої, зціляє всі недуги твої.","Він звільняє від тління життя твоє, вінчає тебе милістю і щедротами.","Він виконує благі бажання твої: оновиться, подібно орляті, юність твоя.","Господь творить справедливість і суд усім покривдженим.","Показав путі Свої Мойсеєві, синам Ізраїлевим — хотіння Свої.","Щедрий і милостивий Господь, довготерпеливий і многомилостивий.","Не до кінця прогнівається і повік не ворогуватиме.","Не за беззаконнями нашими вчинив нам і не за гріхами нашими воздав нам.","Бо як високо небо над землею, так утвердив Господь милість Свою над тими, що бояться Його.","Як далеко схід від заходу, так віддалив Він від нас беззаконня наші.","Як отець милує дітей, так милує Господь тих, що бояться Його.","Бо Він знає сутність нашу, пам’ятає, що ми — порох землі.","Людина — як трава, дні її — немов цвіт польовий, цвіте й відцвітає.","Повіє вітер над нею, і не стане її: не знайти вже й місця по ній.","Милість же Господня від віку й до віку на тих, що бояться Його.","І правда Його на синах синів, що бережуть завіти Його і пам’ятають заповіді Його, щоб виконувати їх.","Господь на небесах уготував Престіл Свій, і Царство Його усім володіє.","Благословіть Господа, [всі] ангели Його, сильні міцністю, що виконуєте слово Його, слухаючи голосу слів Його.","Благословіть Господа, всі Сили Його, слуги Його, що творите волю Його.","Благословіть Господа, всі діла Його. На всіх місцях володіння Його благослови, душе моя, Господа!"],"h":"Псалом Давида.","x":{"1":"25.103.1","3":"25.29.3|13.30.20","4":"24.33.24","5":"25.5.13","6":"25.98.4","8":"3.14.18|17.9.17","9":"31.57.16","15":"31.40.6","16":"24.7.10","17":"25.24.6","18":"4.7.9|25.30.2","19":"25.9.8","20":"37.7.10","21":"66.3.10|68.1.16"}},{"v":["Благослови, душе моя, Господа. Господи Боже мій, як звеличився Ти дивно. Ти прибрався у славу й у величну красу.","Ти зодягаєшся у світло, як у ризу, простираєш небеса, як шатро.","Підносиш над водами горні палаци Твої, обертаєш хмари на колісницю для Себе, на крилах вітру Ти ходиш.","Ти твориш духів ангелами Своїми і слугами Своїми — вогненне полум’я.","Ти поставив землю на тверді її, не захитається вона повік віку.","Безодня, як одежа, покриває її; на горах стоять води.","Від повеління Твого вони біжать, від голосу грому Твого тікають.","Піднімаються на гори і сходять у долини в місце, що Ти призначив для них.","Ти поклав межу, якої не перейдуть вони і не повернуться, щоб покрити землю.","Ти посилаєш джерела в долини, поміж горами течуть [води.]","Ти напуваєш усіх звірів польових, дикі осли втамовують спрагу свою.","Над ними літають птахи небесні, голос їх лунає між віттям.","Ти напуваєш гори з висот Твоїх. Плодами діл Твоїх насичується земля.","Ти вирощуєш траву для худоби і злаки на користь людям, щоб добути хліб із землі.","І вино веселить серце людини, і єлей намащує лице її, і хліб — підкріпляє серце людини.","Насичуються дерева польові, кедри ливанські, що Ти насадив їх.","Там птахи гніздяться, гніздо ж чаплі — найвище.","Гори високі для оленів; скелі — захисток для зайців.","Ти створив місяць, щоб визначати час, і сонце знає захід свій.","Ти насуваєш темряву, і ніч настає; тоді бродить вся звірина лісова.","Леви ричать за здобиччю і просять від Бога поживи собі.","Сходить сонце — вони вертаються назад і лягають у лігвищах своїх.","Виходить людина для справ своїх і на працю свою до вечора.","Які величні діла Твої, Господи! Все премудро створив Ти; повна земля творіння Твого.","Ось море велике й просторе; там безліч гадів і тварі малої й великої.","Там плавають кораблі, і кити, що Ти їх створив вигравати у ньому.","Всі вони на Тебе сподіваються, що даси їм поживу у свій час.","Ти даєш їм — вони приймають. Ти відкриваєш руку Свою — вони наповнюються усяким благом.","Ти відвертаєш лице Твоє — вони тривожаться; віднімеш дух їх — вони щезнуть і у прах свій повернуться.","Пошлеш Духа Свого — і створяться, і Ти оновлюєш лице землі.","Нехай буде слава Господня навіки; звеселиться Господь від діл Своїх.","Він погляне на землю — і вона тремтить; торкнеться гір — і вони димлять.","Славитиму Господа все життя моє, співатиму Богові моєму, поки живу.","Нехай буде благоприємною Йому пісня моя, і я звеселюся в Господі.","Нехай щезнуть грішники з землі, і беззаконників нехай більше не буде. Благослови, душе моя, Господа! Алилуя!"],"h":"[Псалом Давида про сотворіння світу.]","x":{"1":"25.102.1:22","3":"0.1.7","4":"75.1.7","7":"24.37.5","9":"24.38.10-11","10":"25.73.15|4.11.11|24.5.10","14":"25.146.8","15":"6.9.13|30.40.20","20":"0.1.16","21":"25.146.9|31.31.4","22":"24.37.8","24":"25.32.5|25.91.6","25":"30.43.27","26":"24.40.20","27":"25.144.15","28":"26.6.8","29":"24.12.10|37.5.23","30":"24.33.4","32":"25.143.5","33":"25.33.2","35":"25.102.1"}},{"v":["Прославляйте Господа і призивайте ім’я Його. Сповіщайте між народами про діла Його.","Співайте Йому і славте Його, розповідайте про всі чудеса Його.","Хваліться іменем святим Його. Нехай радіє серце тих, що шукають Господа.","Шукайте Господа й сили Його, шукайте лиця Його завжди.","Згадуйте чуда Його, що він створив, знамення Його й суди уст Його.","Ви, насіння Авраамове, раби Його, сини Якова — обрані Його.","Він є Господь Бог наш: по всій землі суди Його.","Він навіки пам’ятає завіт Свій, слово, [яке] заповідав у тисячі родів,","яке заповідав Авраамові, і клятву Свою Ісаакові.","І поставив його законом для Якова та Ізраїля в завіт вічний,","кажучи: «Дам тобі землю Ханаанську в поділ насліддя вашого».","Коли їх було ще мало за кількістю, дуже мало, і були вони чужинцями в ній,","і переходили вони від народу до народу, з царства до племені іншого,","Він не дозволив нікому кривдити їх і забороняв про них царям:","«Не доторкайтеся до помазаних Моїх і не чиніть зла пророкам Моїм».","І прикликав голод на землю, і знищив усяке хлібне стебло.","Послав перед ними чоловіка; в рабство був проданий Йосиф.","Скували кайданами ноги йому, в залізних путах була душа його,","аж поки сповнилося слово Його, слово Господнє випробувало його.","Послав цар і звільнив його, володар народу випустив його.","І поставив його господарем над усім домом своїм і правителем над усім володінням своїм.","Щоб він настановляв вельмож його за душею своєю і старійшин його навчав мудрости.","Тоді прийшов Ізраїль до Єгипту, і переселився Яків у землю Хамову.","І дуже розмножив Бог людей Своїх, і зробив їх сильнішими від ворогів їхніх.","Попустив серце єгиптян зненавидіти народ Його, чинити напасті рабам Його.","Тоді послав Мойсея, раба Свого, і Аарона, якого вибрав.","Вони показали між ними слова знамень Його і чудеса [Його] в землі Хамовій.","Наслав темряву і зробив морок, і не могли суперечити слову Його.","Перемінив воду їх на кров і поморив усю рибу їх.","Закишіла земля їх жабами, навіть у покоях царів їхніх.","Сказав Він, і роями з’явились оводи й комарі у всій країні їх.","Послав на них град замість дощу, і вогонь палючий на землю їх.","Побив виноград і смоковниці їх, і дерева поламав у країні їх.","Сказав, і прийшли сарана та гусінь — без ліку.","І пожерли всю траву на землі їх, поїли увесь урожай на полях їх.","І умертвив всякого первістка в землі їх, початки всієї сили їх.","І вивів ізраїльтян із сріблом і золотом, і не було хворого в колінах (поколіннях) їх.","Зрадів Єгипет, коли вийшли вони, бо обійняв його страх перед ними.","Господь розпростер над ними хмару, як покров [їм], і вогняний стовп, — щоб світив [їм] уночі.","Просили вони, і Він послав їм перепелиць і хлібом небесним насичував їх.","Розколов скелю, і потекла вода, зашуміла рікою по землі сухій.","Бо згадав Він слово Своє до Авраама, раба Свого,","і вивів народ Свій з радощами, обраних Своїх — з веселощами.","І дав їм землю народів, і успадкували вони працю чужих народів.","Щоб заповіді Його виконували й дотримувалися закону Його. Алилуя!"],"h":"(Алилуя.)","x":{"1":"12.16.8|31.12.4","2":"25.70.17","3":"25.33.4","8":"54.7.5|1.2.24","9":"0.17.2|0.26.3|52.1.73|75.6.13","10":"0.13.15","13":"0.13.8|75.11.8","14":"0.12.17","15":"12.16.22","16":"0.41.57","17":"0.37.28","18":"0.39.20","20":"0.41.14","21":"54.7.10","23":"0.46.6","24":"1.1.7|54.7.17","25":"1.1.14","26":"1.3.10","27":"1.7.10","28":"1.10.22","29":"1.7.20|25.77.44","30":"1.8.6","31":"1.8.17|25.77.45","32":"1.9.23","33":"1.9.25|25.77.47","34":"1.10.13-14|25.77.46","36":"1.12.29|25.77.51","37":"1.12.35","38":"1.12.33","39":"1.13.21|25.77.14","40":"1.16.13","41":"1.17.6|3.20.11|25.77.16|29.11.4|63.10.4","42":"0.22.16","43":"5.3.1"}},{"v":["Прославляйте Господа, бо Він благий, бо повіки милість Його.","Хто висловить могутність Господа, звістить усі хвали Його?","Блаженні ті, хто чинить правосуддя і дотримується справедливости.","Пом’яни нас, Господи, в любові до людей Твоїх, завітай до нас спасінням Твоїм,","щоб мені бачити блаженне життя обраних Твоїх, радіти радощами народу Твого, хвалитися з насліддям Твоїм.","Нагрішили ми, як і батьки наші, жили не за правдою, творили беззаконня.","Батьки наші у Єгипті не зрозуміли чудес Твоїх, не пам’ятали про багатство милосердя Твого та прогнівили Тебе біля моря, Червоного моря.","Але Ти, Господи, спас їх ради імені Твого, щоб показати могутність Твою.","І наказав Господь Червоному морю, і розступилося воно, і перевів їх через безодню, наче через пустелю.","І врятував їх від руки ненависника, і визволив їх від руки ворога.","Покрила вода гнобителів їх, жоден з них не залишився.","І повірили вони словам Його [і] заспівали хвалу Йому.","Та скоро забули діла Його, не покладали надії на волю Його.","Забажали м’яса в пустелі і випробовували силу Бога в країні безлюдній.","Він виконав бажання їх, але послав рану на душі їхні.","І заздрили у стані Мойсеєві та Ааронові, святому Господа.","Тоді розступилася земля і поглинула Дафана, покрила зборище Авирона.","Упав вогонь на них, і полум’я попалило богопротивних.","Зробили вони тельця біля Хорива і поклонилися ідолові.","Проміняли славу Бога на образ тельця, що їсть траву.","Забули Бога, Спасителя свого, що звершив величне у Єгипті,","дивне — в землі Хамовій, страшне — на Червоному морі.","І хотів Він винищити їх, коли б Мойсей, вибраний Його, не став перед Ним у благанні, щоб відвернути гнів Його; щоб не погубив [їх].","І зневажили вони землю жадану, не стали вірити словам Його;","Нарікали в наметах своїх і не слухали голосу Господнього.","І підняв Він руку Свою на них, щоб знищити їх у пустелі,","розвіяти нащадків їх між народами, розсіяти їх по землі.","Вони пристали до Ваалфегора і їли жертви мертвих,","і прогнівляли Бога ділами своїми. За це хвороба стала нищити їх.","Тоді встав Финеєс і вчинив суд над винними, і пошесть припинилася.","І це зараховано йому в праведність з роду й до роду повіки.","І прогнівили вони Бога біля вод Меріви, і Мойсей потерпів за них,","бо так вони засмутили дух його, що він згрішив устами своїми.","Не знищили народів, про яких говорив їм Господь,","але змішалися з язичниками і навчилися звичаїв їх,","стали служити ідолам їх, які стали для них спокусою,","приносили в жертву бісам синів своїх і дочок своїх;","проливали кров безвинну, кров синів своїх та дочок своїх, приносячи їх в жертву ідолам ханаанським, — і осквернилася земля кров’ю;","осквернили себе ділами своїми, блуд творили в ділах своїх.","Тоді запалав гнів Господа на народ Його, і противним стало Йому насліддя Його.","і віддав їх у руки язичницьких народів, і вороги їх стали володіти ними.","Вороги гнобили їх, і вони корилися під рукою їхньою.","Багато разів Він визволяв їх, вони ж гнівили [Його] впертістю своєю, тому були принижені за беззаконня своє.","Але Він зглянувся на скорботу їх, коли почув стогін їх.","Згадав завіт Свій з ними і жаль огорнув Його з великого милосердя Його.","І збуджував милосердя до них у всіх тих, що поневолили їх.","Спаси нас, Господи, Боже наш! Збери нас з-поміж народів, щоб славити святе ім’я Твоє та хвалитися славою Твоєю.","Благословен Господь, Бог Ізраїля, од віку до віку. І нехай скаже увесь народ: амінь! Алилуя!"],"h":"Алилуя.","x":{"1":"25.117.1","2":"30.43.34","3":"25.36.37","4":"17.5.19","5":"25.2.8","6":"37.9.5","7":"1.14.11","9":"1.14.21|25.77.13","10":"52.1.71","11":"1.14.28","13":"32.2.32","14":"3.11.33","16":"3.16.2","17":"3.16.31|4.11.6","19":"1.32.4","20":"62.1.23","23":"1.32.11","24":"3.14.2","25":"4.1.27","26":"3.14.29","28":"3.25.3","30":"3.25.7","31":"3.25.13","32":"3.20.3","34":"4.7.2","35":"38.7.8","36":"1.23.33|4.7.16","37":"2.18.21|4.12.31|11.21.6","40":"6.2.14|6.3.8","45":"4.30.1-3","47":"12.16.35|31.11.12","48":"12.16.36|25.40.14|25.71.18"}},{"v":["Прославляйте Господа, бо Він благий, бо повіки милість Його.","Так нехай скажуть визволені Господом, яких Він визволив із руки ворога,","і зібрав їх із усіх країв — зі сходу й заходу, з півночі і півдня.","Блукали вони по пустелі безлюдними шляхами і не знаходили міста заселеного.","Голод і спрагу терпіли вони, знемагала в них душа їхня.","Тоді взивали до Господа в скорботі своїй, і Він визволив їх із біди їхньої.","І привів їх прямою дорогою до міста заселеного.","Нехай же прославляють Господа за милість Його і за дивні діла Його для синів людських,","бо Він наситив душу спраглу і душу голодну сповнив добром.","Вони сиділи в темряві і тіні смертній, сковані скорботою та залізом,","бо не скорилися словам Божим і зневажали вони Всевишнього.","Він же смирив серця їхні стражданнями, вони падали, і не було кому допомогти їм.","Тоді взивали вони до Господа в скорботі своїй, і Він визволив їх від бід їхніх,","вивів їх із темряви і тіні смертної і кайдани їх розірвав.","Нехай же прославляють Господа за милість Його і дивні діла Його для синів людських:","бо розбив Він брами мідні і замки залізні зламав.","Непокірні страждали через беззаконне життя своє і за неправди свої терпіли.","Душа їхня відверталася від усякої поживи, і наблизилися вони до воріт смерти.","Тоді взивали вони до Господа в скорботі своїй, і Він визволив їх від бід їхніх,","послав їм слово Своє і зцілив їх, і з могил їхніх вивів їх.","Нехай же прославляють Господа за милість Його і за дивні діла Його для синів людських.","Нехай приносять Йому жертви хвали, і піснями радости нехай сповіщають про діла Його.","Ті, що на кораблях плавають по морю і виконують роботу свою на водах великих,","вони бачать діла Господні і чудеса Його на глибині:","скаже Він — і здійметься буйний вітер, який високо підносить хвилі, —","піднімає їх до неба, і опускає в безодню, і від страху мліє душа людей.","Кружляють вони і хитаються, наче п’яні, — зникає вся мудрість їхня.","Тоді взивають вони до Господа в скорботі своїй, і Він визволяє їх від біди.","Він повелів бурі, і настала тиша, і хвилі затихли.","І радіють вони, що море втихло, а Він приводить їх до бажаної пристані.","Нехай же прославляють Господа за милість Його і за дивні діла Його для синів людських.","Нехай вихваляють Його в зібранні людей і прославляють Його на зборах старійшин.","Він перетворює ріки на пустелю і джерела води на безводну землю,","землю родючу на солончаки за беззаконня тих, що живуть в ній.","Він перетворює пустелю на озера, і землю засохлу — на джерела води.","І оселяє там голодних; вони будують міста — оселі собі,","засівають поля, насаджують виноградники, що приносять їм великий урожай.","Він благословляє їх, і вони швидко розмножуються, і тварин у них не зменшується.","Вони занепадали від гноблення, біди і скорботи,","тоді Він посилав безчестя на князів їхніх і залишав їх блукати по пустелі, де немає шляхів.","Убогого Він спасав від біди і примножував рід його, як отари овець.","Бачать це праведники і радіють, а беззаконні замикають уста свої.","Хто мудрий, той помітить це і зрозуміє милості Господні."],"h":"[Алилуя.]","x":{"1":"19.16.1","2":"25.105.10","4":"75.11.9:37|75.13.14","6":"25.21.6","9":"25.33.11|25.144.16","10":"24.36.8","12":"11.14.26","16":"25.115.7|31.45.2|44.1.13","18":"24.33.20","20":"29.16.12","22":"25.49.14|25.115.8","24":"30.43.26","25":"42.1.4|50.8.24","27":"31.29.14|36.7.26","29":"50.14.32","34":"10.17.1|39.1.10","35":"31.41.18","39":"25.43.26","40":"24.12.21","41":"8.2.8","42":"24.5.16|24.22.19","43":"4.32.29|32.9.12"}},{"v":["Пісня. Псалом Давида.","Готове серце моє, Боже, [готове серце моє]. Буду співати і прославляти в славі моїй.","Встань, славо моя, встаньте, псалтирю і гуслі, я встану рано.","Буду славити Тебе, Господи, між народами. Буду оспівувати Тебе серед племен.","Бо вище небес милість Твоя, і до хмар істина Твоя.","Вознесися на небеса, Боже, і по всій землі слава Твоя,","щоб спаслися всі улюблені Твої. Спаси правицею Твоєю і почуй мене.","Бог сказав у святині Своїй: «Піднесуся і розділю Сихем, і долину осель розмірю:","Мій — Галаад, Мій — Манассія, Єфрем — сила глави Моєї, Іуда — скіпетр Мій,","Моав — умивальна чаша Моя, на Едома стану ногою Моєю, земля филистимська скориться Мені».","Хто введе мене в укріплене місто? Хто приведе мене до Едома?","Чи не Ти, Боже, що відкинув нас, і не виходиш, Боже, з військом нашим?","Дай нам поміч у скорботі, бо марна надія на захист людський.","З Богом ми покажемо силу, Він знищить ворогів наших."],"x":{"2":"25.56.8","5":"25.35.6","6":"25.56.6","7":"25.59.7","8":"25.59.8","9":"25.59.9","11":"25.59.11","12":"25.59.12","14":"25.59.14"}},{"v":["Боже хвали моєї! Не мовчи.","Бо відкрилися на мене уста нечестиві й уста підступні; говорять про мене слова неправди.","Словами ненависти звідусіль оточують мене і повстають проти мене без причини;","за любов мою вони ворогують проти мене, я ж молюся;","віддають мені злом за добро, і ненавистю — за любов мою.","Постав над ним нечестивого, і диявол нехай стане праворуч нього.","Коли стане на суд, хай він вийде осудженим, і молитва його буде йому за гріх.","Нехай дні його будуть короткими і достоїнство його перейме інший.","Діти його хай будуть сиротами і дружина його — вдовою.","Будуть вони блукати та просити хліба і будуть вигнані із домів їх.","Хай позичкодавець його забере в нього все, і чужі розтягнуть добро його.","Хай не буде йому заступника, і ніхто не приголубить сиріт його;","нехай згинуть усі нащадки його, і вже в наступному поколінні ніхто не згадає й імені його.","Нехай згадаються перед Господом беззаконня батьків його, і гріх матері його не буде очищений.","Нехай будуть вони повсякчас перед Господом, і Він знищить і спомин про них на землі,","за те, що не виявив він милости, а переслідував людину бідну, беззахисну, засмучену серцем, щоб убити її.","Він полюбив прокляття, воно і прийде на нього; не побажав благословення, — і воно одійшло від нього.","Нехай він одягнеться в прокляття, наче в одежу, і нехай увійде воно, як вода, в утробу його і, як олива, в кості його;","і нехай буде воно йому як одіж, в яку він одягається, і як пояс, яким він завжди підперізується.","Ось така відплата від Господа ворогам моїм і тим, що говорять зло на душу мою!","Ти ж, Господи, Господи, захисти мене заради імені Твого, бо блага милість Твоя.","Спаси мене, бо я знеможений і вбогий, і серце моє поранене в мені.","Я зникаю, як та тінь, що відхиляється; стрясаюся, як та сарана, що гонять її.","Коліна мої знесиліли від посту, і тіло моє сохне без поживи.","І став я посміховиськом для них: ті, що дивляться на мене, похитують головами.","Допоможи мені, Господи, Боже мій! Спаси мене з милости Твоєї.","Нехай пізнають, що це — Твоя рука і що це Ти, Господи, вчинив.","Вони проклинають, а Ти благослови. Вони нападають, але нехай будуть посоромлені; а раб Твій нехай возрадується.","А ворогів моїх нехай покриє безчестя і, як одежею, нехай вони покриються соромом своїм.","А я голосно буду славити Господа устами моїми і серед багатьох буду прославляти Його,","бо Він стоїть праворуч бідного, щоб спасти його від тих, що шукають душу мою."],"h":"Начальнику хору. Псалом Давида.","x":{"2":"51.14.56","4":"25.119.7|53.8.40","5":"25.34.12|32.18.20","6":"24.17.8","8":"53.17.12|54.1.20","9":"4.28.32","10":"24.20.10","11":"4.28.43","13":"1.20.5|24.18.19|31.14.22","14":"1.20.5|32.18.23","15":"26.10.7|50.27.25","16":"24.24.20|55.2.13","17":"26.11.27|29.1.12","23":"24.14.2|25.143.4","25":"25.21.8|50.27.29","27":"25.63.10","28":"50.5.44|63.4.12-13","30":"25.21.23","31":"54.2.25"}},{"v":["Сказав Господь Господу моєму: «Сиди праворуч Мене, доки покладу ворогів Твоїх у підніжжя ніг Твоїх».","Жезл сили Твоєї пошле Господь із Сиона; царюй посеред ворогів Твоїх.","З Тобою народ Твій у день сили Твоєї, у світлостях святих Твоїх. «Із утроби раніше віків Я породив Тебе».","Клявся Господь і не розкається: «Ти священик повік за чином Мелхиседековим».","Господь праворуч Тебе, Він у день гніву Свого уразить царів.","Він учинить суд над народами, покриє землю трупами, знищить голови багатьох у великій країні.","І з потоку в дорозі буде пити, тому високо піднесе голову."],"h":"Псалом Давида.","x":{"1":"50.22.44|51.12.36|52.20.42|54.2.34|63.15.25|75.1.13","4":"75.5.6|75.7.17","5":"25.2.10","7":"67.2.8-9"}},{"v":["Прославляю [Тебе], Господи, всім серцем [моїм] в раді праведників і в зібранні.","Великі діла Господні, вони жадані для всіх, що люблять їх.","Діла Його — краса і слава; правда Його перебуває вічно.","Незабутніми зробив Він чудеса Свої; щедрий і милостивий Господь.","Він дає поживу всім тим, що бояться Його. Завіт Свій пам’ятає вічно.","Могутність діянь Своїх явив Він народові Своєму, щоб дати йому насліддя народів.","Діла рук Його — істина й правосуддя; всі заповіді Його вірні,","тверді на віки вічні, встановлені на істині й правоті.","Визволення послав Господь народові Своєму, навіки поставив завіт Свій. Святе і страшне ім’я Його.","Початок премудрости — страх Господній, і розум добрий мають ті, що додержуються заповідей Його. Хвала Йому на віки віків."],"h":"Алилуя.","x":{"1":"25.9.2|75.10.25","2":"24.37.14","3":"25.9.9|25.47.11|25.101.28","5":"25.36.19|52.1.72","6":"4.9.6","7":"37.4.34","9":"52.1.68|52.11.2","10":"24.28.28|26.1.7|26.9.10|30.11.16"}},{"v":["Блажен муж, що боїться Господа і дуже любить заповіді Його.","Сильним на землі буде покоління його. Рід праведних буде благословенний.","Слава і багатство буде в домі його; праведність його перебуватиме вічно.","У темряві сяє світло праведникові; він лагідний, милосердний і справедливий.","Добрий чоловік має милосердя і в позику дає; на суді він твердо говорить слово своє.","Він повіки не захитається. Пам’ять праведникові буде вічна.","Лихих наклепів він не убоїться; серце його надіється на Господа.","Упевнене серце його: він не злякається, коли побачить ворогів своїх.","Він роздає щедро, подає вбогим, праведність його перебуватиме вічно, сила його піднесеться у славі.","Побачить це нечестивий і розгнівається, заскрегоче зубами і згине. Бажання нечестивців не здійсниться."],"h":"Алилуя.","x":{"1":"25.1.1|25.127.1","2":"26.20.7","3":"25.33.10","4":"1.10.23|20.8.16","5":"25.36.26","6":"26.10.7","7":"30.34.16","8":"26.4.23","9":"25.36.26|64.9.9","10":"25.34.16|25.36.12"}},{"v":["Хваліть, раби Господні, хваліть ім’я Господнє!","Нехай буде благословенне ім’я Господнє віднині і довіку.","Від сходу сонця й до заходу нехай буде прославлене ім’я Господнє.","Високо над усіма народами Господь, вище небес слава Його.","Хто — як Господь Бог наш?! Він перебуває на небесах.","Він нахиляється, щоб доглядати небо й землю;","з пороху піднімає бідного і з гноїща підносить убогого,","щоб посадити його з князями народу Свого;","неплідну робить матір’ю, яка в домі своїм втішається дітьми. Алилуя!"],"h":"Алилуя.","x":{"1":"25.134.1","2":"37.2.20","3":"49.1.11","4":"25.96.9","5":"25.137.6|31.57.15","7":"10.16.2","8":"8.16.12","9":"25.67.7"}},{"v":["Коли вийшов Ізраїль з Єгипту, дім Якова — від людей чужих,","Юдея стала святинею Його, а Ізраїль — володінням Його.","Море побачило і розступилося, Йордан повернув назад.","Гори підстрибували, як вівці, і пагорби — наче ягнята.","Чого ти, море, розступилося? І ти, Йордане, чого повернув назад?","Чого ви, гори, як вівці, скачете, і ви, пагорби, наче ягнята?","Перед лицем Господа затряслася земля, перед лицем Бога Якова,","що перетворив камінь на озеро води, скелю — на джерело потоків.","Не нам, Господи, не нам, а імені Твоєму дай славу з милости Твоєї.","Щоб не сказали народи: «Де Бог їх?»","Бог наш на небесах [і на землі], все, що захотів, створив.","Ідоли язичників — срібло й золото, діло рук людських:","мають уста, та не говорять, мають очі, та не бачать,","мають вуха, та не чують, мають ніздрі, та нема в них нюху;","руки їх не діють, ноги їх не ходять, жодного звуку немає в гортані їх.","Подібні до них і ті, що роблять їх, і ті, що надіються на них.","[Доме] Ізраїля! Уповай на Господа, Він — наша поміч і захист.","Доме Аарона! Уповай на Господа, Він — наша поміч і захист.","Всі, що боїтеся Господа, уповайте на Господа, Він — наша поміч і захист.","Господь пам’ятає про нас і благословляє [нас]: Він благословив дім Ізраїля, благословив дім Аарона,","Він благословляє тих, що бояться Господа — малих і великих.","Нехай же додасть вам Господь все більше й більше, вам і дітям вашим.","Нехай благословить вас Господь, що сотворив небо і землю.","Небо над небесами — оселя Господа, а землю Він дав синам людським.","Не мертві хвалитимуть Господа, і не всі, що сходять у могилу.","А ми, [живі,] будемо благословляти Господа віднині й довіку. Алилуя."],"h":"[Алилуя.]","x":{"1":"1.13.3","3":"1.14.21-22|5.3.16","4":"25.67.17","5":"44.1.4","8":"1.17.6|3.20.11","9":"12.16.35","10":"25.41.4","11":"4.33.26","13":"29.15.15","14":"25.134.17","16":"32.10.8","17":"25.129.5","24":"4.10.14","25":"25.6.6|31.38.18|35.2.17","26":"37.2.20"}},{"v":["Я люблю Господа, Він почув голос благання мого.","Прихилив до мене вухо Своє; буду призивати Його в усі дні мої.","Обійняли мене болі смертельні, і муки пекельні найшли на мене: я зустрів скорботу й утиски.","Тоді я призвав ім’я Господнє: «Господи, спаси душу мою!»","Милостивий і праведний Господь; Бог наш милує нас.","Господь охороняє немовлят: я знесилився, і Він допоміг мені.","Повернися, душе моя, у спокій твій, бо Господь облагодіяв тебе.","Ти, Господи, спас душу мою від смерти, очі мої — від сліз, ноги мої — від спотикання. Буду ходити перед Господом у країні живих."],"h":"[Алилуя.]","x":{"2":"25.30.3","3":"9.22.5","5":"25.85.5","6":"50.10.16","8":"25.55.14"}},{"v":["Вірував я, тому й заговорив, і я смирився вельми.","І сказав я в нестямі моїй: «Кожна людина говорить неправду!»","Що віддам Господу за все, що Він воздав мені?","Чашу спасіння прийму й ім’я Господнє призву.","Молитви мої Господу воздам перед усіма людьми Його.","Чесна перед Господом смерть преподобних Його.","О Господи, я раб Твій, я раб Твій і син рабині Твоєї. Ти розірвав кайдани мої.","Тобі принесу я жертву хваління й ім’я Господнє призву.","Молитви мої Господу воздам перед усіма людьми Його.","У дворах дому Господнього, посеред тебе, Єрусалиме. Алилуя."],"h":"[Алилуя.]","x":{"1":"64.4.13","2":"62.3.4","4":"25.22.5","5":"25.21.26","7":"29.9.5","8":"25.49.14|75.13.15"}},{"v":["Хваліть Господа, всі народи, прославляйте Його, всі люди.","Бо велика милість Його над нами й істина Його [перебуває] вічно. Алилуя."],"h":"[Алилуя.]","x":{"1":"54.13.48|62.15.11","2":"25.99.5"}},{"v":["Прославляйте Господа, бо Він благий, бо повіки милість Його.","Нехай же промовить [дім] Ізраїлів, що Господь благий, і повіки милість Його.","Нехай говорить дім Ааронів, що Господь благий, і повіки милість Його.","Нехай говорять всі, що бояться Господа, бо [Він благий,] і повіки милість Його.","У скорботі взивав я до Господа, і Він почув мене і вивів мене на простір.","Господь — мій помічник, і я не боюся, що зробить мені людина.","Господь — мій помічник, і я сміливо дивлюся на ворогів моїх.","Краще уповати на Господа, аніж надіятися на людину.","Краще уповати на Господа, аніж покладатися на князів.","Обступили й оточили мене, я ж іменем Господнім переміг їх.","Оточили мене, але я іменем Господнім подолав їх,","обсіли мене, наче бджоли [соти], розгорілися, як вогонь у сухому терні, але я іменем Господнім подолав їх.","Вони били мене, щоб я впав, але Господь підтримав мене,","Господь — моя сила і пісня моя, і став моїм спасінням.","Голос радости і спасіння в оселях праведників. Правиця Господня дає їм силу,","правиця Господня піднесла мене, правиця Господня дала мені силу.","Не умру, а житиму і повідатиму про діла Господні.","Караючи, покарав мене Господь, але смерті не віддав мене.","Відчиніть мені врата правди, і я ввійду ними і прославлю Господа.","Ось врата Господні; праведні увійдуть ними.","Прославляю Тебе, Господи, що Ти почув мене і став моїм спасінням.","Камінь, що занедбали будівничі, став в основу (наріжним каменем).","Від Господа це сталося, і дивне воно в очах наших.","Цей день, його ж створив Господь, радіймо й веселімось в нім.","О Господи! Спаси, о Господи! Допоможи.","Благословен, хто йде в ім’я Господнє. Благословляємо вас із дому Господнього.","Бог Господь і явився нам. Вчиніть свято, несіть жертви до Жертовника Господнього.","Ти — Бог мій, буду хвалити Тебе. Ти Бог мій, [буду славити Тебе. Бо Ти почув мене і став моїм спасінням].","Прославляйте Господа, бо Він благий, бо повіки милість Його."],"h":"[Алилуя.]","x":{"1":"25.135.1","5":"31.26.16","6":"25.26.1|25.55.12|62.8.31","7":"75.13.6","8":"25.61.9|25.83.13|25.107.13","11":"8.17.45","12":"4.1.44|31.7.18","14":"1.15.2|31.12.2","17":"31.53.11|62.6.9","18":"36.18.21","19":"31.26.2|75.9.24","22":"31.28.16|50.21.42|51.12.10","26":"50.21.9|51.11.9|52.19.38","29":"25.135.1"}},{"v":["Блаженні непорочні, що ходять у законі Господнім.","Блаженні ті, що додержують свідчення Його і всім серцем шукають Його.","Вони не чинять беззаконня і путями Його ходять.","Ти наказав виконувати заповіти Твої пильно.","О, коли б дороги мої вели мене до виконання постанов Твоїх!","Тоді б не осоромився я, зважаючи на всі заповіді Твої.","Буду славити Тебе в правоті серця, навчаючись судів правди Твоєї.","Буду сповняти повеління Твої, не покидай мене.","Як юнакові додержати в чистоті дорогу свою? Тільки додержанням слів Твоїх.","Всім серцем моїм я шукаю Тебе, не дай мені відхилитися від заповідей Твоїх.","Слово Твоє заховав я в серці моїм, щоб не згрішити перед Тобою.","Благословен єси, Господи, навчи мене заповітів Твоїх.","Устами моїми сповіщав я суди уст Твоїх.","Дорогами свідчень Твоїх я втішався, як найбільшим багатством.","Заповідям Твоїм навчаюся я і буду пильнувати путі Твої.","Заповіти Твої — утіха моя; не забуду я слова Твого.","Яви милість Твою рабу Твоєму, я буду жити і додержуватися слова Твого.","Відкрий очі мої, і зрозумію чуда закону Твого.","Я подорожній на землі, не приховуй від мене заповідей Твоїх.","Стомилася душа моя від щоденного бажання зрозуміти суди Твої.","Ти упокорив гордих, проклятих, що відхилилися від заповідей Твоїх.","Зніми з мене сором і зневагу, бо я додержувався заповітів Твоїх.","Бо князі сидять і змовляються проти мене, я ж, раб Твій, роздумую про постанови Твої.","Свідчення Твої — втіха моя, [і накази Твої] — радники мої.","В землю никне душа моя, оживи мене за словом Твоїм.","Розповів я про дороги мої, і Ти вислухав мене, навчи ж мене заповітів Твоїх.","Дай мені зрозуміти дорогу повелінь Твоїх, і я буду розмірковувати про дивні діла Твої.","Ниє душа моя від скорботи, підкріпи мене за словом Твоїм.","Одверни від мене дорогу неправди і в законі Твоїм провадь мене.","Я обрав дорогу істини і поставив перед собою суди Твої.","Я пристав до свідчень Твоїх — Господи, не осором мене.","Піду дорогою заповідей Твоїх, коли Ти розшириш серце моє.","Покажи мені, Господи, дорогу постанов Твоїх, і я буду триматися її до кінця життя мого.","Врозуми мене, щоб я навчився закону Твого, і буду дотримуватися його всім серцем моїм.","Постав мене на стежку заповідей Твоїх, бо я бажаю її.","Нахили серце моє до свідчень Твоїх, а не до лихої користи.","Одверни очі мої, щоб не дивилися на марноту; оживляй мене на дорозі Твоїй.","Постав слово Твоє перед рабом Твоїм, щоб мав я страх перед Тобою.","Одверни від мене зневагу, якої боюся я, бо суди Твої милостиві.","Ось я жадаю наказів Твоїх, оживляй мене Правдою Твоєю.","І нехай прийде на мене милість Твоя, Господи, спасіння Твоє за словом Твоїм.","І я дам відповідь тим, що ганьблять мене, бо уповаю на слова Твої.","Не відбери слова правди від уст моїх, бо на суди Твої надія моя.","Буду додержуватися закону Твого повсякчас і на віки віків.","Буду ходити простором широким, бо прагну до виконання заповідей Твоїх.","Перед царями буду говорити про свідчення Твої і не посоромлюся.","Буду втішатися заповідями Твоїми, бо я їх дуже люблю.","Руки мої буду простягати до заповідей Твоїх, які я люблю, і розмірковуватиму про накази Твої.","Згадай слова [Твої] до раба Твого, на які Ти звелів мені уповати.","Це — втіха моя в горі моїм, що слово Твоє оживляє мене.","Горді тяжко знущалися з мене, але я не відхилився від закону Твого.","Згадую, Господи, присуди Твої одвічні і втішаюся.","Сум огортає мене за грішників, що відкинули закон Твій.","Постанови Твої — то пісня моя на місці блукання мого.","Вночі поминав я ім’я Твоє, Господи, і тримався закону Твого.","Він став рідним мені, бо я дотримуюся наказів Твоїх.","Я сказав: Господи! Щастя моє в тому, щоб сповняти слова Твої.","Молю Тебе всім серцем моїм: помилуй мене за словом Твоїм.","Думав я про дороги мої, і ось повернув стопи мої до заповітів Твоїх.","Поспішав я і не затримувався виконувати заповіді Твої.","Сіті безбожних оточили мене, але не забув я закону Твого.","Опівночі вставав я прославляти Тебе за праведні суди Твої.","Я спільник тим, що бояться Тебе і шанують повеління Твої.","Милости Твоєї, Господи, повна земля; навчи мене заповітів Твоїх.","Благо зробив Ти, Господи, слузі Твоєму за словом Твоїм.","Доброго розуміння та знання навчи мене, бо заповідям Твоїм я вірю.","Як ще не був я упокореним, я блукав, а нині я тримаюся слова Твого.","Благий Ти, [Господи], і благістю Твоєю навчи мене заповідей Твоїх.","Примножили на мене неправду горді, але я всім серцем моїм схиляюся до заповідей Твоїх.","Загрубіло серце їх, як сир з молока, я ж утішаюся в законі Твоїм.","Благо мені, що Ти упокорив мене, щоб я навчився заповітів Твоїх.","Благий для мене закон уст Твоїх, більше за тисячі золота й срібла.","Руки Твої створили мене і впорядкували мене; врозуми мене, і навчуся заповідей Твоїх.","Ті, що бояться Тебе, побачать мене і звеселяться, що я уповаю на слово Твоє.","Знаю, Господи, що суди Твої праведні, і що Ти справедливо покарав мене.","Нехай же буде милість Твоя втіхою мені за словом Твоїм до раба Твого.","Нехай зійде на мене милосердя Твоє, і я буду жити, бо закон Твій — повчання моє.","Нехай будуть посоромлені горді, бо вони безвинно нападають на мене; а я буду навчатися в повеліннях Твоїх.","Нехай прийдуть до мене ті, що бояться Тебе і знають свідчення Твої.","Нехай буде серце моє непорочним у законі Твоїм, щоб не осоромився я.","Умліває душа моя за спасінням Твоїм; я покладаюся на слово Твоє.","Плачуть очі мої за словом Твоїм; я кажу: «Коли Ти втішиш мене?»","Я став як той міх у диму, але наказів Твоїх не забув.","Скільки ще днів для раба Твого? Коли вчиниш гонителям моїм суд?","Яму викопали для мене горді наперекір закону Твоєму.","Всі заповіді Твої — істина. Безвинно переслідують мене; поможи мені.","Ледве не знищили мене на землі, я ж не покинув заповідей Твоїх.","Оживи мене за милістю Твоєю, і буду берегти свідчення вуст Твоїх.","Навіки, Господи, слово Твоє перебуває на небесах.","З роду в рід істина Твоя. Ти поставив землю, і вона стоїть твердо.","З волі Твоєї все стоїть аж до цього дня, бо все служить Тобі.","Коли б не закон Твій був утіхою мені, то я б загинув у біді моїй.","Повік не забуду повелінь Твоїх, бо ними Ти оживив мене.","Твій — я, спаси мене, бо я сповняв веління Твої.","Нечестивці підстерігають, щоб погубити мене, я ж заглиблююсь у свідчення Твої.","Я бачив кінець всього досконалого, але заповідь Твоя широка безмірно.","О, як люблю я закон Твій! Цілий день думки мої про нього.","Ти зробив мене мудрішим від ворогів моїх заповітами Твоїми, бо вони завжди зі мною.","Я зрозумів більше за всіх учителів моїх, бо я вдумуюсь у свідчення Твої.","Став я мудрішим за старших, бо дотримуюся заповітів Твоїх.","Від усякої стежки лукавої я стримував ноги мої, щоб берегти слово Твоє.","Від судів Твоїх я не відхилявся, бо Ти, Боже, навчив мене.","Які солодкі слова Твої в устах моїх! Вони солодші за мед на язиці моїм.","Ти зробив мене мудрим заповітами Твоїми, тому зненавидів я всяку дорогу неправди.","Закон Твій — світильник для ніг моїх і світло на стежках моїх.","Я поклявся і постановив додержуватися праведних судів Твоїх, і додержусь.","Дуже знеможений я, Господи! Оживи мене за словом Твоїм.","Прийми ж милостиво, Господи, добровільну жертву мою і навчи мене судів Твоїх.","В небезпеці завжди душа моя, та не забув я закону Твого.","Богопротивні поставили сіті для мене, але я від наказів Твоїх не відхилився.","Свідчення Твої я прийняв, як насліддя вічне, бо вони — радість серця мого.","Я нахилив серце моє сповняти накази Твої вічно, до кінця життя мого.","Тих, що противляться закону, я зненавидів, закон же Твій полюбив.","Ти — моя поміч і захист мій; я уповаю на слово Твоє.","Відійдіть від мене, беззаконники, я буду навчатися в заповідях Бога мого.","Заступи мене, Господи, за словом Твоїм, і я буду жити; не осором мене в надії моїй.","Поможи мені, і я спасуся, і безперестанно буду навчатися заповітів Твоїх.","Ти на ніщо обернув тих, що відступили від закону Твого, бо хитрощі їхні — неправда.","Як попіл, Ти відгортаєш нечестивців землі, тому полюбив я свідчення Твої.","Від страху перед Тобою тремтить тіло моє; судів Твоїх я боюся.","Я чинив суд і справедливість, не віддай мене до рук ворогів моїх.","Захисти раба Твого на добро йому, щоб не гнобили мене горді.","Знесилились очі мої виглядати спасіння Твоє і слова правди Твоєї.","Яви милість Твою слузі Твоєму і постанов Твоїх навчи мене.","Я — раб Твій, дай мені розуміння, щоб я зрозумів свідчення Твої.","Прийшов час відплати Твоєї, Господи, бо безбожні зневажили закон Твій.","Я ж полюбив заповіді Твої більше, аніж золото і дороге каміння.","Всі повеління Твої визнаю справедливими, а дорогу неправди ненавиджу.","Дивні свідчення Твої, Господи, тому й додержується їх душа моя.","Об’явлене слово Твоє просвітлює і врозумляє немовлят.","Відкриваю уста мої і, як повітря, втягую в себе заповіді Твої, бо так їх жадаю.","Зглянься на мене і помилуй мене, як милуєш тих, що люблять ім’я Твоє.","Стопи мої направ за словом Твоїм, і нехай не оволодіє мною ніяке беззаконня.","Спаси мене від наклепів людських, і я буду сповняти заповіді Твої.","Осяй раба Твого світлом лиця Твого і навчи мене заповітів Твоїх.","Потоки сліз течуть з очей моїх, бо люди не додержують закону Твого.","Праведний Ти, Господи, і справедливі суди Твої.","Свідчення Твої, що їх заповідав Ти, — правда і чиста істина.","Ревність моя за Тебе сушить мене, бо вороги мої забули слова Твої.","Розпалене й чисте слово Твоє, і я — раб Твій — полюбив Його.","Малий я і принижений, але повелінь Твоїх я не забув.","Правда Твоя — правда вічна, і закон Твій — істина.","Скорбота й горе прийшли на мене, та заповіді Твої — утіха моя.","Правда свідчень Твоїх — вічна; дай мені зрозуміти їх, і я буду жити.","Від усього серця [мого] взиваю я; почуй мене, Господи, заповіти Твої я сповнятиму.","Взиваю до Тебе: спаси мене, буду сповняти накази Твої.","Раніше світанку взиваю я; на слово Твоє я уповаю.","Раніше ранку відкриті очі мої, щоб навчатися слів Твоїх.","Почуй, Господи, голос мій з милости Твоєї і за судом Твоїм оживи мене.","Наблизилися до мене ті, що замислили зло; від закону Твого вони далеко стали.","Ти ж, Господи, близько від мене, і всі заповіти Твої — істина.","Віддавна я знаю свідчення Твої, що їх навіки встановив Ти.","Зглянься на горе моє і визволи мене, бо я закону Твого не забув.","Розсуди справу мою і захисти мене; за словом Твоїм оживи мене.","Далеко від нечестивців спасіння, бо вони не визнають закону Твого.","Велика щедрість Твоя, Господи; оживи мене праведним судом Твоїм.","Багато в мене напасників і гнобителів, але я від свідчень Твоїх не відхилився.","Бачу я безбожних і тяжко мені, що вони відступили від слова Твого.","Глянь, як люблю я заповіді Твої; з милости Твоєї, Господи, оживи мене.","Основа слів Твоїх — істина, і вічні всі суди правди Твоєї.","Князі безвинно гонять мене, але серце моє боїться слова Твого.","Радію я від слів Твоїх, як той, що одержав велике багатство.","Неправду я зненавидів і гидую нею, закон же Твій я люблю.","Семикратно кожного дня я прославляю Тебе за суди правди Твоєї.","Великим миром утішаються ті, що люблять закон Твій, і не спотикаються вони.","Я уповаю на спасіння Твоє, Господи, і сповняю заповіді Твої.","Душа моя додержує свідчень Твоїх, бо вельми люблю їх.","Я охороняю заповіді Твої і свідчення Твої, бо всі дороги мої перед Тобою, Господи.","Нехай дійде молитва моя до Тебе, Господи, за словом Твоїм врозуми мене.","Нехай прийде благання моє до Тебе, Господи, за словом Твоїм визволи мене.","Висловлять уста мої пісню хвали, коли навчиш мене заповітів Твоїх.","Язик мій буде голосно провіщати слова Твої, бо всі заповіді Твої — правда.","Нехай стане рука Твоя на поміч мені, бо я обрав собі повеління Твої.","Я жадаю спасіння Твого, Господи, і закон Твій — утіха моя.","Нехай живе душа моя і славить Тебе, і суди Твої нехай допоможуть мені.","Я блукаю, наче ягня загублене. Знайди раба Твого, бо я заповідей Твоїх не забув."],"h":"[Алилуя.]","x":{"2":"25.18.12","3":"53.5.18","4":"4.4.5-6","5":"52.1.6","6":"58.2.3|65.6.16","9":"53.15.3|56.1.22","10":"31.63.17","11":"4.6.6","18":"4.17.19","19":"12.29.15|75.11.13","21":"4.11.28","23":"25.2.2","24":"4.17.19","30":"10.8.36","32":"52.19.6","34":"17.9.20","36":"8.8.3","37":"50.18.9","39":"50.6.13","44":"53.15.10","46":"62.1.16","50":"25.18.8|32.15.16","51":"4.17.11","55":"25.62.7","57":"3.18.20","61":"68.2.8","62":"54.16.25","63":"30.37.15","64":"25.32.5","67":"75.12.10","70":"50.13.15","71":"64.7.10","72":"25.118.127","73":"24.10.8","75":"76.19.2","81":"25.118.166","83":"24.30.30","86":"53.17.17","89":"31.40.8|50.24.35","92":"25.18.8|32.15.16","97":"4.17.19","99":"4.4.6","100":"29.8.10","103":"25.18.11","104":"25.118.128","105":"57.1.19","106":"17.10.29|24.27.5","108":"25.18.15","110":"25.139.6","112":"10.8.58","115":"25.6.9|25.100.4","116":"25.24.2","118":"62.8.6-7","120":"52.12.5|54.5.5","124":"25.142.2","126":"27.8.11","127":"25.18.11","128":"25.118.104","130":"25.18.9|50.11.25","132":"25.6.5","135":"25.66.2","136":"55.4.9","137":"1.9.27","138":"4.4.5-6","139":"25.68.10","140":"9.22.31|26.30.5","142":"53.17.17","147":"25.5.4|25.87.14","148":"31.26.9","151":"53.17.17","152":"50.5.18|56.1.25","154":"25.36.6","155":"25.108.17","157":"25.3.1-2","158":"54.17.16","161":"31.66.2","162":"31.9.3","163":"25.100.7","165":"65.6.16|58.2.10","166":"0.49.18","168":"25.138.3","176":"31.53.6|56.2.25"}},{"v":["До Господа взивав я в скорботі моїй, і Він вислухав мене.","Господи, визволи душу мою від уст неправдивих, від язика облесливого.","Що дасть Тобі або що додасть Тобі язик зрадливий?","Він — як гострі стріли сильного з палаючим вугіллям, що спустошує.","Горе мені, що я перебуваю у Мосоха, живу біля шатрів кидарських.","Довго перебувала душа моя з тими, що не бажають миру.","Я бажаю жити мирно, але, як тільки заговорю до них, вони повстають проти мене без вини."],"h":"Пісня ступенів.","x":{"1":"25.49.15","2":"8.26.19","3":"55.3.5","4":"25.58.8|25.64.4|26.25.18","7":"62.3.17"}},{"v":["Звів я очі мої в гори, звідкіля прийде поміч моя.","Поміч моя від Господа, що створив небо і землю.","Він не дасть нозі твоїй спіткнутися, не задрімає Охоронитель твій.","Не задрімає і не засне Той, Хто охороняє Ізраїля.","Господь — Охорона твоя, Господь — покрова твоя на правиці твоїй.","Удень сонце не опалить тебе, а вночі — місяць.","Господь охоронить тебе від усякого зла, охоронить душу твою [Господь].","Господь охоронить вхід і вихід твій віднині й навіки."],"h":"Пісня ступенів.","x":{"1":"13.20.12","2":"13.20.17|25.123.8","4":"10.8.52","6":"29.18.3|42.4.8"}},{"v":["Звеселився я тим, що сказали мені: ходімо до дому Господнього.","Стояли ноги наші у дворах твоїх, Єрусалиме.","Єрусалим створений як місто, і доля його з народом його.","Бо туди увійшли коліна, коліна Господні, за законом Ізраїля, щоб прославляти ім’я Господнє.","Бо там стоять престоли, щоб судити, престоли в домі Давидовому.","Просіть про мир для Єрусалима, і благоденство тим, що люблять тебе.","І нехай буде мир силою твоєю і благоденство у стінах твоїх.","Заради братів моїх і ближніх моїх промовляю: мир тобі.","Заради дому Господа Бога нашого жадаю я блага тобі."],"h":"Пісня ступенів. Давида.","x":{"3":"13.6.6|32.31.4","5":"10.7.7","6":"48.4.7|31.66.10","9":"62.15.2"}},{"v":["До Тебе, що перебуваєш на небі, зводжу очі мої.","Як очі рабів звертаються до рук господарів їхніх, як очі рабині до рук господині її, так очі наші — до Господа Бога нашого, аж поки помилує нас.","Помилуй нас, Господи, помилуй нас, бо багато ми маємо приниження.","Надміру має душа наша ганьби від багатих та зневаги від гордих."],"h":"Пісня ступенів.","x":{"1":"25.120.1","2":"13.20.12","4":"25.87.4|75.11.36"}},{"v":["Якби не Господь був з нами, — нехай скаже Ізраїль,","якби не Господь був з нами, коли повстали проти нас люди, —","вони б живих поглинули нас, коли гнів їх розпалився на нас.","Вода б затопила нас; потоки залили б душу нашу.","Бурхливі хвилі води прийшли б над душею нашою.","Благословен Господь, Який не дав нас на здобич у зуби їхні.","Душа наша, як пташка, вирвалася з сітки тих, що ловили. Сітка розірвалась, і ми спаслися.","Поміч наша в імені Господа, що створив небо і землю."],"h":"Пісня ступенів. Давида.","x":{"3":"26.1.12","4":"25.143.7","7":"25.10.2|26.6.5","8":"25.120.2|17.9.6"}},{"v":["Ті, що надіються на Господа, не похитнуться, як гора Сион, що стоїть вічно.","Гори навкруги Єрусалима, а Господь — навкруги народу Свого віднині і навіки.","Бо не залишить [Господь] жезла нечестивих над долею праведних, щоб праведні не простягли рук своїх до беззаконня.","Благодій, Господи, добрим і праведним серцем.","А тих, що звернули на криву дорогу неправди, нехай залишить Господь разом з тими, що чинять беззаконня. Мир на Ізраїля!"],"h":"Пісня ступенів.","x":{"1":"26.16.20|26.28.25|31.33.20","3":"54.22.30","4":"25.7.11|25.111.4","5":"25.127.6|65.6.16"}},{"v":["Коли повертав Господь з полону Сион, нам здавалося, що то був сон.","Тоді були душі наші повні радости, і з уст наших лилася пісня. Тоді між народами говорили: «Велике сотворив Господь над ними».","Так, Господь явив над нами велике; ми раділи серцем.","Поверни ж, Господи, невільників наших, як потоки на південь.","Ті, що сіють зі сльозами, пожнуть з радістю.","Хто з плачем ніс сіяти зерно своє, той повернеться веселий, несучи снопи свої."],"h":"Пісня ступенів.","x":{"1":"31.26.1|32.33.26","3":"52.1.49","4":"32.29.14|32.30.3|32.31.23","6":"31.66.13|50.5.4|52.16.25"}},{"v":["Коли не Господь будує дім, даремно трудяться будівничі; коли не Господь береже місто, даремно пильнує сторожа.","Даремно встаєте ви рано і лягаєте пізно, їсте хліб, тяжко здобутий, тоді як Господь дає улюбленим Своїм спокійний сон.","Ось і діти — насліддя від Господа; нагорода від Нього — плід утроби.","Як стріли в руках сильного, так і сини молоді.","Блаженний, хто здобув таку поміч собі. Не осоромляться вони, коли біля брами міста свого говоритимуть з ворогами."],"h":"Пісня ступенів. Соломона.","x":{"1":"26.14.11|63.3.6","2":"53.21.3|36.12.19","3":"8.1.27"}},{"v":["Блаженні всі, що бояться Господа. Ті, що ходять путями Його.","Ти житимеш трудами рук твоїх. Блаженний ти, і добро тобі буде.","Жона твоя в домі твоїм як родюча лоза виноградна. Сини твої, як паростки дерева оливкового, навколо трапези твоєї.","Ось так буде благословенний чоловік, що боїться Господа.","Нехай благословить тебе Господь від Сиону. І побачиш блаженство Єрусалима по всі дні життя твого.","Щоб побачив ти дітей синів твоїх. Мир на Ізраїля!"],"h":"Пісня ступенів.","x":{"1":"25.111.1","2":"0.3.19","3":"25.143.12","4":"4.28.2","5":"3.6.24","6":"25.124.5"}},{"v":["Багато разів бороли мене від юности моєї, — нехай скаже Ізраїль,","багато разів бороли мене від юности моєї, але не перемогли мене.","На хребті моїм орали плугарі, проклали довгі борозни свої,","але Господь справедливий, Він розсік пута беззаконників.","Нехай осоромляться і відступлять ті, що ненавидять Сион.","Нехай будуть як трава на покрівлі, що сохне раніше, ніж вирвуть її,","якою жнець не наповнює руки своєї, і в’язальниця не зв’яже снопа.","А перехожі не скажуть: «Благословення Господнє на вас; благословляємо вас іменем Господнім»."],"h":"Пісня ступенів.","x":{"2":"64.4.8","3":"24.4.8|31.51.23","4":"31.5.8","5":"25.6.11","6":"25.36.2|25.57.10"}},{"v":["З глибини взиваю до Тебе, Господи, Господи, почуй голос мій.","Нехай будуть вуха Твої уважні до голосу благання мого.","Якщо на беззаконня наші зважатимеш, Господи, Господи, хто встоїть?","Але у Тебе прощення; нехай благоговіють перед Тобою.","Ради імені Твого я надіюся на Тебе, Господи; терпіла душа моя у слові Твоїм. Уповає душа моя на Господа.","Від ранньої зорі до ночі, від ранньої зорі нехай уповає Ізраїль на Господа.","Бо у Господі милість і велике у Нього визволення,","і Він визволить Ізраїля від усіх беззаконь його."],"h":"Пісня ступенів.","x":{"1":"25.68.2","2":"25.5.2","3":"25.142.2","4":"37.9.9","6":"45.2.3","8":"31.43.25|31.44.22"}},{"v":["Господи, не зазнавалося серце моє, не підносилися гордо очі мої; я не входив у велике і дивне, недосяжне для мене.","Чи не смиряв я душу свою, наче дитину, відлучену від грудей матері? Душа моя в мені жадає Тебе, як дитя грудей матері своєї.","Нехай надіється Ізраїль на Господа віднині і навіки."],"h":"Пісня ступенів. Давида.","x":{"1":"9.6.22|26.16.5","2":"62.12.16"}},{"v":["Пом’яни, Господи, Давида і всю лагідність його.","Як він присягався Господу, давав обітниці Богу Якова:","«Не ввійду в світлицю дому мого, не ляжу на постіль мою,","не дам заснути очам моїм і задрімати повікам моїм;","не заспокоюся, поки не знайду оселі для Господа, дому для Бога Якова».","Ось ми чули про Нього в Єфрафі, знайшли Його на полях Іарима.","Ходімо в оселі Його, поклонімося підніжжю ніг Його.","Воскресни, Господи, у спокій Твій, Ти і кивот святині Твоєї.","Священики Твої зодягнуться в правду, і преподобні Твої зрадіють.","Ради Давида, раба Твого, не відверни лиця від помазаника Твого.","Клявся Господь Давиду істиною і не зречеться її: «Із синів роду твого посаджу на престолі твоїм.","А коли сини твої зберігатимуть завіт Мій і повеління Мої, яких Я навчу їх, то й сини їхні навіки сидітимуть на престолі твоїм».","Вибрав Господь Сион, забажав [його] на оселю для Себе.","«Це місце спокою Мого повік віку, сказав Господь, тут оселюся, бо Я полюбив його.","Поживу його Я, благословляючи, благословлю, і вбогих його Я нагодую хлібом.","Священиків його Я зодягну в спасіння, і праведні його будуть радіти радістю.","Там Я вирощу спасіння Давидові, поставлю світильник помазанику Моєму.","Ворогів його осоромлю Я, на ньому ж розцвіте святиня Моя»."],"h":"Пісня ступенів.","x":{"1":"17.13.14","3":"9.7.2-3|10.8.17","4":"26.6.4","5":"54.7.46","6":"8.7.1","7":"25.17.7","8":"13.6.41","10":"13.6.42","11":"9.7.12|10.8.25|13.6.16|25.88.5|52.1.55|54.2.30","13":"10.9.3","14":"10.8.13","15":"25.36.19|25.110.5","17":"8.2.10|49.3.1|52.1.69","18":"25.34.26"}},{"v":["Як то добре і як то гарно, коли брати живуть у згоді!","Як миро на голові, що сходить на бороду, на бороду Ааронову, що сходить на краї одежі його.","Як роса єрмонська, що спадає на гори Сионські. Бо там посилає Господь благословення і життя навіки."],"h":"Пісня ступенів. Давида.","x":{"1":"30.25.2|51.9.5","2":"1.29.7|2.8.12","3":"4.3.8|28.4.8"}},{"v":["Нині благословляйте Господа, всі раби Господні, що стоїте у храмі Господнім, [у дворах дому Бога нашого].","Вночі підносьте руки ваші до святині і благословляйте Господа.","Благословить і тебе з небесного Сиону Господь, Який створив небо і землю."],"h":"Пісня ступенів.","x":{"1":"25.112.1|25.134.2","3":"3.6.24|25.127.5"}},{"v":["Хваліть ім’я Господнє, хваліть, раби Господні,","що стоїте у храмі Господнім, у дворах дому Бога нашого.","Хваліть Господа, бо Господь благий; співайте імені Його, бо це добре.","Господь обрав Собі Якова, — обрав Ізраїля у насліддя Собі.","Я пізнав, що Господь великий, і що Бог наш над усіма богами.","Все, що хоче, Господь творить на небесах і на землі, в морях і у всіх безоднях;","підносить хмари від країв землі, сяє блискавкою серед дощу, виводить вітри зі сховищ Своїх.","Він умертвив первістків у Єгипті від людей до тварин,","явив знамення й чудеса посеред тебе, Єгипте, над фараоном і над усіма рабами його,","уразив багато народів і знищив могутніх царів:","Сигона, царя Аморрейського, і Ога, царя Васанського, і всі царства ханаанські;","і віддав землю їх у насліддя Ізраїлю, в насліддя людям Своїм.","Господи, ім’я Твоє навіки, і пам’ять про Тебе з роду в рід.","Бо Господь буде судити народ Свій і змилосердиться над рабами Своїми.","Ідоли язичників — срібло й золото, творіння рук людських.","Мають уста і не говорять, мають очі і не бачать,","мають вуха і не чують, і нема дихання в устах їх.","Подібні до них будуть і ті, що роблять їх, і ті, що надіються на них.","Доме Ізраїлів! Благословляйте Господа. Доме Ааронів, благословляйте Господа!","Доме Левія, благословляйте Господа. Всі, хто боїться Господа, благословляйте Господа.","Благословен Господь від Сиона, що живе в Єрусалимі. Алилуя!"],"h":"Алилуя.","x":{"1":"25.112.1","3":"25.135.1","4":"4.7.6|56.2.9|73.2.14","6":"25.113.11|37.4.32","7":"32.10.13|32.14.22","8":"1.12.29|25.77.51","11":"5.12.7","15":"25.113.12","16":"29.15.15","18":"31.42.17","21":"25.49.2|25.109.2|31.2.3"}},{"v":["Прославляйте Господа, бо Він благий, бо повіки милість Його.","Прославляйте Бога богів, бо повіки милість Його.","Прославляйте Господа володарів, бо повіки милість Його.","Він Один творить чудеса великі, бо повіки милість Його.","Він створив небеса премудро, бо повіки милість Його;","утвердив землю на водах, бо повіки милість Його.","Він створив великі світила, бо повіки милість Його;","сонце, щоб творило день, бо повіки милість Його;","місяць і зорі, щоб світили вночі, бо повіки милість Його;","покарав Єгипет у первістках його, бо повіки милість Його;","і вивів з нього Ізраїля, бо повіки милість Його;","рукою кріпкою і силою могутньою, бо повіки милість Його;","Він розділив море Червоне, бо повіки милість Його;","і провів Ізраїля посеред нього, бо повіки милість Його;","і потопив фараона й військо його у морі, бо повіки милість Його;","Він провів народ Свій через пустелю, бо повіки милість Його;","і покарав царів великих, бо повіки милість Його;","знищив царів сильних, бо повіки милість Його;","Сигона, царя аморреїв, бо повіки милість Його;","і Ога, царя Васанського, бо повіки милість Його;","і віддав землю їх у насліддя, бо повіки милість Його;","в насліддя Ізраїлю, рабу Своєму, бо повіки милість Його;","Він пом’янув нас у смиренні нашому, бо повіки милість Його;","і визволив нас від ворогів наших, бо повіки милість Його;","Він дає поживу всім творінням, бо повіки милість Його.","Прославляйте Бога Небесного, бо повіки милість Його."],"h":"[Алилуя.]","x":{"1":"12.16.34|13.5.13","2":"4.10.17","4":"25.71.18","5":"0.1.7-8|25.145.6|30.18.1","6":"0.1.9-10|32.10.12|32.51.15","7":"25.148.3:5","8":"0.1.16","10":"1.12.29","11":"1.12.41","12":"1.13.3|4.4.34","13":"1.14.21","14":"1.14.22","15":"1.14.28","20":"5.12.4","25":"25.103.27|25.146.9"}},{"v":["На ріках вавилонських, там ми сиділи і плакали, коли згадували Сион наш.","На вербах посеред нього повісили ми арфи наші.","Там бо питали нас про слова пісень полонителі наші, що знали про наш спів: «Заспівайте нам пісень сионських».","Як же нам співати пісню Господню на землі чужій?","Якщо забуду тебе, Єрусалиме, нехай буде забута правиця моя.","Нехай прилипне язик мій до гортані моєї, якщо не пом’яну тебе і коли не поставлю Єрусалим початком радости моєї.","Пом’яни, Господи, синів Едомських, що в день єрусалимський кричали: «Руйнуйте його до останку».","Дочко Вавилона, окаянна, блаженний той, хто відплатить тобі за все, що ти заподіяла нам.","Блаженний, хто візьме і розіб’є дітей твоїх об камінь."],"h":"Давида.] (Пісня перед Богом про неволю прор. Єремії).","x":{"1":"36.1.1|31.30.19","5":"32.51.50","7":"32.49.7|36.25.12|36.35.5","9":"31.13.16"}},{"v":["Прославляю Тебе, Господи, від усього серця мого. Перед ангелами співатиму похвалу Тобі за те, [що Ти почув усі слова уст моїх].","Буду поклонятися перед святим храмом Твоїм і славити ім’я Твоє за милість Твою і правду Твою, бо Ти звеличив слово Твоє вище від усякого імені Твого.","В день, коли я взивав до Тебе, Ти почув мене і вселив у душу мою силу.","Будуть прославляти Тебе, Господи, всі царі землі, коли почують слова уст Твоїх.","Будуть у піснях прославляти путі Господні, бо велика слава Господня.","Високий Господь: смиренного бачить і гордого пізнає здалека.","Якщо я піду серед напастей, Ти оживиш мене, простягнеш руку Твою на ворогів моїх, і спасе мене правиця Твоя.","Господь воздасть за мене; Господи, милість Твоя повік. Не покидай творіння рук Твоїх."],"h":"Давида. (Аггея й Захарії).","x":{"1":"25.9.2","2":"25.144.1","4":"25.67.33|31.6.3","6":"25.112.6","7":"25.36.24"}},{"v":["Господи, Ти випробував мене і знаєш мене.","Ти знаєш, коли я сяду і коли я встану. Ти наперед знаєш думки мої.","Стежку мою і місце перебування мого Ти визначив, і всі путі мої відомі Тобі.","Ще нема слова на язиці моїм, а вже Ти, Господи, все знаєш.","Ти ствердив мене і поклав на мене руку Твою.","Дивне для мене всевідання [Твоє]; високе воно для мене, і я не можу збагнути його.","Куди піду я від Духа Твого і від лиця Твого куди втечу?","Зійду на небо — Ти там перебуваєш; зійду в пекло — і там Ти.","Чи візьму крила в ранньої зорі і переселюся на самий край моря,","і там рука Твоя поведе мене, і правиця Твоя триматиме мене.","Сказав би я: може, темрява сховає мене, то й темрява стане світлою перед Тобою.","Не сховає від Тебе й темрява, бо й ніч перед Тобою як день; і пітьма перед Тобою як світло.","Ти створив усе нутро моє, витворив мене в утробі матері моєї.","Прославляю Тебе за те, що Ти так дивно створив мене. Дивні діла Твої, і душа моя добре це знає.","Не були втаєні від Тебе кості мої, коли в тайні зачався я, коли в утробі витворювалося тіло моє.","Очі Твої бачили зародок мій, і в книзі Твоїй були записані всі дні, призначені для мене, коли ще й одного з них не було.","О, які величні для мене замисли Твої, Боже! І яка велика кількість їх!","Став би лічити їх, та їх більше, ніж піску; коли я пробуджуюсь, я все ще перед Тобою.","О, коли б Ти, Боже, знищив нечестивого! Відійдіть від мене, кровожерні!","Вороги Твої, Господи, говорять проти Тебе зневажливо; марне замишляють вороги Твої.","Чи ж мені не мати ненависти проти тих, що Тебе, Господи, ненавидять? І чи не цуратися тих, що повстають проти Тебе?","Повною ненавистю ненавиджу їх; ворогами моїми стали вони.","Випробуй мене, Боже, і побач серце моє, досліди думки мої.","Подивись, чи не на шляху я беззаконня і чи на добрій я дорозі? Якщо ні, то настанови мене на путь вічну."],"h":"Начальнику хору. Псалом Давида. (Захарії).","x":{"1":"26.24.12|53.21.17","2":"9.7.20|32.12.3|4.31.21","3":"25.118.168","7":"29.1.7","8":"40.9.2","9":"25.54.7","11":"24.34.22|32.23.24|75.4.13","12":"55.1.17","13":"24.10.11","14":"25.118.71|76.15.3","15":"27.11.5","16":"30.23.29|24.14.5|49.3.16","18":"0.22.17","19":"25.5.7","21":"25.100.3","22":"62.12.9","23":"24.31.6|25.25.2","24":"25.26.11|25.85.11|25.142.8"}},{"v":["Начальнику хору. Псалом Давида.","Спаси мене, Господи, від людей лукавих; захисти мене від гнобителів:","вони замишляють неправду в серці; щодня готуються до битви,","гострять язики свої, як змія, отрута аспида в устах їхніх.","Збережи мене, Господи, від руки беззаконника; захисти від гнобителів, що задумали спинити кроки життя мого.","Горді розставили таємно сіті на мене при дорозі; приготували для мене яму.","Я сказав Господу: Ти — Бог мій! Почуй, Господи, голос моління мого!","Господи, Господи! Сило спасіння мого! Ти покрив голову мою в день битви.","Не допусти, Господи, здійснитися наміру нечестивого; не дай успіху замислам його, щоб вони не загордилися.","Голови тих, що оточили мене, нехай покриє зло уст їхніх.","Нехай впаде на них гаряче вугілля; нехай впадуть вони у вогонь і у безодню, так щоб не встали.","Людина злоязична не утвердиться на землі; злоба приведе гнобителя до загибелі.","Знаю, що Господь учинить суд пригнобленим і справедливість бідним.","І будуть праведні прославляти ім’я Твоє; непорочні оселяться перед лицем Твоїм."],"h":"Псалом.","x":{"4":"25.5.10|25.57.5|62.3.13","5":"9.22.3","6":"25.63.6|25.141.4|32.18.22","9":"4.32.27","10":"25.7.15","11":"25.10.6","12":"30.28.15","13":"25.9.19"}},{"v":["Господи, взиваю до Тебе, вислухай мене. Почуй голос моління мого, коли взиваю до Тебе.","Нехай стане молитва моя як кадило перед Тобою; піднесення рук моїх — як жертва вечірня.","Постав, Господи, охорону устам моїм і двері огорожі в устах моїх.","Не відхили серця мого до слів лукавих — виправдовувати мої гріхи, разом з людьми, що чинять беззаконня, щоб не став я спільником пристрастей їхніх.","Нехай навчає мене праведник милістю, нехай і викриває мене; єлей же слів грішника нехай не намастить голови моєї.","І молитва моя проти злодіянь їхніх. Пожерла земля в безодні суддів їхніх.","Почуті ж були слова мої як переможні; як груддя землі розметалися вони по землі; так розсипалися кості їхні над пеклом.","На Тебе ж, Господи, Господи, звернені очі мої; на Тебе надія моя, не відкинь душі моєї.","Охорони мене від сіті, що її поставили на мене, і від спокус, що їх наставили беззаконні.","У сіть свою впадуть грішники, а я з Тобою її перейду."],"h":"Псалом Давида.","x":{"2":"1.29.39|1.30.7-8","3":"25.38.2|30.22.31","4":"10.8.58|26.1.10:15","5":"26.12.1|26.15.12|26.25.12","9":"25.139.6","10":"25.7.16|25.9.16"}},{"v":["Голосом моїм до Господа взиваю: голосом моїм до Господа молюся.","Розповім Йому всі печалі мої, і скорботу мою Йому сповіщу.","Коли знемагав у мені дух мій, Ти знав стежки мої. На дорозі, де ходив я, поставили сіть на мене.","Дивився я навкруги — і ніхто не впізнавав мене. Не стало захисту, і ніхто не дбав про душу мою.","Я до Тебе взивав, Господи, й казав: Ти — надія моя і доля моя на землі живих.","Вислухай моління моє, бо я дуже знесилений; спаси мене від гонителів моїх, бо вони сильніші за мене.","Виведи з темниці душу мою, щоб славити ім’я Твоє. На мене чекають праведники, поки явиш мені милість Твою."],"h":"Повчання Давида. Молитва його, коли він був у печері.","x":{"1":"8.24.4","2":"25.101.1","3":"25.139.6|32.18.22","4":"26.29.10","5":"25.15.5|25.26.13|25.90.2","7":"25.142.11"}},{"v":["Господи, почуй молитву мою, зглянься на моління моє в істині Твоїй, вислухай мене у правді Твоїй.","І не входь у суд з рабом Твоїм, бо не виправдається перед Тобою ніхто з живих.","Бо ворог переслідує душу мою, втоптав у землю життя моє, посадив мене в темряву, як давно померлих.","І впав у мені дух мій, стривожилось у мені серце моє.","Я згадую дні давні, розмірковую про всі діла Твої і в творінні рук Твоїх повчаюся.","До Тебе простягаю руки мої: душа моя, як земля безводна, перед Тобою.","Скоро почуй мене, Господи, згасає дух мій. Не відверни лиця Твого від мене, бо уподібнюся тим, що сходять у могилу.","Дай мені зрання відчути милість Твою, бо на Тебе уповаю. Вкажи мені, [Господи], путь, якою піду, бо до Тебе підношу душу мою.","Визволи мене від ворогів моїх, Господи, до Тебе вдаюся,","навчи мене творити волю Твою, бо Ти єси Бог мій. Дух Твій благий наставить мене на землю правди;","імені Твого ради, Господи, оживи мене правдою Твоєю. Виведи з печалі душу мою","і милістю Твоєю знищ ворогів моїх. І вигуби гнобителів душі моєї, бо я раб Твій є."],"h":"Псалом Давида, [коли його переслідував син — Авессалом.]","x":{"2":"24.9.2-3|24.15.14|24.25.4","3":"8.23.14","5":"25.76.6","6":"25.27.2","7":"25.27.1","8":"25.85.11","10":"17.9.20","11":"25.26.11|25.141.7"}},{"v":["Благословенний Господь Бог мій, що навчає руки мої до боротьби і пальці мої до битви.","Він — милість моя і охорона моя; твердиня моя і Спаситель мій; Він — щит мій, і я надіюся на Нього; Він прихиляє народ мій до мене.","Господи! Що таке людина, що Ти виявляєш їй Себе, і сини людські, що Ти піклуєшся про них?","Людина — як подих вітру; дні її — як тінь, що зникає.","Господи! Прихили небо Твоє і зійди; торкнися гір — і з них піде дим.","Блисни блискавкою — і розжени ворогів моїх; пусти стріли Твої — і розвій їх.","Простягни руку Твою з висоти, визволи мене і спаси мене з вод великих, — з руки синів чужих,","що їх уста говорять марноту, а правиця їхня повна неправди.","Боже! Нову пісню Тобі співаю; на десятиструннім псалтирі буду співати Тобі,","бо Ти даєш спасіння царям; визволив Давида, раба Твого, від меча лютого.","Визволи мене і спаси мене від руки синів чужих, що їхні уста говорять марноту, а правиця їхня повна неправди.","Нехай сини наші будуть як розквітлі рослини у молодості своїй; і дочки наші нехай будуть прибрані й прикрашені, як стовп у царських палатах.","Нехай житниці наші будуть повні і всяким хлібом багаті. Нехай множаться тисячами вівці на пасовищах наших.","Нехай воли наші будуть ситі, і не буде ні розкрадання, ні пропажі, ні стогону на вулицях наших.","Блаженний народ, у якого все це є. Блаженний народ, у якого Господь — Бог його."],"h":"Псалом Давида. [Проти Голіафа.]","x":{"1":"9.22.35","2":"9.22.47","3":"24.7.17|25.8.5|75.2.6","4":"24.8.9|24.14.2","5":"9.22.10","7":"25.123.4","9":"25.32.2|31.5.1|76.5.9","10":"26.21.31|21.3.19","12":"36.24.25","13":"52.12.16","14":"52.14.19","15":"25.32.12"}},{"v":["Величатиму Тебе, Боже мій, Царю [мій], і благословлятиму ім’я Твоє повіки й повік віку.","Кожного дня благословлятиму Тебе і хвалитиму ім’я Твоє повіки й повік віку.","Великий Господь і преславний, і немає меж величі Його.","З роду в рід будуть прославляти діла Твої і сповіщати про могутність Твою,","а я буду говорити про велич слави святині Твоєї і розповідати про чуда Твої.","Скажуть про силу дивних діянь Твоїх, і я розповідатиму про велич Твою.","Будуть проголошувати пам’ять великої благости Твоєї і правдою Твоєю будуть радуватися.","Щедрий і милостивий Господь, довготерпеливий і многомилостивий.","Благий Господь до всіх, і милість Його на всіх ділах Його.","Нехай славлять Тебе, Господи, всі діла Твої, і святі Твої нехай благословляють Тебе.","Нехай скажуть про славу Царства Твого і проповідують про силу Твою,","щоб дізналися сини людські про могутність Твою і про славну велич Царства Твого.","Царство Твоє — Царство всіх віків, і влада Твоя через усі роди. [Вірний Господь у всіх словах Своїх і праведний у всіх ділах Своїх.]","Зміцнює Господь усіх, що падають, і піднімає тих, що впали.","Очі всіх з надією на Тебе, Господи, дивляться, і Ти даєш їм поживу в час свій.","Відкриваєш руку Твою і насичуєш усі творіння благами Твоїми.","Праведний Господь у всіх путях Своїх і благий у всіх ділах Своїх.","Господь близько до всіх, хто призиває Його, хто призиває Його праведно.","Він сповняє бажання тих, що бояться Його, чує молитву їхню і спасає їх.","Господь охороняє всіх, що люблять Його, а всіх нечестивців знищить.","Хвалу Господню будуть виголошувати уста мої. І всі творіння нехай прославляють ім’я Його повік віку."],"h":"Хвала Давида.","x":{"1":"25.46.3","3":"24.5.9|24.36.26","4":"4.4.10|4.6.7","8":"1.34.6|25.85.15","9":"30.18.12|57.3.9|71.2.4","11":"25.46.9","13":"25.145.10|37.4.32|37.6.26","14":"25.36.24","15":"25.103.27","16":"24.39.2","18":"4.4.7","19":"25.146.11","20":"8.2.9"}},{"v":["Хвали, душе моя, Господа! Буду хвалити Господа, поки й життя мого.","Співатиму Богові моєму, поки й живу.","Не надійтеся на князів, на синів людських, в них нема спасіння.","Вийде дух його і вернеться в землю свою; в той день загинуть усі помисли його.","Блажен, кому Бог Якова — помічник його; у кого надія на Господа Бога свого,","що створив небо і землю, море і все, що в них; Він береже істину повік,","творить суд покривдженим, дає поживу голодним.","Господь визволяє закованих, Господь умудряє сліпців, Господь підносить повалених, Господь любить праведників;","Господь охороняє пришельців; сироту і вдову прийме, а путь грішників погубить.","Царюватиме Господь повіки, Бог твій, Сионе, з роду в рід. Алилуя."],"h":"[Алилуя. Аггея й Захарії.]","x":{"1":"25.102.1","3":"25.117.9","4":"0.3.19|27.12.7","5":"25.33.9","6":"25.135.5|54.14.15|76.14.7","7":"25.11.6|25.103.27","8":"52.18.35","9":"25.67.6","10":"1.15.18"}},{"v":["Хваліть Господа, бо благо співати Богу нашому: нехай буде Йому насолодою наша хвала.","Господь будує Єрусалим, і розсіяних людей Своїх збере.","Він зціляє розбитих серцем і перев’язує рани їхні.","Знає кількість усіх зірок, і всіх їх за іменами називає.","Великий Господь наш, і велика сила [Його], і розуму Його немає числа.","Смиренних підносить Господь, а нечестивих принижує до землі.","Співайте Господу хвалу, співайте Богу нашому на гуслях.","Він покриває небо хмарами і посилає на землю дощ, вирощує на горах траву [і всяку рослину на поживу людям].","Дає поживу тваринам і всім птахам, що прославляють Його.","Не на силу коня дивиться Він, і не на швидкість людських ніг зважає.","Господь любить тих, що бояться Його і уповають на милість Його."],"h":"[Алилуя.] (Аггея й Захарії.)","x":{"1":"25.91.2","2":"25.50.20|31.60.10","3":"31.61.1","4":"31.40.26","5":"25.144.3|31.40.28","6":"25.145.8","8":"54.14.17","9":"24.38.41|25.103.14|50.6.26","11":"54.10.35"}},{"v":["Прославляй, Єрусалиме, Господа! Хвали Бога твого, Сионе!","Бо Він укріпив засуви врат твоїх, і благословив синів твоїх у тобі.","Він утвердив у межах твоїх мир і поживною пшеницею насичує тебе.","Він посилає слово Своє на землю, і скоро поширюється слово Його.","Сипле сніг Свій, як вовну, іній, як попіл, розсипає.","Кидає град Свій грудками, а проти морозів Його хто встоїть?","Пошле слово Своє, і розтануть вони; подме вітер Його, і потечуть води.","Він сповістив слово Своє Якову, і суди Свої — Ізраїлю.","Не вчинив Він цього нікому іншому з народів, і судів Його вони не знають."],"h":"(Аггея й Захарії.)","x":{"3":"4.32.14","5":"30.43.19","7":"25.32.9","8":"54.13.17","9":"4.29.29|4.33.4|62.2.3"}},{"v":["Хваліть Господа з небес! Хваліть Його у вишніх.","Хваліть Його, всі ангели Його, хваліть Його, всі Сили Його.","Хваліть Його, сонце й місяць, хваліть Його, всі зорі й світло.","Хваліть Його, небеса небес; і вода, що вище небес.","Нехай хвалять ім’я Господнє, бо Він [промовив — і сталося,] Він повелів — і створилося.","Поставив їх на віки вічні; дав їм закон, що не змінюється.","Хваліть Господа від землі: всі моря, всі риби і всі безодні.","Хваліть Його вогонь, град, сніг, туман, вітер буйний, що виконує волю Його;","хваліть Його гори і всі горби, дерева плодові і всі ліси,","звірі і всі тварини, всі плазуни і птахи крилаті,","царі земні і всі народи, князі і всі судді,","юнаки й діви, старі з молодими —","нехай хвалять ім’я Господнє, бо прославилось ім’я Його Одного. Слава Його на небі і на землі.","Він підніс силу людей Своїх, славу всіх святих Своїх, синів Ізраїлевих, близьких Йому. Алилуя."],"h":"[Алилуя.]","x":{"1":"76.5.13","2":"52.2.13","4":"0.1.7|25.101.1","5":"0.1.6-7|25.135.5|32.10.12|32.51.15","8":"24.37.10","11":"25.48.3","13":"31.12.4","14":"25.131.17"}},{"v":["Співайте Господу пісню нову! Хвала Йому в Церкві преподобних Його.","Нехай звеселиться духовний Ізраїль Сотворителем своїм, сини Сиону нехай возрадуються Царю своєму.","Нехай хвалять ім’я Його хором, з тимпанами і гуслями нехай співають Йому,","бо любить Господь людей Своїх і покірних підносить до спасіння.","Нехай звеличаться преподобні у славі і зрадіють в оселях своїх.","Нехай буде хвала Богові в устах їхніх, і мечі двогострі в руках їхніх,","щоб учинити помсту над нечестивими і кару над беззаконними;","зв’язати царів їхніх путами і славних їхніх — кайданами залізними,","вчинити над ними суд написаний. Слава ця буде всім святим Його. Алилуя."],"h":"[Алилуя.]","x":{"1":"25.32.3","2":"25.92.1|43.2.13","4":"25.146.11","5":"25.41.9","6":"64.10.4","7":"43.4.3|43.5.15","9":"4.4.6|4.32.35"}},{"v":["Хваліть Бога в святих Його, хваліть Його в утвердженні сили Його.","Хваліть Його в могутності сили Його; хваліть його за безмежну велич Його.","Хваліть Його голосом сурми; хваліть його на арфі і гуслях.","Хваліть Його хором під тимпани; хваліть його на струнах і органах.","Хваліть Його на органах милозвучних; хваліть Його на органах і зі співами.","Все, що дише, нехай хвалить Господа. Алилуя."],"h":"[Алилуя.]","x":{"1":"25.105.1","3":"25.46.2","4":"25.149.3","6":"76.5.13"}},{"v":["Я був найменшим серед братів моїх і наймолодшим у домі батька мого; пас овець батька мого.","Руки мої зробили орган, пальці мої настроювали псалтир.","І хто сповістить Господу моєму? Сам Господь, Сам почув.","Він послав ангела Свого і взяв мене від овець батька мого, і помазав мене єлеєм помазання Свого.","Брати мої прекрасні і великі, але Господь не благозволив обрати з них.","Я вийшов назустріч іноплеміннику, і він прокляв мене ідолами своїми.","Але я, вихопивши у нього меч, обезглавив його і звільнив від ганьблення синів Ізраїлевих.]"],"h":"[Псалом Давида на поєдинок з Голіафом*"}];
export default C;
